def request_group(kind, indicator_id=None):
    if kind not in KINDS:
        fail("SOURCE_KIND", "Choose an original sources, countries, indicators or data collection.")
    if indicator_id is None:
        return kind
    if kind != "indicators":
        fail("SOURCE_GROUP", "Only indicator metadata has a selected indicator request group.")
    return "indicators:" + identifier(indicator_id, "indicator id").upper()


def page_order(page):
    if not isinstance(page, dict):
        fail("SOURCE_IMPORT", "Each original source page must be an object.")
    group = request_group(page.get("kind"), page.get("indicatorId"))
    number = page.get("page")
    if isinstance(number, bool) or not isinstance(number, int) or number < 1:
        fail("SOURCE_PAGE_ORDER", "Use the original positive integer page number within each request group.")
    return KINDS.index(page["kind"]), group, number


def text(value, name, maximum=20000):
    if not isinstance(value, str) or len(value) > maximum or "\x00" in value:
        fail("WORKSPACE_TEXT", "Provide valid " + name + ".")
    return value


def page_window(data, default=100):
    offset, limit = data.get("offset", 0), data.get("limit", default)
    if isinstance(offset, bool) or not isinstance(offset, int) or offset < 0:
        fail("WORKSPACE_PAGE", "Offset must be a nonnegative integer.")
    if isinstance(limit, bool) or not isinstance(limit, int) or not 1 <= limit <= 1000:
        fail("WORKSPACE_PAGE", "Limit must be an integer from 1 to 1,000.")
    return offset, limit


def regular(path, root=None):
    path = Path(path)
    if root is not None:
        try:
            path.relative_to(root)
        except ValueError:
            fail("WORKSPACE_PATH", "The selected file is outside the original workspace.")
    if path.is_symlink() or path.resolve() != path.absolute() or not path.is_file():
        fail("WORKSPACE_FILE", "Use original regular files without symbolic links.")
    return path


def read_bytes(path, maximum=256 * 1024 * 1024):
    path = regular(path)
    with path.open("rb") as handle:
        before = os.fstat(handle.fileno())
        raw = handle.read(maximum + 1)
        after = os.fstat(handle.fileno())
    if len(raw) > maximum or len(raw) != before.st_size or before.st_size != after.st_size or before.st_mtime_ns != after.st_mtime_ns:
        fail("WORKSPACE_FILE_CHANGED", "The original file changed during its read or exceeds the supported file size.")
    return raw


def immutable(path, raw):
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True, mode=0o700)
    if path.parent.resolve() != path.parent.absolute():
        fail("WORKSPACE_PATH", "Use canonical private source directories.")
    try:
        descriptor = os.open(path, os.O_WRONLY | os.O_CREAT | os.O_EXCL | getattr(os, "O_NOFOLLOW", 0), 0o600)
    except FileExistsError:
        if read_bytes(path, max(len(raw), 1)) != raw:
            fail("IMMUTABLE_SOURCE", "The retained file already contains different bytes.", file=path.name)
        return
    try:
        with os.fdopen(descriptor, "wb") as output:
            output.write(raw)
            output.flush()
            os.fsync(output.fileno())
    except BaseException:
        # This call owns the newly created, incomplete file only.
        with contextlib.suppress(FileNotFoundError):
            path.unlink()
        raise
    directory = os.open(path.parent, os.O_RDONLY)
    try:
        os.fsync(directory)
    finally:
        os.close(directory)


def file_descriptor(root, path):
    raw = read_bytes(path)
    return {"path": Path(path).relative_to(root).as_posix(), "bytes": len(raw), "sha256": digest(raw)}


@contextlib.contextmanager
def file_lock(path):
    path = Path(path)
    path.parent.mkdir(parents=True, exist_ok=True, mode=0o700)
    if path.is_symlink():
        fail("WORKSPACE_LOCK", "Use the original local workspace lock.")
    fd = os.open(path, os.O_RDWR | os.O_CREAT | getattr(os, "O_NOFOLLOW", 0), 0o600)
    try:
        try:
            fcntl.flock(fd, fcntl.LOCK_EX | fcntl.LOCK_NB)
        except BlockingIOError:
            fail("OPERATION_ACTIVE", "This original operation is already running.")
        yield
    finally:
        os.close(fd)


def held(path):
    try:
        with file_lock(path):
            return False
    except SourceError as error:
        if error.code == "OPERATION_ACTIVE":
            return True
        raise


class Workspace:
    def __init__(self, directory):
        self.root = Path(directory).absolute()
        if self.root == Path("/") or self.root.resolve() != self.root:
            fail("WORKSPACE_PATH", "Choose a canonical absolute private workspace directory.")
        self.root.mkdir(parents=True, exist_ok=True, mode=0o700)
        for name in ("captures", "catalogs", "exports", "locks"):
            (self.root / name).mkdir(exist_ok=True, mode=0o700)
            if (self.root / name).is_symlink():
                fail("WORKSPACE_PATH", "Keep the original workspace directories without symbolic links.")
        db_path = self.root / "worldbank.sqlite3"
        if db_path.is_symlink():
            fail("WORKSPACE_PATH", "Keep the original regular workspace database.")
        self.db = sqlite3.connect(db_path, timeout=10)
        os.chmod(db_path, 0o600)
        self.db.row_factory = sqlite3.Row
        self.db.execute("PRAGMA journal_mode=WAL")
        self.db.execute("PRAGMA foreign_keys=ON")
        self.db.executescript("""
          CREATE TABLE IF NOT EXISTS records(
            kind TEXT NOT NULL, id TEXT NOT NULL, revision INTEGER NOT NULL,
            data TEXT NOT NULL, PRIMARY KEY(kind,id));
          CREATE TABLE IF NOT EXISTS history(
            kind TEXT NOT NULL, id TEXT NOT NULL, revision INTEGER NOT NULL,
            data TEXT NOT NULL, PRIMARY KEY(kind,id,revision));
          CREATE TABLE IF NOT EXISTS observations(
            capture TEXT NOT NULL, page INTEGER NOT NULL, position INTEGER NOT NULL,
            observation_key TEXT NOT NULL, data TEXT NOT NULL,
            PRIMARY KEY(capture,page,position));
          CREATE INDEX IF NOT EXISTS observation_identity ON observations(capture,observation_key);
          CREATE TABLE IF NOT EXISTS capture_pages(
            capture TEXT NOT NULL, kind TEXT NOT NULL, request_group TEXT NOT NULL,
            page INTEGER NOT NULL, data TEXT NOT NULL,
            PRIMARY KEY(capture,kind,request_group,page));
        """)
        self.db.commit()
        if "request_group" not in {row["name"] for row in self.db.execute("PRAGMA table_info(capture_pages)")}:
            # Preserve the original page data while upgrading an interrupted
            # workspace created before metadata requests acquired group identity.
            with self.db:
                self.db.execute("BEGIN IMMEDIATE")
                self.db.execute("ALTER TABLE capture_pages RENAME TO capture_pages_ungrouped")
                self.db.execute("CREATE TABLE capture_pages(capture TEXT NOT NULL, kind TEXT NOT NULL, "
                                "request_group TEXT NOT NULL, page INTEGER NOT NULL, data TEXT NOT NULL, "
                                "PRIMARY KEY(capture,kind,request_group,page))")
                for old in self.db.execute("SELECT capture,kind,page,data FROM capture_pages_ungrouped"):
                    descriptor = json.loads(old["data"])
                    self.db.execute("INSERT INTO capture_pages VALUES(?,?,?,?,?)",
                                    (old["capture"], old["kind"], request_group(old["kind"], descriptor.get("indicatorId")),
                                     old["page"], old["data"]))
                self.db.execute("DROP TABLE capture_pages_ungrouped")

    def close(self):
        self.db.close()

    def get(self, kind, record_id, required=True, *, with_pages=True):
        identifier(record_id)
        row = self.db.execute("SELECT data FROM records WHERE kind=? AND id=?", (kind, record_id)).fetchone()
        if row is None:
            if required:
                fail("RECORD_MISSING", "The selected " + kind + " is not retained in this workspace.", id=record_id)
            return None
        value = json.loads(row["data"])
        if kind == "capture" and with_pages:
            value["pages"] = [json.loads(page["data"]) for page in self.db.execute(
                "SELECT data FROM capture_pages WHERE capture=? ORDER BY CASE kind "
                "WHEN 'sources' THEN 1 WHEN 'countries' THEN 2 WHEN 'indicators' THEN 3 ELSE 4 END,request_group,page",
                (record_id,))]
        return value

    def list(self, kind):
        return [json.loads(row["data"]) for row in self.db.execute(
            "SELECT data FROM records WHERE kind=? ORDER BY rowid DESC", (kind,))]

    def put(self, kind, value, expected_revision=None, *, transaction=True):
        def save():
            old = self.get(kind, value["id"], required=False, with_pages=False)
            revision = old["revision"] if old else 0
            if expected_revision is not None and expected_revision != revision:
                fail("REVISION_CHANGED", "The saved record changed. Reopen its current revision before saving.",
                     id=value["id"], expectedRevision=expected_revision, currentRevision=revision)
            value["revision"] = revision + 1
            value["updatedAt"] = utc()
            value.setdefault("createdAt", old["createdAt"] if old else value["updatedAt"])
            stored = {key: item for key, item in value.items() if not (kind == "capture" and key == "pages")}
            raw = encode(stored).decode()
            self.db.execute("INSERT OR REPLACE INTO records VALUES(?,?,?,?)",
                            (kind, value["id"], value["revision"], raw))
            if kind in ("selection", "review"):
                self.db.execute("INSERT INTO history VALUES(?,?,?,?)",
                                (kind, value["id"], value["revision"], raw))
            return value
        if not transaction:
            return save()
        with self.db:
            self.db.execute("BEGIN IMMEDIATE")
            return save()

    def state(self, _):
        captures = []
        for item in self.list("capture"):
            item = dict(item)
            item.pop("pages", None)
            if item["status"] == "RUNNING" and not held(self.root / "locks" / (item["id"] + ".lock")):
                item["status"] = "INTERRUPTED"
            captures.append(item)
        catalogs = [{key: value for key, value in item.items() if key not in ("rows", "pages")}
                    for item in self.list("catalog")]
        return {"schema": "stellar-forge.worldbank-workspace.v1",
                "directory": str(self.root), "selections": self.list("selection"),
                "captures": captures, "reviews": self.list("review"),
                "exports": self.list("export"), "catalogs": catalogs}

    def save_selection(self, data):
        record_id = identifier(data.get("id"))
        if "expectedRevision" not in data:
            fail("REVISION_REQUIRED", "Save the displayed selection revision, or zero for a new selection.")
        value = {"id": record_id, "title": text(data.get("title", record_id), "selection title", 128),
                 "spec": selection(data.get("spec")), "schema": "stellar-forge.worldbank-saved-selection.v1"}
        return self.put("selection", value, data["expectedRevision"])

    def catalog(self, data):
        kind, source_id = data.get("kind"), str(data.get("sourceId", "2"))
        key = identifier(str(kind) + ("-" + source_id if kind == "indicators" else ""))
        saved = self.get("catalog", key, required=False)
        if saved is None or data.get("refresh") is True:
            with file_lock(self.root / "locks" / ("catalog-" + key + ".lock")):
                pages, rows, expected_meta, page = [], [], None, 1
                while True:
                    url = catalog_url(kind, page, source_id)
                    raw, receipt = request_page(url)
                    meta, records = envelope(raw, page, expected_meta)
                    expected_meta = expected_meta or meta
                    path = self.root / "catalogs" / key / (f"{page:06d}-" + receipt["sha256"] + ".json")
                    immutable(path, raw)
                    pages.append({**receipt, "kind": kind, "page": page,
                                  "bodyFile": path.relative_to(self.root).as_posix(), "pagination": meta})
                    rows.extend(records)
                    if page >= max(1, meta["pages"]):
                        break
                    page += 1
                if len(rows) != expected_meta["total"]:
                    fail("SOURCE_POPULATION", "The complete catalogue row count differs from the original total.")
                saved = self.put("catalog", {"id": key, "kind": kind, "sourceId": source_id,
                                 "capturedAt": utc(), "pages": pages, "rows": rows,
                                 "total": len(rows), "pageCount": len(pages)})
        query = text(data.get("search", ""), "catalogue search", 200).casefold()
        rows = saved["rows"]
        if query:
            rows = [item for item in rows if query in json.dumps(item, ensure_ascii=False).casefold()]
        offset, limit = page_window(data, 100)
        return {"id": saved["id"], "kind": kind, "sourceId": source_id, "capturedAt": saved["capturedAt"],
                "total": len(rows), "sourceTotal": saved["total"], "offset": offset, "limit": limit,
                "rows": rows[offset:offset + limit]}

    def _capture(self, data, acquisition):
        capture_id = identifier(data.get("id"), "capture id")
        prior = self.get("capture", capture_id, required=False)
        if prior:
            if data.get("selectionId") and prior["selectionId"] != data["selectionId"]:
                fail("CAPTURE_IDENTITY", "This capture belongs to its original saved selection.")
            if prior["acquisition"] != acquisition:
                fail("CAPTURE_IDENTITY", "Continue the original source transport for this capture.")
            return prior
        selected = self.get("selection", data.get("selectionId"))
        return self.put("capture", {
            "schema": "stellar-forge.worldbank-capture.v1", "id": capture_id,
            "selectionId": selected["id"], "selectionRevision": selected["revision"],
            "selectionTitle": selected["title"], "spec": selected["spec"],
            "selectionSha256": identity(selected["spec"]), "acquisition": acquisition,
            "status": "PREPARED", "pages": [], "collections": {}, "requestGroups": {}, "summary": {},
            "startedAt": utc(), "error": None,
        }, 0)

    def _rows(self, capture_id):
        for row in self.db.execute("SELECT data FROM observations WHERE capture=? ORDER BY page,position", (capture_id,)):
            yield json.loads(row["data"])

    def _country_index(self, capture):
        countries = {}
        for descriptor in capture["pages"]:
            if descriptor["kind"] != "countries":
                continue
            _, rows = envelope(read_bytes(self.root / descriptor["bodyFile"]), descriptor["page"])
            for row in rows:
                for key in ("id", "iso2Code"):
                    value = row.get(key)
                    if isinstance(value, str) and value:
                        countries[value.upper()] = row
        return countries

    def _group_states(self, capture):
        if capture.get("requestGroups"):
            return dict(capture["requestGroups"])
        groups = {}
        for item in capture["pages"]:
            group = request_group(item["kind"], item.get("indicatorId"))
            state = groups.setdefault(group, {"kind": item["kind"], "indicatorId": item.get("indicatorId"),
                                             "requestGroup": item.get("requestGroup", group), "rows": 0})
            meta = item["pagination"]
            state.update(pages=item["page"], expectedPages=meta["pages"], total=meta["total"],
                         lastUpdated=meta["lastUpdated"], complete=item["page"] >= max(1, meta["pages"]))
            state["rows"] += item["rows"]
        return groups

    def _collections(self, capture, groups):
        collections = {kind: groups[kind] for kind in ("sources", "countries", "data") if kind in groups}
        required = [request_group("indicators", item) for item in capture["spec"]["indicators"]]
        selected = [groups[key] for key in required if key in groups]
        collections["indicators"] = {
            "pages": sum(item["pages"] for item in selected),
            "expectedPages": sum(item["expectedPages"] for item in selected),
            "rows": sum(item["rows"] for item in selected),
            "total": sum(item["total"] for item in selected),
            "lastUpdated": ", ".join(sorted({item["lastUpdated"] for item in selected if item["lastUpdated"]})),
            "requiredGroups": required,
            "complete": all(groups.get(key, {}).get("complete") for key in required),
            "retainedSupplementalPages": groups.get("indicators", {}).get("pages", 0),
        }
        return collections

    def _append(self, capture, kind, page, raw, receipt, indicator_id=None, source_group=None):
        group = request_group(kind, indicator_id)
        indicator_id = indicator_id.upper() if indicator_id is not None else None
        original_url = url_for(capture["spec"], kind, page, indicator_id)
        if not same_request(receipt.get("url"), original_url) or not same_request(
            receipt.get("finalUrl"), original_url
        ) or receipt.get("status") != 200 or (
            receipt.get("sha256") != digest(raw) or receipt.get("bytes") != len(raw)
        ):
            fail("SOURCE_RECEIPT", "The original response bytes and request receipt do not match the selected page.")
        prior_pages = [item for item in capture["pages"]
                       if request_group(item["kind"], item.get("indicatorId")) == group]
        if page != len(prior_pages) + 1:
            fail("SOURCE_PAGE_ORDER", "Append the next original page without replacing earlier pages.")
        meta, rows = envelope(raw, page, prior_pages[0]["pagination"] if prior_pages else None)
        if meta["perPage"] != capture["spec"]["perPage"]:
            fail("SOURCE_PAGE_SIZE", "The source used a different page size from this saved selection.")
        if kind == "data":
            if meta["sourceId"] and meta["sourceId"] != capture["spec"]["sourceId"]:
                fail("SOURCE_ID", "The source response identifies another source database.")
            if meta["total"] > MAX_ROWS:
                fail("DATASET_CAPACITY", "This selection exceeds the native dataset's one-million-row capacity. Choose its intended country/indicator/period population.")
            countries = self._country_index(capture)
            normalized = [normalize_observation(row, capture["spec"], page, pos, countries)
                          for pos, row in enumerate(rows, 1)]
        else:
            normalized = []
        body_root = self.root / "captures" / capture["id"] / "raw" / kind
        if kind == "indicators":
            body_root = body_root / (indicator_id or "_combined")
        body_path = body_root / (f"{page:06d}-" + digest(raw) + ".json")
        immutable(body_path, raw)
        retained = {**receipt, "kind": kind, "page": page, "pagination": meta,
                    "requestGroup": text(source_group if source_group is not None else group, "original request group", 200),
                    "bodyFile": body_path.relative_to(self.root).as_posix(), "rows": len(rows)}
        if indicator_id is not None:
            retained["indicatorId"] = indicator_id
        current = dict(capture)
        current["pages"] = [*capture["pages"], retained]
        groups = self._group_states(capture)
        row_count = sum(item["rows"] for item in prior_pages) + len(rows)
        complete = page >= max(1, meta["pages"])
        if complete and row_count != meta["total"]:
            fail("SOURCE_POPULATION", "The completed page chain differs from the source's total.")
        groups[group] = {"kind": kind, "indicatorId": indicator_id, "requestGroup": retained["requestGroup"],
                         "pages": page, "expectedPages": meta["pages"], "rows": row_count,
                         "total": meta["total"], "lastUpdated": meta["lastUpdated"], "complete": complete}
        collections = self._collections(capture, groups)
        current["requestGroups"] = groups
        current["collections"], current["status"], current["error"] = collections, "RUNNING", None
        with self.db:
            self.db.execute("BEGIN IMMEDIATE")
            self.db.execute("INSERT INTO capture_pages VALUES(?,?,?,?,?)",
                            (capture["id"], kind, group, page, encode(retained).decode()))
            for row in normalized:
                self.db.execute("INSERT INTO observations VALUES(?,?,?,?,?)",
                                (capture["id"], page, row["source_row"], row["key"], encode(row).decode()))
            return self.put("capture", current, capture["revision"], transaction=False)

    def _finish(self, capture):
        groups = self._group_states(capture)
        required = ["sources", "countries", "data", *[
            request_group("indicators", item) for item in capture["spec"]["indicators"]]]
        if not all(groups.get(group, {}).get("complete") for group in required):
            return capture
        index = self._country_index(capture)
        if capture["spec"]["countries"] != ["all"]:
            absent = [code for code in capture["spec"]["countries"] if code.upper() not in index]
            if absent:
                fail("SOURCE_COUNTRY_METADATA", "The source did not return every selected country or aggregate.", codes=absent)
        indicators, sources = set(), set()
        for item in capture["pages"]:
            if item["kind"] not in ("sources", "indicators"):
                continue
            _, records = envelope(read_bytes(self.root / item["bodyFile"]), item["page"])
            for record in records:
                if item["kind"] == "sources":
                    sources.add(str(record.get("id")))
                else:
                    if str(record.get("source", {}).get("id")) != capture["spec"]["sourceId"]:
                        fail("SOURCE_INDICATOR_METADATA", "An indicator's metadata belongs to another source.")
                    indicator = str(record.get("id")).upper()
                    if item.get("indicatorId") and indicator != item["indicatorId"]:
                        fail("SOURCE_INDICATOR_METADATA", "An indicator metadata response belongs to another request group.")
                    indicators.add(indicator)
        if sources != {capture["spec"]["sourceId"]} or indicators != set(capture["spec"]["indicators"]):
            fail("SOURCE_METADATA", "The original source or indicator metadata does not cover the saved selection.")
        summary = {"observations": 0, "present": 0, "missing": 0, "aggregateObservations": 0,
                   "duplicateKeys": 0, "conflictingKeys": 0, "observationStatuses": {}}
        grouped = {}
        for row in self._rows(capture["id"]):
            summary["observations"] += 1
            summary[row["value_state"]] += 1
            summary["aggregateObservations"] += int(row["aggregate"])
            status = row["obs_status"] or "(unspecified)"
            summary["observationStatuses"][status] = summary["observationStatuses"].get(status, 0) + 1
            grouped.setdefault(row["key"], []).append(row["contentSha256"])
        for hashes in grouped.values():
            summary["duplicateKeys"] += int(len(hashes) > 1)
            summary["conflictingKeys"] += int(len(set(hashes)) > 1)
        capture["pages"] = sorted(capture["pages"], key=page_order)
        capture["requestGroups"] = groups
        capture["collections"] = self._collections(capture, groups)
        capture["summary"], capture["status"], capture["completedAt"] = summary, "COMPLETE", utc()
        capture["captureSha256"] = identity({
            "spec": capture["spec"], "acquisition": capture["acquisition"],
            "pages": [{key: item[key] for key in ("kind", "page", "indicatorId", "requestGroup", "url", "sha256", "bytes", "pagination") if key in item}
                      for item in capture["pages"]], "summary": summary,
        })
        capture = self.put("capture", capture, capture["revision"])
        immutable(self.root / "captures" / capture["id"] / "capture.json", encode(capture))
        return capture

    def capture(self, data):
        capture_id = identifier(data.get("id"), "capture id")
        with file_lock(self.root / "locks" / (capture_id + ".lock")):
            capture = self._capture(data, "ORIGINAL_HTTP")
            if capture["status"] == "COMPLETE":
                return self.capture_detail({"id": capture_id})
            retry = (capture.get("error") or {}).get("retryAt")
            if retry and retry > utc():
                fail("SOURCE_COOLDOWN", "The original source cooldown is still active.", retryAt=retry)
            capture["status"], capture["error"] = "RUNNING", None
            capture = self.put("capture", capture, capture["revision"])
            try:
                requests = [("sources", None), ("countries", None), *[
                    ("indicators", item) for item in capture["spec"]["indicators"]], ("data", None)]
                for kind, indicator_id in requests:
                    group = request_group(kind, indicator_id)
                    while not self._group_states(capture).get(group, {}).get("complete"):
                        page = self._group_states(capture).get(group, {}).get("pages", 0) + 1
                        raw, receipt = request_page(url_for(capture["spec"], kind, page, indicator_id))
                        capture = self._append(capture, kind, page, raw, receipt, indicator_id)
                return self._finish(capture)
            except BaseException as exc:
                capture = self.get("capture", capture_id)
                if capture["status"] == "COMPLETE":
                    # Completion is already committed. Reopening repairs an interrupted
                    # adjacent manifest write from this exact retained record.
                    raise
                capture["status"] = "INTERRUPTED" if isinstance(exc, (KeyboardInterrupt, SystemExit)) else "PAUSED"
                capture["error"] = exc.public() if isinstance(exc, SourceError) else {
                    "code": "CAPTURE_INTERRUPTED" if capture["status"] == "INTERRUPTED" else "CAPTURE_FAILED",
                    "message": str(exc) or "The original acquisition was interrupted."}
                self.put("capture", capture, capture["revision"])
                raise

    def import_pages(self, data):
        capture_id = identifier(data.get("id"))
        pages = data.get("pages")
        if not isinstance(pages, list) or not pages:
            fail("SOURCE_IMPORT", "Provide the original page bytes and source receipts.")
        with file_lock(self.root / "locks" / (capture_id + ".lock")):
            capture = self._capture(data, "IMPORTED_ORIGINAL_RESPONSES")
            for page in sorted(pages, key=page_order):
                kind, number = page["kind"], page["page"]
                group = request_group(kind, page.get("indicatorId"))
                try:
                    raw = base64.b64decode(page["bodyBase64"], validate=True)
                except (ValueError, TypeError, KeyError) as exc:
                    raise SourceError("SOURCE_IMPORT", "Supply one complete original Base64 response body.") from exc
                receipt = page.get("receipt")
                if not isinstance(receipt, dict) or not isinstance(receipt.get("receivedAt"), str):
                    fail("SOURCE_IMPORT", "Preserve the original source request and acquisition receipt.")
                earlier = next((item for item in capture["pages"] if item["page"] == number
                                and request_group(item["kind"], item.get("indicatorId")) == group), None)
                if earlier:
                    if earlier["sha256"] != digest(raw) or earlier["url"] != receipt.get("url"):
                        fail("SOURCE_IMPORT_CONFLICT", "The incoming source page conflicts with the retained original.")
                    continue
                if capture["status"] == "COMPLETE":
                    fail("CAPTURE_COMPLETE", "A complete original capture is immutable.")
                capture = self._append(capture, kind, number, raw, receipt,
                                       page.get("indicatorId"), page.get("requestGroup"))
            return self._finish(capture) if capture["status"] != "COMPLETE" else self.capture_detail({"id": capture_id})

    def capture_detail(self, data):
        capture_id = data.get("id") or data.get("captureId")
        capture = self.get("capture", capture_id)
        for item in capture["pages"]:
            raw = read_bytes(self.root / item["bodyFile"])
            if digest(raw) != item["sha256"] or len(raw) != item["bytes"]:
                fail("SOURCE_CHANGED", "A retained original source page changed.")
        if capture["status"] == "COMPLETE":
            path = self.root / "captures" / capture["id"] / "capture.json"
            if not path.exists():
                immutable(path, encode(capture))
            elif json.loads(read_bytes(path)) != capture:
                fail("CAPTURE_CHANGED", "The saved capture metadata differs from its completed original.")
        return capture

    def observations(self, data):
        capture = self.get("capture", data.get("captureId"))
        query = text(data.get("search", ""), "observation search", 200).casefold()
        offset, limit = page_window(data)
        result, total = [], 0
        for row in self._rows(capture["id"]):
            if query and query not in json.dumps(row, ensure_ascii=False).casefold():
                continue
            if offset <= total < offset + limit:
                result.append(row)
            total += 1
        return {"captureId": capture["id"], "status": capture["status"], "total": total,
                "offset": offset, "limit": limit, "rows": result, "summary": capture["summary"]}

    def compare(self, data):
        current = self.get("capture", data.get("captureId"))
        baseline = self.get("capture", data.get("baselineId"))
        if current["status"] != "COMPLETE" or baseline["status"] != "COMPLETE":
            fail("CAPTURE_INCOMPLETE", "Compare two complete original captures.")
        def group(capture_id):
            result = {}
            for row in self._rows(capture_id):
                result.setdefault(row["key"], []).append(row)
            return result
        before, after = group(baseline["id"]), group(current["id"])
        counts = {"added": 0, "absent": 0, "changed": 0, "unchanged": 0}
        changes = []
        for key in sorted(before.keys() | after.keys()):
            old, new = before.get(key, []), after.get(key, [])
            status = "added" if not old else "absent" if not new else (
                "unchanged" if sorted(item["contentSha256"] for item in old) == sorted(item["contentSha256"] for item in new)
                else "changed")
            counts[status] += 1
            if status != "unchanged":
                changes.append({"key": key, "status": status, "before": old, "after": new})
        fields = ("sourceId", "countries", "indicators", "date")
        same = all(current["spec"][key] == baseline["spec"][key] for key in fields)
        offset, limit = page_window(data)
        return {"captureId": current["id"], "baselineId": baseline["id"], "sameSelection": same,
                "currentSelection": current["spec"], "baselineSelection": baseline["spec"],
                "counts": counts, "total": len(changes), "offset": offset, "limit": limit,
                "rows": changes[offset:offset + limit]}

    def review(self, data):
        capture = self.capture_detail({"id": data.get("captureId")})
        if capture["status"] != "COMPLETE":
            fail("CAPTURE_INCOMPLETE", "Finish the original page chain before saving an edition review.")
        review_id = identifier(data.get("id"))
        if "expectedRevision" not in data:
            fail("REVISION_REQUIRED", "Save the displayed review revision, or zero for a new review.")
        excluded = data.get("excludedKeys", [])
        choices = data.get("choices", {})
        if not isinstance(excluded, list) or any(not isinstance(key, str) for key in excluded) or not isinstance(choices, dict):
            fail("REVIEW_SELECTION", "Choose observation identities and any explicit duplicate rows.")
        groups = {}
        for row in self._rows(capture["id"]):
            groups.setdefault(row["key"], []).append(row)
        unknown = set(excluded) - groups.keys()
        if unknown or set(choices) - groups.keys():
            fail("REVIEW_SELECTION", "The review names observations outside its original capture.")
        unresolved = []
        for key, rows in groups.items():
            if key in choices and choices[key] not in {row["rowId"] for row in rows}:
                fail("REVIEW_SELECTION", "A chosen duplicate row belongs to another observation.")
            if key not in excluded and len(rows) > 1 and key not in choices:
                unresolved.append({"key": key, "rows": [row["rowId"] for row in rows]})
        if unresolved:
            fail("DUPLICATE_REVIEW", "Choose the original row to retain for each repeated observation identity, or exclude that identity.", conflicts=unresolved[:100])
        baseline_id = data.get("baselineId") or None
        comparison = self.compare({"captureId": capture["id"], "baselineId": baseline_id, "limit": 1}) if baseline_id else None
        columns = data.get("columns", list(COLUMNS))
        if not isinstance(columns, list) or not columns or len(set(columns)) != len(columns) or set(columns) - set(COLUMNS):
            fail("REVIEW_COLUMNS", "Choose unique fields from the original observation projection.")
        mandatory = {"source_id", "country_id", "country_iso3", "indicator_id", "period", "value", "value_state"}
        if not mandatory <= set(columns):
            fail("REVIEW_COLUMNS", "Keep source, country, indicator, period and value identity in the customer dataset.")
        value = {"schema": "stellar-forge.worldbank-review.v1", "id": review_id,
                 "title": text(data.get("title", capture["selectionTitle"]), "review title", 128),
                 "note": text(data.get("note", ""), "review note", 100000),
                 "captureId": capture["id"], "captureSha256": capture["captureSha256"],
                 "baselineId": baseline_id, "comparison": {key: comparison[key] for key in
                    ("counts", "sameSelection", "baselineId", "captureId")} if comparison else None,
                 "excludedKeys": sorted(set(excluded)), "choices": choices, "columns": columns,
                 "includedObservations": len(groups) - len(set(excluded)), "summary": capture["summary"]}
        return self.put("review", value, data["expectedRevision"])

    def review_read(self, data):
        value = self.get("review", data.get("id"))
        history = self.db.execute("SELECT revision,data FROM history WHERE kind='review' AND id=? ORDER BY revision DESC",
                                  (value["id"],))
        return {**value, "history": [{"revision": row["revision"], "updatedAt": json.loads(row["data"])["updatedAt"]}
                                   for row in history]}

    def export(self, data):
        export_id = identifier(data.get("id"), "export id")
        with file_lock(self.root / "locks" / ("export-" + export_id + ".lock")):
            existing = self.get("export", export_id, required=False)
            if existing:
                if existing["reviewId"] != data.get("reviewId"):
                    fail("EXPORT_IDENTITY", "This export belongs to its original review.")
                return self.export_read({"id": export_id})
            review = self.get("review", data.get("reviewId"))
            if data.get("expectedRevision", review["revision"]) != review["revision"]:
                fail("REVISION_CHANGED", "Review the current edition revision before preparing its export.")
            capture = self.capture_detail({"id": review["captureId"]})
            if capture.get("captureSha256") != review["captureSha256"]:
                fail("REVIEW_SOURCE_CHANGED", "The review no longer matches its completed source capture.")
            output = self.root / "exports" / export_id
            output.mkdir(mode=0o700, exist_ok=True)
            intent = {"id": export_id, "reviewId": review["id"], "reviewRevision": review["revision"],
                      "captureSha256": capture["captureSha256"]}
            immutable(output / "intent.json", encode(intent))
            columns = review["columns"]
            csv_stream = io.StringIO(newline="")
            writer = csv.writer(csv_stream, lineterminator="\n")
            writer.writerow(columns)
            rows_written = 0
            for row in self._rows(capture["id"]):
                if row["key"] in review["excludedKeys"]:
                    continue
                if row["key"] in review["choices"] and review["choices"][row["key"]] != row["rowId"]:
                    continue
                values = []
                for key in columns:
                    value = row[key]
                    values.append("" if value is None else "true" if value is True else "false" if value is False else str(value))
                writer.writerow(values)
                rows_written += 1
            if rows_written != review["includedObservations"]:
                fail("REVIEW_POPULATION", "The reviewed observation population differs from the export.")
            csv_bytes = csv_stream.getvalue().encode("utf-8")
            config = {
                "schema": "stellar-forge.csv-dataset.v1", "file": "dataset.csv",
                "name": "World Bank " + capture["selectionId"][:96],
                "columns": {column: ({"type": "string", "nullable": True} if column == "value" else
                             "boolean" if column == "aggregate" else "integer" if column in ("source_page", "source_row")
                             else "string") for column in columns},
                "filters": [column for column in ("source_id", "country_id", "country_iso3", "indicator_id",
                                                 "value_state", "aggregate", "obs_status") if column in columns],
                "ranges": ["period"], "sorts": ["period", "country_id", "indicator_id"],
                "maxBytes": 256 * 1024 * 1024, "maxRows": max(1, rows_written), "maxCellChars": 1024 * 1024,
                "defaultLimit": 50, "maxLimit": 1000, "maxPageBytes": 900 * 1024,
            }
            files = []
            def add(relative, raw):
                path = output / relative
                immutable(path, raw)
                files.append(file_descriptor(output, path))
            add("dataset.csv", csv_bytes)
            add("dataset.json", encode(config))
            add("review.json", encode(review))
            add("selection.json", encode(capture["spec"]))
            add("original/capture.json", encode(capture))
            for page in capture["pages"]:
                add("original/" + page["bodyFile"], read_bytes(self.root / page["bodyFile"]))
            retained = [item for item in files if item["path"] not in ("dataset.csv", "dataset.json")]
            source = {
                "schema": "stellar-forge.worldbank-export.v1", **intent,
                "provider": "World Bank Indicators API V2", "api": "https://api.worldbank.org/v2",
                "sourceId": capture["spec"]["sourceId"], "selection": capture["spec"],
                "acquisition": capture["acquisition"], "capturedAt": capture["completedAt"],
                "collections": capture["collections"], "observations": rows_written,
                "numericRepresentation": "Original JSON number tokens retained as exact strings; source null remains nullable.",
                "periodRepresentation": "Original source period labels and observation statuses retained.",
                "attribution": "World Bank and the original source organizations retained in the indicator metadata.",
                "documentation": [
                    "https://datahelpdesk.worldbank.org/knowledgebase/articles/898581-api-basic-call-structures",
                    "https://datahelpdesk.worldbank.org/knowledgebase/articles/898599-indicator-api-queries",
                ],
                "sourceFiles": retained,
            }
            add("source.json", encode(source))
            package_manifest = {"schema": "stellar-forge.worldbank-package.v1", **intent,
                                "files": sorted(files, key=lambda item: item["path"])}
            archive_bytes = io.BytesIO()
            with zipfile.ZipFile(archive_bytes, "w", compression=zipfile.ZIP_DEFLATED) as archive:
                def pack(name, raw):
                    member = zipfile.ZipInfo(name, date_time=(1980, 1, 1, 0, 0, 0))
                    member.create_system = 3
                    member.external_attr = 0o100600 << 16
                    member.compress_type = zipfile.ZIP_DEFLATED
                    archive.writestr(member, raw)
                for item in package_manifest["files"]:
                    pack(item["path"], read_bytes(output / item["path"]))
                pack("package-manifest.json", encode(package_manifest))
            add("handover.zip", archive_bytes.getvalue())
            manifest = {"schema": "stellar-forge.worldbank-export-manifest.v1", **intent,
                        "observations": rows_written, "files": sorted(files, key=lambda item: item["path"])}
            immutable(output / "manifest.json", encode(manifest))
            self.put("export", {**intent, "directory": str(output), "manifestSha256": digest(encode(manifest)),
                               "observations": rows_written, "title": review["title"]}, 0)
            return self.export_read({"id": export_id})

    def export_read(self, data):
        saved = self.get("export", data.get("id"))
        root = self.root / "exports" / saved["id"]
        raw = read_bytes(root / "manifest.json")
        if digest(raw) != saved["manifestSha256"]:
            fail("EXPORT_CHANGED", "The retained export manifest changed.")
        manifest = json.loads(raw)
        for item in manifest["files"]:
            path = root / item["path"]
            regular(path, root)
            content = read_bytes(path)
            if len(content) != item["bytes"] or digest(content) != item["sha256"]:
                fail("EXPORT_CHANGED", "A retained export file changed.", file=item["path"])
        return {**saved, "directory": str(root), "manifest": manifest}

    def import_package(self, data):
        capture_id, review_id = identifier(data.get("id")), identifier(data.get("reviewId", data.get("id") + "-review"))
        try:
            raw = base64.b64decode(data["archiveBase64"], validate=True)
        except (KeyError, TypeError, ValueError) as exc:
            raise SourceError("PACKAGE_IMPORT", "Supply the complete retained handover ZIP.") from exc
        if len(raw) > 256 * 1024 * 1024:
            fail("PACKAGE_IMPORT", "The incoming handover exceeds 256 MiB.")
        with zipfile.ZipFile(io.BytesIO(raw)) as archive:
            infos = archive.infolist()
            names = [item.filename for item in infos]
            if len(names) != len(set(names)) or len(names) > 10000 or sum(item.file_size for item in infos) > 512 * 1024 * 1024:
                fail("PACKAGE_IMPORT", "The handover has repeated members or exceeds the supported import capacity.")
            for item in infos:
                path = Path(item.filename)
                if path.is_absolute() or ".." in path.parts or "\\" in item.filename or item.is_dir() or (item.external_attr >> 16) & 0o170000 == 0o120000:
                    fail("PACKAGE_IMPORT", "The handover contains a non-regular or unsafe member.")
            manifest = json.loads(archive.read("package-manifest.json"))
            if manifest.get("schema") != "stellar-forge.worldbank-package.v1":
                fail("PACKAGE_IMPORT", "Use the original World Bank handover package.")
            files = manifest["files"]
            if set(names) != {item["path"] for item in files} | {"package-manifest.json"}:
                fail("PACKAGE_IMPORT", "The archive members differ from its retained manifest.")
            content = {}
            for item in files:
                value = archive.read(item["path"])
                if digest(value) != item["sha256"] or len(value) != item["bytes"]:
                    fail("PACKAGE_IMPORT", "An incoming source file differs from its original descriptor.")
                content[item["path"]] = value
            original = json.loads(content["original/capture.json"])
            selected = original["spec"]
            selection_id = identifier(data.get("selectionId", capture_id + "-selection"))
            prior = self.get("selection", selection_id, required=False)
            if prior:
                if prior["spec"] != selected:
                    fail("PACKAGE_IMPORT", "The receiving selection ID already names different source criteria.")
            else:
                self.save_selection({"id": selection_id, "title": original["selectionTitle"],
                                     "spec": selected, "expectedRevision": 0})
            pages = []
            for page in original["pages"]:
                pages.append({"kind": page["kind"], "page": page["page"],
                              **{key: page[key] for key in ("indicatorId", "requestGroup") if key in page},
                              "bodyBase64": base64.b64encode(content["original/" + page["bodyFile"]]).decode(),
                              "receipt": {key: value for key, value in page.items() if key not in
                                          ("kind", "page", "indicatorId", "requestGroup", "bodyFile", "rows", "pagination")}})
            capture = self.import_pages({"id": capture_id, "selectionId": selection_id, "pages": pages})
            original_review = json.loads(content["review.json"])
            prior_review = self.get("review", review_id, required=False)
            review = self.review({"id": review_id, "captureId": capture_id, "expectedRevision": prior_review["revision"] if prior_review else 0,
                                  "title": original_review["title"], "note": original_review["note"],
                                  "columns": original_review["columns"], "excludedKeys": original_review["excludedKeys"],
                                  "choices": original_review["choices"]})
            return {"capture": capture, "review": review, "originalPackageSha256": digest(raw),
                    "originalCaptureSha256": original["captureSha256"],
                    "originalReviewId": original_review["id"], "originalReviewRevision": original_review["revision"]}


ACTIONS = {
    "state": "state", "save-selection": "save_selection", "catalog": "catalog",
    "capture": "capture", "import-pages": "import_pages", "capture-detail": "capture_detail",
    "observations": "observations", "compare": "compare", "review": "review",
    "review-read": "review_read", "export": "export", "export-read": "export_read",
    "import-package": "import_package",
}


def run(directory, action, data):
    if action not in ACTIONS:
        fail("WORKSPACE_ACTION", "Unknown World Bank workspace action.")
    if not isinstance(data, dict):
        fail("WORKSPACE_INPUT", "Supply a JSON object for the selected action.")
    workspace = Workspace(directory)
    try:
        return getattr(workspace, ACTIONS[action])(data)
    finally:
        workspace.close()


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--workspace", required=True)
    parser.add_argument("--action", required=True, choices=sorted(ACTIONS))
    arguments = parser.parse_args()
    signal.signal(signal.SIGTERM, lambda *_: (_ for _ in ()).throw(KeyboardInterrupt("Capture cancelled by its operator.")))
    try:
        incoming = sys.stdin.buffer.read(256 * 1024 * 1024 + 1)
        if len(incoming) > 256 * 1024 * 1024:
            fail("WORKSPACE_INPUT", "The source action exceeds its input capacity.")
        data = json.loads(incoming or b"{}")
        result = run(arguments.workspace, arguments.action, data)
        sys.stdout.buffer.write(encode(result))
    except SourceError as error:
        sys.stdout.buffer.write(encode({"error": error.public()}))
        return 1
    except (KeyboardInterrupt, SystemExit) as error:
        sys.stdout.buffer.write(encode({"error": {"code": "CAPTURE_INTERRUPTED", "message": str(error)}}))
        return 1
    except Exception as error:
        sys.stdout.buffer.write(encode({"error": {"code": "WORKSPACE_FAILED", "message": str(error)}}))
        return 1
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

// MIT. World Bank source workspace over the original SF30/SF82/SF88 publisher.
import { spawn } from 'node:child_process';
import { createServer } from 'node:http';
import { constants } from 'node:fs';
import { mkdir, realpath, open, readFile, link, unlink } from 'node:fs/promises';
import { createHash, randomBytes, randomUUID, timingSafeEqual } from 'node:crypto';
import { isAbsolute, resolve, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = fileURLToPath(new URL('./', import.meta.url));
const MAX_JSON = 1024 * 1024;
const MAX_IMPORT = 256 * 1024 * 1024;
const MAX_OUTPUT = 64 * 1024 * 1024;
const MAX_DOWNLOAD = 256 * 1024 * 1024;
const ID = /^[A-Za-z0-9][A-Za-z0-9._-]{0,127}$/;
const object = value => value !== null && typeof value === 'object' && !Array.isArray(value);
const json = value => Buffer.from(JSON.stringify(value, null, 2) + '\n');
const sha = bytes => createHash('sha256').update(bytes).digest('hex');
const fault = (code, message, status = 400) => Object.assign(new Error(message), { code, status });
const publicError = error => ({
  ...(object(error?.sourceDetails) ? error.sourceDetails : {}),
  code: typeof error?.code === 'string' ? error.code : 'WORLDBANK_OPERATION_FAILED',
  message: error?.message || 'The World Bank workspace could not complete this action.',
  ...(error?.retryAt === undefined ? {} : { retryAt: error.retryAt })
});
const coreActions = new Set([
  'state', 'save-selection', 'catalog', 'capture', 'capture-detail', 'observations',
  'compare', 'review', 'review-read', 'export', 'export-read', 'import-pages', 'import-package'
]);
const publisherActions = new Set([
  'publisher.status', 'publisher.preview', 'publisher.reviewDraft', 'publisher.publish',
  'publisher.activateSnapshot', 'publisher.collect',
  'publisher.release.stage', 'publisher.release.inspect', 'publisher.release.activate',
  'publisher.release.rollback', 'publisher.release.start', 'publisher.release.stop',
  'publisher.buyer.review', 'publisher.buyer.prepare', 'publisher.buyer.session',
  'publisher.buyer.run', 'publisher.buyer.recover', 'publisher.buyer.account',
  'publisher.buyer.export'
]);
export const WORLDBANK_ACTIONS = Object.freeze([
  ...coreActions, 'capture-cancel', 'merchant-prepare', ...publisherActions
]);

function fields(value, allowed) {
  if (!object(value) || Object.keys(value).some(key => !allowed.includes(key)))
    throw fault('WORLDBANK_INPUT', 'Use an object containing the fields supported by this action.');
}
function identifier(value, label) {
  if (typeof value !== 'string' || !ID.test(value) || value === '.' || value === '..')
    throw fault('WORLDBANK_ID', 'Choose a valid ' + label + ' identifier.');
  return value;
}
function canonical(value) {
  if (Array.isArray(value)) return value.map(canonical);
  if (object(value)) return Object.fromEntries(Object.keys(value).sort().map(key => [key, canonical(value[key])]));
  return value;
}
function same(left, right) { return JSON.stringify(canonical(left)) === JSON.stringify(canonical(right)); }

async function stableBytes(path, maximum = MAX_DOWNLOAD) {
  if (await realpath(path) !== resolve(path))
    throw fault('WORLDBANK_EXPORT_PATH', 'Use the original retained export files.', 409);
  const file = await open(path, constants.O_RDONLY | (constants.O_NOFOLLOW ?? 0));
  try {
    const before = await file.stat({ bigint: true });
    if (!before.isFile() || before.size > BigInt(maximum))
      throw fault('WORLDBANK_FILE_SIZE', 'The selected file exceeds its supported download size.', 413);
    const bytes = await file.readFile(), after = await file.stat({ bigint: true });
    if (BigInt(bytes.length) !== before.size || before.size !== after.size ||
        before.mtimeNs !== after.mtimeNs || before.ino !== after.ino || before.dev !== after.dev)
      throw fault('WORLDBANK_FILE_CHANGED', 'The retained export changed during this read.', 409);
    return bytes;
  } finally { await file.close(); }
}
async function writeImmutable(path, bytes) {
  // Publish only complete bytes. The existing destination is never overwritten.
  const temporary = path + '.stage-' + randomUUID();
  let created = false;
  try {
    const file = await open(temporary, 'wx', 0o600);
    created = true;
    try { await file.writeFile(bytes); await file.sync(); } finally { await file.close(); }
    try { await link(temporary, path); }
    catch (error) {
      if (error.code !== 'EEXIST') throw error;
      if (!(await stableBytes(path, Math.max(MAX_JSON, bytes.length))).equals(bytes))
        throw fault('WORLDBANK_MERCHANT_CHANGED',
          'This export already has different merchant terms. Create a new export for changed terms.', 409);
    }
    const parent = await open(resolve(path, '..'), 'r');
    try { await parent.sync(); } finally { await parent.close(); }
  } finally { if (created) await unlink(temporary).catch(error => { if (error.code !== 'ENOENT') throw error; }); }
}

/** The Python child owns source capture and retained pages; no source values are rewritten here. */
export async function openWorldBankOperator({ directory, python = process.env.PYTHON || 'python3' } = {}) {
  if (typeof directory !== 'string' || !directory.trim())
    throw fault('WORLDBANK_DIRECTORY', 'Choose a World Bank workspace directory.');
  if (typeof python !== 'string' || !python.trim())
    throw fault('WORLDBANK_PYTHON', 'Choose the existing Python 3 executable.');
  directory = resolve(directory);
  if (!isAbsolute(directory) || directory === '/')
    throw fault('WORLDBANK_DIRECTORY', 'Choose a dedicated workspace directory.');
  await mkdir(directory, { recursive: true, mode: 0o700 });
  if (await realpath(directory) !== directory)
    throw fault('WORLDBANK_DIRECTORY', 'Use a canonical workspace directory.');
  let publisher, openingPublisher, closing = false, closePromise;
  let prepareTail = Promise.resolve();
  const jobs = new Map(), children = new Set(), operations = new Set();
  const now = () => new Date().toISOString();
  const track = operation => {
    if (closing) return Promise.reject(fault('WORLDBANK_CLOSING', 'The workspace is closing.', 409));
    const pending = Promise.resolve().then(operation);
    operations.add(pending);
    pending.then(() => operations.delete(pending), () => operations.delete(pending));
    return pending;
  };

  function launchCore(action, payload = {}) {
    if (!coreActions.has(action) || !object(payload))
      throw fault('WORLDBANK_ACTION', 'Choose a supported World Bank action and object payload.');
    const input = json(payload);
    const inputLimit = ['import-pages', 'import-package'].includes(action) ? MAX_IMPORT : MAX_JSON;
    if (input.length > inputLimit) throw fault('WORLDBANK_INPUT_SIZE',
      'The action exceeds its input capacity of ' + inputLimit + ' bytes.', 413);
    const child = spawn(python, ['-B', join(ROOT, 'core.py'), '--workspace', directory, '--action', action],
      { cwd: ROOT, stdio: ['pipe', 'pipe', 'pipe'], windowsHide: true });
    children.add(child);
    let stdout = [], stdoutSize = 0, stderr = [], stderrSize = 0, failure;
    const completion = new Promise((accept, reject) => {
      child.once('error', error => {
        failure = fault('WORLDBANK_PYTHON_UNAVAILABLE', 'Python could not start: ' + error.message, 503);
      });
      child.stdin.on('error', error => { if (error.code !== 'EPIPE') failure = error; });
      child.stdout.on('data', bytes => {
        stdoutSize += bytes.length;
        if (stdoutSize > MAX_OUTPUT) {
          failure ??= fault('WORLDBANK_OUTPUT_SIZE', 'Use a smaller observation page for this response.', 413);
          child.kill('SIGTERM');
        } else stdout.push(bytes);
      });
      child.stderr.on('data', bytes => {
        if (stderrSize < 32768) { stderr.push(bytes.subarray(0, 32768 - stderrSize)); stderrSize += bytes.length; }
      });
      child.once('close', (code, signal) => {
        children.delete(child);
        if (failure) { reject(failure); return; }
        let value;
        const raw = Buffer.concat(stdout);
        try { value = raw.length ? JSON.parse(new TextDecoder('utf-8', { fatal: true }).decode(raw)) : null; }
        catch { reject(fault('WORLDBANK_CORE_RESPONSE', 'The source engine returned an unreadable response.', 502)); return; }
        if (code !== 0 || value?.error) {
          const detail = object(value?.error) ? value.error : {};
          const error = fault(typeof detail.code === 'string' ? detail.code :
            signal === 'SIGTERM' ? 'WORLDBANK_CAPTURE_CANCELLED' : 'WORLDBANK_CORE_FAILED',
          detail.message || (signal === 'SIGTERM' ? 'Capture stopped; retained pages are available to resume.' :
            Buffer.concat(stderr).toString('utf8').trim() || 'The source engine did not complete this action.'),
          Number.isInteger(detail.status) ? detail.status : signal === 'SIGTERM' ? 409 : 400);
          Object.assign(error, detail);
          error.sourceDetails = structuredClone(detail);
          error.exitCode = code; error.signal = signal;
          reject(error); return;
        }
        if (!object(value) && !Array.isArray(value)) {
          reject(fault('WORLDBANK_CORE_RESPONSE', 'The source engine returned no result.', 502)); return;
        }
        accept(value);
      });
      child.stdin.end(input);
    });
    return { child, completion };
  }
  const core = (action, payload) => launchCore(action, payload).completion;
  const jobView = job => ({
    id: job.id, action: 'capture', selectionId: job.payload.selectionId,
    attempt: job.attempt, status: job.status, startedAt: job.startedAt,
    ...(job.finishedAt ? { finishedAt: job.finishedAt } : {}),
    ...(job.result === undefined ? {} : { result: object(job.result)
      ? Object.fromEntries(Object.entries(job.result).filter(([key]) => key !== 'pages')) : job.result }),
    ...(job.error ? { error: job.error } : {})
  });
  const view = async () => ({
    ...await core('state', {}),
    publisher: publisher ? await publisher.state() : null,
    jobs: [...jobs.values()].map(jobView)
  });
  const refresh = async result => {
    try { return { result, state: await view() }; }
    catch (error) {
      // Preserve the completed operation if its independent state read fails.
      return { result, state: null, stateError: publicError(error) };
    }
  };
  const getPublisher = async () => {
    if (publisher) return publisher;
    if (!openingPublisher) openingPublisher = import('../socrata/publisher.mjs')
      .then(({ openSocrataPublisher }) => openSocrataPublisher({ directory: join(directory, 'publisher') }))
      .then(value => { publisher = value; return value; })
      .catch(error => { openingPublisher = undefined; throw error; });
    return openingPublisher;
  };

  function capture(payload) {
    fields(payload, ['id', 'selectionId']);
    const id = identifier(payload.id, 'capture');
    identifier(payload.selectionId, 'selection');
    const previous = jobs.get(id);
    if (previous && !same(previous.payload, payload))
      throw fault('WORLDBANK_CAPTURE_ID_USED', 'This capture identifier belongs to another selection.', 409);
    if (previous && ['RUNNING', 'CANCELLING', 'COMPLETE'].includes(previous.status)) return jobView(previous);
    const launched = launchCore('capture', payload);
    const job = { id, payload: structuredClone(payload), child: launched.child, completion: launched.completion,
      attempt: (previous?.attempt ?? 0) + 1, status: 'RUNNING', startedAt: now() };
    jobs.set(id, job);
    job.settled = launched.completion.then(result => {
      job.result = result;
      job.status = result?.status === 'CANCELLED' ? 'CANCELLED' : 'COMPLETE';
      job.finishedAt = now(); job.child = null; return jobView(job);
    }, error => {
      job.error = publicError(error); job.finishedAt = now();
      job.status = job.status === 'CANCELLING' || error.code === 'WORLDBANK_CAPTURE_CANCELLED' ? 'CANCELLED' : 'FAILED';
      job.child = null; return jobView(job);
    });
    return jobView(job);
  }
  function cancel(payload) {
    fields(payload, ['id']);
    const id = identifier(payload.id, 'capture'), job = jobs.get(id);
    if (!job) throw fault('WORLDBANK_CAPTURE_NOT_OWNED', 'This process has no running capture with that identifier. Reopen its retained capture to resume it.', 409);
    if (job.child && job.status === 'RUNNING') {
      job.status = 'CANCELLING';
      if (!job.child.kill('SIGTERM')) throw fault('WORLDBANK_CANCEL_FAILED', 'The capture process could not receive its stop signal. Refresh its current state.', 409);
    }
    return jobView(job);
  }
  async function prepareMerchant(payload) {
    fields(payload, ['exportId', 'origin', 'path', 'payment']);
    identifier(payload.exportId, 'export');
    if (typeof payload.origin !== 'string' || typeof payload.path !== 'string' || !object(payload.payment))
      throw fault('WORLDBANK_MERCHANT_TERMS', 'Supply the public origin, route path and exact payment terms.');
    const retained = await core('export-read', { id: payload.exportId });
    const exportDirectory = resolve(retained.directory ?? '');
    if (exportDirectory !== join(directory, 'exports', payload.exportId))
      throw fault('WORLDBANK_EXPORT_DIRECTORY', 'The source engine returned an unexpected export directory.', 409);
    if (await realpath(exportDirectory) !== exportDirectory)
      throw fault('WORLDBANK_EXPORT_DIRECTORY', 'Use the original canonical export directory.', 409);
    const { loadDatasetConfig } = await import('../dataset-handler.mjs');
    const { buildDatasetSellerConfig } = await import('../dataset-cli.mjs');
    const dataset = await loadDatasetConfig(join(exportDirectory, 'dataset.json'));
    const config = await buildDatasetSellerConfig(dataset,
      { origin: payload.origin, path: payload.path, payment: payload.payment });
    const sellerBytes = json(config);
    await writeImmutable(join(exportDirectory, 'seller.json'), sellerBytes);
    // Re-read the core's immutable closure after preparing its adjacent merchant file.
    const checked = await core('export-read', { id: payload.exportId });
    if (!same(retained.manifest, checked.manifest))
      throw fault('WORLDBANK_EXPORT_CHANGED', 'The reviewed source export changed during merchant preparation.', 409);
    const model = await getPublisher();
    const prepared = await model.act('publisher.prepare', { exportDirectory });
    const binding = {
      schema: 'stellar-forge.worldbank-merchant-binding.v1', exportId: payload.exportId,
      exportDirectory, manifest: checked.manifest,
      seller: { path: 'seller.json', bytes: sellerBytes.length, sha256: sha(sellerBytes) },
      publisherDirectory: model.directory, packageDirectory: prepared.result.packageDirectory
    };
    const bindingDirectory = join(directory, 'merchant-bindings');
    await mkdir(bindingDirectory, { recursive: true, mode: 0o700 });
    if (await realpath(bindingDirectory) !== bindingDirectory)
      throw fault('WORLDBANK_BINDING_DIRECTORY', 'Use the canonical merchant binding directory.', 409);
    const bindingFile = join(bindingDirectory, sha(Buffer.from(payload.exportId)) + '.json');
    await writeImmutable(bindingFile, json(binding));
    return { ...prepared.result, exportId: payload.exportId, bindingFile, binding };
  }
  async function dispatch(action, payload) {
    if (action === 'capture') return capture(payload);
    if (action === 'capture-cancel') return cancel(payload);
    if (action === 'merchant-prepare') {
      const pending = prepareTail.catch(() => {}).then(() => prepareMerchant(payload));
      prepareTail = pending; return pending;
    }
    if (publisherActions.has(action)) return (await (await getPublisher()).act(action, payload)).result;
    if (coreActions.has(action)) return core(action, payload);
    throw fault('WORLDBANK_ACTION', 'Choose a supported World Bank or publisher action.');
  }

  async function exportFile(exportId, filename) {
    identifier(exportId, 'export');
    if (typeof filename !== 'string' || filename.includes('\\') || filename.includes('\0') ||
        filename.split('/').some(part => !part || part === '.' || part === '..'))
      throw fault('WORLDBANK_EXPORT_FILE', 'Choose an original file listed by this export.');
    const retained = await core('export-read', { id: exportId });
    const entry = retained.manifest?.files?.find(file => file.path === filename);
    if (!entry || !Number.isSafeInteger(entry.bytes) || !/^[a-f0-9]{64}$/.test(entry.sha256))
      throw fault('WORLDBANK_EXPORT_FILE', 'This file is not in the reviewed export manifest.', 404);
    const exportDirectory = resolve(retained.directory ?? '');
    if (exportDirectory !== join(directory, 'exports', exportId))
      throw fault('WORLDBANK_EXPORT_DIRECTORY', 'The source engine returned an unexpected export directory.', 409);
    const bytes = await stableBytes(join(exportDirectory, filename));
    if (bytes.length !== entry.bytes || sha(bytes) !== entry.sha256)
      throw fault('WORLDBANK_EXPORT_CHANGED', 'This file differs from its retained export manifest.', 409);
    const contentType = filename.endsWith('.csv') ? 'text/csv; charset=utf-8' :
      filename.endsWith('.json') ? 'application/json; charset=utf-8' : 'application/octet-stream';
    return { bytes, filename: filename.split('/').at(-1), contentType };
  }
  return {
    directory,
    state: () => track(view),
    act: (action, payload = {}) => track(async () => {
      if (!WORLDBANK_ACTIONS.includes(action) || !object(payload))
        throw fault('WORLDBANK_ACTION', 'Choose a supported action and an object payload.');
      return refresh(await dispatch(action, payload));
    }),
    waitCapture: id => track(async () => {
      const job = jobs.get(identifier(id, 'capture'));
      if (!job) throw fault('WORLDBANK_CAPTURE_NOT_OWNED', 'This capture has no execution in this process.', 409);
      return job.settled;
    }),
    readExport: (id, filename) => track(() => exportFile(id, filename)),
    readPublisherExport: (kind, id) => track(async () => (await getPublisher()).readExport(kind, id)),
    close() {
      if (!closePromise) {
        closing = true;
        closePromise = (async () => {
          // Let already accepted action callbacks register their owned capture.
          await Promise.resolve();
          for (const job of jobs.values()) if (job.child && job.status === 'RUNNING') {
            job.status = 'CANCELLING'; job.child.kill('SIGTERM');
          }
          await Promise.allSettled([...operations, ...jobs.values()].map(value => value?.settled ?? value));
          if (openingPublisher) await openingPublisher.catch(() => {});
          if (publisher) await publisher.close();
        })();
      }
      return closePromise;
    }
  };
}

const headers = {
  'cache-control': 'no-store', 'x-content-type-options': 'nosniff',
  'referrer-policy': 'no-referrer', 'cross-origin-resource-policy': 'same-origin',
  'content-security-policy': "default-src 'none'; script-src 'self'; style-src 'self'; connect-src 'self'; img-src 'self' blob:; base-uri 'none'; frame-ancestors 'none'; form-action 'none'"
};
async function requestJson(request) {
  if ((request.headers['content-type'] ?? '').split(';', 1)[0].trim() !== 'application/json')
    throw fault('WORLDBANK_JSON_REQUIRED', 'Send Content-Type application/json.', 415);
  const chunks = []; let size = 0;
  for await (const chunk of request) {
    size += chunk.length;
    if (size > MAX_IMPORT) throw fault('WORLDBANK_INPUT_SIZE', 'The request exceeds 256 MiB.', 413);
    chunks.push(chunk);
  }
  try { return JSON.parse(new TextDecoder('utf-8', { fatal: true }).decode(Buffer.concat(chunks))); }
  catch { throw fault('WORLDBANK_INVALID_JSON', 'Send a valid UTF-8 JSON object.'); }
}

/** The private loopback session owns its capture children and original release process. */
export async function startWorldBankWorkspace({ directory, python, port = 0, operator: supplied, instanceId } = {}) {
  if (!Number.isInteger(port) || port < 0 || port > 65535)
    throw fault('WORLDBANK_PORT', 'Choose a port from 0 to 65535.');
  if (instanceId !== undefined && !/^[a-f0-9]{8}(?:-[a-f0-9]{4}){3}-[a-f0-9]{12}$/.test(instanceId))
    throw fault('WORLDBANK_INSTANCE', 'Use the identity of the supplied original model.');
  const ownsOperator = supplied === undefined;
  const operator = supplied ?? await openWorldBankOperator({ directory, python });
  if (!operator || ['state', 'act', 'readExport', 'readPublisherExport', 'close'].some(name => typeof operator[name] !== 'function'))
    throw fault('WORLDBANK_OPERATOR', 'Supply an original World Bank operator.');
  let assets;
  try {
    assets = new Map(await Promise.all([
      ['/', 'index.html', 'text/html; charset=utf-8'],
      ['/app.js', 'app.js', 'text/javascript; charset=utf-8'],
      ['/style.css', 'style.css', 'text/css; charset=utf-8']
    ].map(async ([route, name, type]) => [route, { bytes: await readFile(join(ROOT, 'ui', name)), type }])));
  } catch (error) { if (ownsOperator) await operator.close().catch(() => {}); throw error; }
  const launch = Object.freeze({ schema: 'stellar-forge.worldbank-workspace-launch.v1', state: 'LISTENING',
    directory: operator.directory, instanceId: instanceId ?? randomUUID(), browserInstanceId: randomUUID(),
    startedAt: new Date().toISOString() });
  const token = randomBytes(32).toString('base64url'), expected = Buffer.from('Bearer ' + token);
  let origin, closing;
  const server = createServer({ maxHeaderSize: 16384, requestTimeout: 30000, headersTimeout: 15000, keepAliveTimeout: 1000 },
    async (request, response) => {
      const reply = (status, value, type = 'application/json; charset=utf-8') => {
        if (response.destroyed) return;
        response.writeHead(status, { ...headers, 'content-type': type });
        response.end(type.startsWith('application/json') && !Buffer.isBuffer(value) ? JSON.stringify(value) : value);
      };
      try {
        if (request.headers.host !== new URL(origin).host ||
            request.headers.origin && request.headers.origin !== origin ||
            request.headers['sec-fetch-site'] === 'cross-site')
          throw fault('WORLDBANK_LOCAL_ORIGIN', 'Open the printed local workspace URL.', 403);
        if (request.method === 'GET' && assets.has(request.url)) {
          const asset = assets.get(request.url); reply(200, asset.bytes, asset.type); return;
        }
        if (request.method === 'GET' && request.url === '/favicon.ico') { reply(204, ''); return; }
        const suppliedToken = Buffer.from(request.headers.authorization ?? '');
        if (suppliedToken.length !== expected.length || !timingSafeEqual(suppliedToken, expected))
          throw fault('WORLDBANK_SESSION_REQUIRED', 'Reopen the session URL printed by the workspace command.', 401);
        if (request.method === 'GET' && request.url === '/api/launch') { reply(200, launch); return; }
        if (request.method === 'GET' && request.url === '/api/state') { reply(200, await operator.state()); return; }
        const download = /^\/api\/exports\/([^/?]+)\/([^?]+)$/.exec(request.url ?? '');
        const publisherDownload = /^\/api\/publisher\/exports\/([^/?]+)\/([^/?]+)$/.exec(request.url ?? '');
        if (request.method === 'GET' && (download || publisherDownload)) {
          const match = download || publisherDownload;
          let first, second;
          try { first = decodeURIComponent(match[1]); second = decodeURIComponent(match[2]); }
          catch { throw fault('WORLDBANK_DOWNLOAD', 'Choose a valid download identifier.'); }
          const file = download ? await operator.readExport(first, second) : await operator.readPublisherExport(first, second);
          response.writeHead(200, { ...headers, 'content-type': file.contentType || 'application/octet-stream',
            'content-length': file.bytes.length,
            'content-disposition': "attachment; filename*=UTF-8''" + encodeURIComponent(file.filename).replaceAll("'", '%27') });
          response.end(file.bytes); return;
        }
        if (request.url !== '/api/action') throw fault('WORLDBANK_NOT_FOUND', 'This workspace route is unavailable.', 404);
        if (request.method !== 'POST') throw fault('WORLDBANK_POST_REQUIRED', 'Use POST for a workspace action.', 405);
        const input = await requestJson(request);
        fields(input, ['action', 'payload']);
        if (!WORLDBANK_ACTIONS.includes(input.action) || !object(input.payload ?? {}))
          throw fault('WORLDBANK_ACTION', 'Choose a supported action and object payload.');
        // An accepted operation survives browser navigation or a closed request.
        reply(200, await operator.act(input.action, input.payload ?? {}));
      } catch (error) {
        if (response.headersSent || response.destroyed) { if (!response.writableEnded) response.end(); return; }
        const status = Number.isInteger(error.status) && error.status >= 400 && error.status <= 599 ? error.status :
          error instanceof TypeError || error instanceof SyntaxError ? 400 : 500;
        reply(status, { error: publicError(error) });
      }
    });
  server.maxRequestsPerSocket = 100;
  server.on('clientError', (_error, socket) => socket.end('HTTP/1.1 400 Bad Request\r\nConnection: close\r\n\r\n'));
  try {
    await new Promise((accept, reject) => {
      server.once('error', reject);
      server.listen(port, '127.0.0.1', () => { server.off('error', reject); accept(); });
    });
    origin = 'http://127.0.0.1:' + server.address().port;
  } catch (error) { if (ownsOperator) await operator.close().catch(() => {}); throw error; }
  return {
    origin, url: origin + '/#' + token, token, operator, launch,
    close() {
      if (!closing) closing = (async () => {
        const stopped = new Promise((accept, reject) => server.close(error => error ? reject(error) : accept()));
        server.closeIdleConnections?.();
        let failure;
        if (ownsOperator) try { await operator.close(); } catch (error) { failure = error; }
        try { await stopped; } catch (error) { failure ??= error; }
        if (failure) throw failure;
      })();
      return closing;
    }
  };
}

#!/usr/bin/env python3
"""World Bank V2 source semantics for the maintained Starforge merchant. MIT."""
from __future__ import annotations

import datetime as dt
import email.utils
import hashlib
import json
import re
import ssl
import urllib.error
import urllib.parse
import urllib.request
from typing import Any

API = "https://api.worldbank.org/v2"
SOURCE_SCHEMA = "stellar-forge.worldbank-selection.v1"
NUMBER = re.compile(r"-?(?:0|[1-9][0-9]*)(?:\.[0-9]+)?(?:[eE][+-]?[0-9]+)?\Z")
IDENTIFIER = re.compile(r"[A-Za-z0-9][A-Za-z0-9_.-]{0,95}\Z")
MAX_PAGE_BYTES = 32 * 1024 * 1024


class SourceError(Exception):
    def __init__(self, code: str, message: str, **details: Any):
        super().__init__(message)
        self.code, self.details = code, details

    def public(self) -> dict:
        return {"code": self.code, "message": str(self), **self.details}


class NumericToken(str):
    """A JSON number's original lexical representation, without float conversion."""


def utc() -> str:
    return dt.datetime.now(dt.timezone.utc).isoformat(timespec="milliseconds").replace("+00:00", "Z")


def digest(raw: bytes) -> str:
    return hashlib.sha256(raw).hexdigest()


def encode(value: Any) -> bytes:
    return (json.dumps(value, ensure_ascii=False, sort_keys=True, indent=2, allow_nan=False) + "\n").encode("utf-8")


def identity(value: Any) -> str:
    return digest(json.dumps(value, ensure_ascii=False, sort_keys=True, separators=(",", ":"), allow_nan=False).encode("utf-8"))


def unique_object(pairs):
    value = {}
    for key, item in pairs:
        if key in value:
            raise SourceError("DUPLICATE_JSON_KEY", "The source response repeats a JSON object key.", key=key)
        value[key] = item
    return value


def parse_source(raw: bytes):
    try:
        return json.loads(raw.decode("utf-8-sig"), parse_float=NumericToken,
                          parse_int=NumericToken, object_pairs_hook=unique_object,
                          parse_constant=lambda token: (_ for _ in ()).throw(ValueError(token)))
    except (UnicodeError, ValueError) as exc:
        raise SourceError("SOURCE_JSON", "The original response is not valid UTF-8 JSON.") from exc


def whole(value, field: str, minimum=0, maximum=1_000_000_000) -> int:
    if value is None or isinstance(value, bool) or not re.fullmatch(r"0|[1-9][0-9]*", str(value)):
        raise SourceError("SOURCE_PAGINATION", "The response has an invalid " + field + ".")
    result = int(value)
    if result < minimum or result > maximum:
        raise SourceError("SOURCE_PAGINATION", "The response has an unsupported " + field + ".")
    return result


def clean_text(value: Any, name: str, *, maximum=20000, allow_empty=True) -> str:
    if not isinstance(value, str) or isinstance(value, NumericToken):
        raise SourceError("SOURCE_FIELD", "The response needs a text " + name + ".")
    if len(value) > maximum or "\x00" in value or (not allow_empty and not value):
        raise SourceError("SOURCE_FIELD", "The response has an invalid " + name + ".")
    return value


def selection(value: Any) -> dict:
    if not isinstance(value, dict) or set(value) - {"schema", "sourceId", "countries", "indicators", "date", "perPage"}:
        raise SourceError("SELECTION", "Choose sourceId, countries, indicators, date and perPage.")
    source = str(value.get("sourceId", "2"))
    if not re.fullmatch(r"[1-9][0-9]{0,7}", source):
        raise SourceError("SELECTION_SOURCE", "Choose the original numeric World Bank source ID.")
    countries = value.get("countries")
    indicators = value.get("indicators")
    if not isinstance(countries, list) or not countries or len(countries) > 300:
        raise SourceError("SELECTION_COUNTRIES", "Choose country or aggregate codes, or the single value all.")
    if countries == ["all"] or countries == ["ALL"]:
        countries = ["all"]
    else:
        if any(not isinstance(item, str) or not re.fullmatch(r"[A-Za-z0-9]{2,3}", item) for item in countries):
            raise SourceError("SELECTION_COUNTRIES", "Use the source's two- or three-character country and aggregate codes.")
        countries = sorted(set(item.upper() for item in countries))
    if not isinstance(indicators, list) or not 1 <= len(indicators) <= 60 or any(
        not isinstance(item, str) or not IDENTIFIER.fullmatch(item) for item in indicators
    ):
        raise SourceError("SELECTION_INDICATORS", "Choose 1–60 original indicator codes from the selected source.")
    indicators = sorted(set(item.upper() for item in indicators))
    period = value.get("date", "")
    # Explicit, comparable windows. The UI keeps annual, monthly and quarterly periods separate.
    match = re.fullmatch(r"([0-9]{4}(?:(?:M(?:0[1-9]|1[0-2]))|(?:Q[1-4]))?)(?::([0-9]{4}(?:(?:M(?:0[1-9]|1[0-2]))|(?:Q[1-4]))?))?", period) if isinstance(period, str) else None
    if not match:
        raise SourceError("SELECTION_DATE", "Use an explicit year, month, quarter or matching range, such as 2018:2024.")
    start, end = match[1], match[2] or match[1]
    if len(start) != len(end) or start > end:
        raise SourceError("SELECTION_DATE", "Use an ordered date range with one consistent frequency.")
    per_page = value.get("perPage", 1000)
    if isinstance(per_page, bool) or not isinstance(per_page, int) or not 1 <= per_page <= 10000:
        raise SourceError("SELECTION_PAGE", "Choose an integer page size from 1 to 10,000.")
    result = {"schema": SOURCE_SCHEMA, "sourceId": source, "countries": countries,
              "indicators": indicators, "date": period, "perPage": per_page}
    for part in (";".join(countries), ";".join(indicators)):
        if len(part) > 1500:
            raise SourceError("SELECTION_URL", "The selected codes exceed the source's 1,500-character URL-segment limit.")
    url_for(result, "data", 1)
    return result


def url_for(spec: dict, kind: str, page: int, indicator_id: str | None = None) -> str:
    page = whole(page, "page", 1)
    if indicator_id is not None:
        if kind != "indicators" or not isinstance(indicator_id, str) or indicator_id.upper() not in spec["indicators"]:
            raise SourceError("SOURCE_INDICATOR", "Choose one original indicator from this saved selection.")
        indicator_id = indicator_id.upper()
    countries = ";".join(spec["countries"])
    indicators = ";".join(spec["indicators"])
    params = {"format": "json", "page": str(page), "per_page": str(spec["perPage"])}
    if kind == "data":
        path = "/country/" + countries + "/indicator/" + indicators
        params.update(source=spec["sourceId"], date=spec["date"], footnote="y")
    elif kind == "countries":
        path = "/country/" + countries
    elif kind == "indicators":
        # The native metadata endpoint needs one indicator at a time. A null
        # indicator_id is retained for importing an earlier combined response.
        path = "/indicator/" + (indicator_id if indicator_id is not None else indicators)
        params["source"] = spec["sourceId"]
    elif kind == "sources":
        path = "/source/" + spec["sourceId"]
    else:
        raise SourceError("SOURCE_KIND", "Unsupported original source collection.")
    url = API + path + "?" + urllib.parse.urlencode(params)
    if len(url) > 4000:
        raise SourceError("SELECTION_URL", "The request exceeds the source's 4,000-character URL limit.")
    return url


def catalog_url(kind: str, page: int, source_id="2") -> str:
    paths = {"countries": "/country", "sources": "/source", "indicators": "/indicator"}
    if kind not in paths:
        raise SourceError("CATALOG_KIND", "Choose countries, sources or indicators.")
    params = {"format": "json", "per_page": "1000", "page": str(whole(page, "page", 1))}
    if kind == "indicators":
        if not re.fullmatch(r"[1-9][0-9]{0,7}", str(source_id)):
            raise SourceError("SELECTION_SOURCE", "Use a numeric source ID.")
        params["source"] = str(source_id)
    return API + paths[kind] + "?" + urllib.parse.urlencode(params)


def same_request(actual: str, expected: str) -> bool:
    """Accept equivalent query ordering while retaining the original request URL."""
    def parts(value):
        if not isinstance(value, str):
            return None
        parsed = urllib.parse.urlsplit(value)
        if (parsed.scheme != "https" or parsed.hostname != "api.worldbank.org"
                or parsed.port not in (None, 443) or parsed.username or parsed.password or parsed.fragment):
            return None
        query = urllib.parse.parse_qsl(parsed.query, keep_blank_values=True, strict_parsing=True)
        if len({key for key, _ in query}) != len(query):
            return None
        return urllib.parse.unquote(parsed.path), sorted(query)
    try:
        left, right = parts(actual), parts(expected)
        return left is not None and left == right
    except (ValueError, UnicodeError):
        return False


class SameSourceRedirect(urllib.request.HTTPRedirectHandler):
    def redirect_request(self, request, fp, code, msg, headers, newurl):
        parsed = urllib.parse.urlsplit(newurl)
        if parsed.scheme != "https" or parsed.hostname != "api.worldbank.org" or parsed.port not in (None, 443) or parsed.username or parsed.password:
            raise SourceError("SOURCE_REDIRECT", "The World Bank request redirected outside its original HTTPS host.")
        return super().redirect_request(request, fp, code, msg, headers, newurl)


def retry_at(header: str | None) -> str | None:
    if not header:
        return None
    try:
        if re.fullmatch(r"[0-9]+", header.strip()):
            value = dt.datetime.now(dt.timezone.utc) + dt.timedelta(seconds=int(header.strip()))
        else:
            value = email.utils.parsedate_to_datetime(header)
            if value.tzinfo is None:
                value = value.replace(tzinfo=dt.timezone.utc)
        return value.astimezone(dt.timezone.utc).isoformat(timespec="seconds").replace("+00:00", "Z")
    except (ValueError, TypeError, OverflowError):
        return None


def request_page(url: str, timeout=45) -> tuple[bytes, dict]:
    parsed = urllib.parse.urlsplit(url)
    if parsed.scheme != "https" or parsed.hostname != "api.worldbank.org" or not parsed.path.startswith("/v2/") or parsed.username or parsed.password:
        raise SourceError("SOURCE_URL", "Only the original World Bank V2 HTTPS endpoint is supported.")
    opener = urllib.request.build_opener(SameSourceRedirect(), urllib.request.HTTPSHandler(context=ssl.create_default_context()))
    request = urllib.request.Request(url, headers={
        "Accept": "application/json", "Accept-Encoding": "identity",
        "User-Agent": "Starforge-WorldBank/1.0 (+https://github.com/woahwhattheheck/public-commons-sprint-2026)",
    })
    started = utc()
    try:
        response = opener.open(request, timeout=timeout)
    except urllib.error.HTTPError as exc:
        raw = exc.read(MAX_PAGE_BYTES + 1)
        headers = dict(exc.headers.items())
        raise SourceError("SOURCE_HTTP", "World Bank returned HTTP " + str(exc.code) + ".",
                          httpStatus=exc.code, url=url, retryAt=retry_at(exc.headers.get("Retry-After")),
                          responseSha256=digest(raw), responseBytes=len(raw)) from exc
    except (urllib.error.URLError, TimeoutError, OSError) as exc:
        raise SourceError("SOURCE_TRANSPORT", "The original World Bank request could not complete.",
                          url=url, detail=str(exc)) from exc
    with response:
        raw = response.read(MAX_PAGE_BYTES + 1)
        if len(raw) > MAX_PAGE_BYTES:
            raise SourceError("SOURCE_SIZE", "The original response exceeds 32 MiB. Choose a smaller source page size.")
        if response.headers.get("Content-Encoding", "identity").lower() not in ("identity", ""):
            raise SourceError("SOURCE_ENCODING", "The source returned an unexpected compressed representation.")
        metadata = {"url": url, "finalUrl": response.geturl(), "status": response.status,
                    "startedAt": started, "receivedAt": utc(), "headers": dict(response.headers.items()),
                    "sha256": digest(raw), "bytes": len(raw)}
    return raw, metadata


def envelope(raw: bytes, expected_page: int, expected: dict | None = None) -> tuple[dict, list]:
    value = parse_source(raw)
    if isinstance(value, list) and value and isinstance(value[0], dict) and "message" in value[0]:
        raise SourceError("SOURCE_API", "The World Bank API rejected the original selection.",
                          sourceMessages=value[0]["message"])
    if not isinstance(value, list) or len(value) != 2 or not isinstance(value[0], dict) or (value[1] is not None and not isinstance(value[1], list)):
        raise SourceError("SOURCE_ENVELOPE", "Expected the original World Bank metadata and record array.")
    meta, rows = value[0], value[1] or []
    required = ("page", "pages", "per_page", "total")
    if any(key not in meta for key in required):
        raise SourceError("SOURCE_PAGINATION", "The original response omits pagination metadata.")
    normalized = {"page": whole(meta["page"], "page", 1),
                  "pages": whole(meta["pages"], "pages"),
                  "perPage": whole(meta["per_page"], "per_page", 1),
                  "total": whole(meta["total"], "total"),
                  "sourceId": None if meta.get("sourceid") is None else str(meta["sourceid"]),
                  "lastUpdated": None if meta.get("lastupdated") is None else str(meta["lastupdated"])}
    if normalized["page"] != expected_page or len(rows) > normalized["perPage"]:
        raise SourceError("SOURCE_PAGE_ID", "The response does not match the requested original page.")
    if normalized["total"] == 0:
        if rows or normalized["pages"] not in (0, 1) or expected_page != 1:
            raise SourceError("SOURCE_PAGINATION", "The empty population has inconsistent original pagination.")
    elif normalized["pages"] != (normalized["total"] + normalized["perPage"] - 1) // normalized["perPage"]:
        raise SourceError("SOURCE_PAGINATION", "The original page count differs from its total and page size.")
    if normalized["total"] and (not rows or expected_page > normalized["pages"]):
        raise SourceError("SOURCE_PAGINATION", "The original continuation ends before its declared population.")
    if expected:
        fields = ("pages", "perPage", "total", "sourceId", "lastUpdated")
        if any(normalized[key] != expected[key] for key in fields):
            raise SourceError("SOURCE_CHANGED", "The source population changed between pages. Retain this capture and start a new capture.",
                              previous={key: expected[key] for key in fields},
                              current={key: normalized[key] for key in fields})
    if any(not isinstance(row, dict) for row in rows):
        raise SourceError("SOURCE_RECORD", "A source record is not a JSON object.")
    return normalized, rows


def normalize_observation(row: dict, spec: dict, page: int, position: int, countries: dict) -> dict:
    country, indicator = row.get("country"), row.get("indicator")
    if not isinstance(country, dict) or not isinstance(indicator, dict):
        raise SourceError("SOURCE_OBSERVATION", "The original observation needs country and indicator identities.")
    country_id = clean_text(country.get("id"), "country id", maximum=20, allow_empty=False)
    indicator_id = clean_text(indicator.get("id"), "indicator id", maximum=96, allow_empty=False)
    iso3 = clean_text(row.get("countryiso3code", ""), "country ISO/WB code", maximum=20)
    period = clean_text(row.get("date"), "period", maximum=40, allow_empty=False)
    if indicator_id.upper() not in spec["indicators"]:
        raise SourceError("SOURCE_OBSERVATION_SCOPE", "An observation belongs to an unselected indicator.")
    if spec["countries"] != ["all"] and country_id.upper() not in spec["countries"] and iso3.upper() not in spec["countries"]:
        raise SourceError("SOURCE_OBSERVATION_SCOPE", "An observation belongs to an unselected country or aggregate.")
    lower, _, upper = spec["date"].partition(":")
    upper = upper or lower
    if len(period) != len(lower) or not lower <= period <= upper:
        raise SourceError("SOURCE_OBSERVATION_SCOPE", "An observation lies outside the selected period.")
    value = row.get("value")
    if value is not None and (not isinstance(value, NumericToken) or not NUMBER.fullmatch(value)):
        raise SourceError("SOURCE_VALUE", "The original observation value must be a JSON number or null.")
    reference = countries.get(country_id.upper()) or countries.get(iso3.upper())
    if reference is None:
        raise SourceError("SOURCE_COUNTRY_METADATA", "No retained country metadata matches the original observation.", country=country_id)
    region = reference.get("region") if isinstance(reference.get("region"), dict) else {}
    key = identity([spec["sourceId"], country_id, iso3, indicator_id, period])
    output = {
        "key": key, "rowId": f"{page}:{position}", "source_id": spec["sourceId"],
        "country_id": country_id, "country_iso3": iso3,
        "country_name": clean_text(country.get("value", ""), "country name"),
        "indicator_id": indicator_id, "indicator_name": clean_text(indicator.get("value", ""), "indicator name"),
        "period": period, "value": None if value is None else str(value),
        "value_state": "missing" if value is None else "present",
        "unit": clean_text(row.get("unit", ""), "unit"),
        "obs_status": clean_text(row.get("obs_status", ""), "observation status"),
        "decimal": str(row.get("decimal", "")),
        "footnote": clean_text(row.get("footnote", "") or "", "footnote", maximum=100000),
        "region": str(region.get("value", "")),
        "aggregate": str(region.get("id", "")) == "NA",
        "source_page": page, "source_row": position,
    }
    output["contentSha256"] = identity({key: value for key, value in output.items()
                                       if key not in ("rowId", "source_page", "source_row")})
    return output

