"""MIT. Local operator console over the same retained XML workspace and SF30 engine."""
from __future__ import annotations

from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
import io
import json
from pathlib import Path
import secrets
import shutil
import threading
from urllib.parse import urlsplit, parse_qs, unquote
import zipfile

from workspace import Workspace, InputError, MAX_SOURCE, HERE, json_bytes, load_json


class LimitedReader:
    def __init__(self, source, length: int):
        self.source, self.remaining = source, length

    def read(self, size: int = -1):
        if self.remaining == 0:
            return b""
        block = self.source.read(min(self.remaining, size if size >= 0 else self.remaining))
        if not block:
            raise InputError("Upload ended before its declared content length")
        self.remaining -= len(block)
        return block


class OperatorServer(ThreadingHTTPServer):
    daemon_threads = False
    block_on_close = True

    def __init__(self, workspace: Workspace, port: int = 0, *, assets_directory: Path | None = None,
                 handler_class=None):
        self.workspace, self.token = workspace, secrets.token_urlsafe(32)
        self.assets_directory = assets_directory or HERE / "public"
        self.slots = threading.BoundedSemaphore(8)
        super().__init__(("127.0.0.1", port), handler_class or Handler)
        authority = "127.0.0.1" if self.server_port == 80 else f"127.0.0.1:{self.server_port}"
        self.origin = "http://" + authority
        self.url = self.origin + "/#" + self.token

    def process_request(self, request, client_address):
        if not self.slots.acquire(blocking=False):
            self.shutdown_request(request)
            return
        try:
            super().process_request(request, client_address)
        except Exception:
            self.slots.release()
            raise

    def process_request_thread(self, request, client_address):
        try:
            super().process_request_thread(request, client_address)
        finally:
            self.slots.release()


class Handler(BaseHTTPRequestHandler):
    server_version = "SF30-XML"
    protocol_version = "HTTP/1.0"

    def setup(self):
        super().setup()
        self.connection.settimeout(60)

    def log_message(self, *_):
        pass  # No private capabilities, paths, query values or XML content in request logs.

    def _gate(self, api: bool = True):
        target = urlsplit(self.path)
        if len(self.headers.get_all("Host", [])) != 1 or len(self.headers.get_all("Origin", [])) > 1:
            raise PermissionError("Repeated local origin or host headers are not accepted")
        if target.scheme or target.netloc or self.headers.get("Host") != urlsplit(self.server.origin).netloc:
            raise PermissionError("Invalid local host")
        if self.headers.get("Origin") not in {None, self.server.origin}:
            raise PermissionError("Cross-origin requests are not accepted")
        if api:
            supplied = self.headers.get("Authorization", "")
            if not secrets.compare_digest(supplied.encode(), ("Bearer " + self.server.token).encode()):
                raise PermissionError("Open this process's private console link")
        return target

    def _headers(self, status, content_type, length, filename=None):
        self.send_response(status)
        self.send_header("Content-Type", content_type)
        self.send_header("Content-Length", str(length))
        self.send_header("Cache-Control", "no-store")
        self.send_header("X-Content-Type-Options", "nosniff")
        self.send_header("Referrer-Policy", "no-referrer")
        self.send_header("Cross-Origin-Resource-Policy", "same-origin")
        self.send_header("Content-Security-Policy", "default-src 'none'; script-src 'self'; style-src 'self'; connect-src 'self'; base-uri 'none'; form-action 'none'; frame-ancestors 'none'")
        if filename:
            self.send_header("Content-Disposition", f'attachment; filename="{filename}"')
        self.end_headers()

    def _json(self, value, status=200):
        data = json_bytes(value)
        self._headers(status, "application/json; charset=utf-8", len(data))
        self.wfile.write(data)

    def _body(self, maximum=131072):
        raw = self.headers.get("Content-Length", "")
        if self.headers.get("Transfer-Encoding") or len(self.headers.get_all("Content-Length", [])) != 1 or not raw.isdecimal():
            raise InputError("A single Content-Length is required")
        length = int(raw)
        if length > maximum:
            raise InputError("Request exceeds its size limit")
        return LimitedReader(self.rfile, length)

    def _download(self, path: Path, filename: str, media="application/octet-stream"):
        with path.open("rb") as stream:
            self._headers(200, media, path.stat().st_size, filename)
            shutil.copyfileobj(stream, self.wfile, 65536)

    def _run(self, callback):
        try:
            callback()
        except PermissionError as e:
            self._json({"error": str(e)}, 403)
        except (InputError, ValueError, KeyError, zipfile.BadZipFile) as e:
            self._json({"error": str(e)}, 400)
        except FileNotFoundError:
            self._json({"error": "Retained file or operation was not found"}, 404)
        except (BrokenPipeError, ConnectionResetError, TimeoutError):
            pass
        except Exception:
            self._json({"error": "The local operation failed; the retained workspace remains available"}, 500)

    def do_GET(self):
        self._run(self._get)

    def _get(self):
        target = self._gate(api=False)
        assets = {"/": ("index.html", "text/html; charset=utf-8"),
                  "/app.js": ("app.js", "text/javascript; charset=utf-8"),
                  "/style.css": ("style.css", "text/css; charset=utf-8")}
        if target.path in assets:
            name, media = assets[target.path]
            body = (self.server.assets_directory / name).read_bytes()
            self._headers(200, media, len(body)); self.wfile.write(body)
            return
        self._gate()
        query = parse_qs(target.query, keep_blank_values=True)
        if any(len(values) != 1 for values in query.values()):
            raise InputError("Repeated query parameters are not accepted")
        q = {k: v[0] for k, v in query.items()}
        ws = self.server.workspace
        if target.path == "/api/state":
            self._json(ws.state())
        elif target.path == "/api/source":
            self._json(ws.source(q["id"]))
        elif target.path == "/api/plan":
            self._json({"id": q["id"], "plan": ws.plan(q["id"])})
        elif target.path == "/api/changes":
            self._json(ws.comparison_page(q["id"], int(q.get("offset", "0")), int(q.get("limit", "50"))))
        elif target.path == "/api/changes/download":
            self._download(ws.comparison_file(q["id"]), ws.kind + "-edition-changes.jsonl", "application/x-ndjson")
        elif target.path in {"/api/export", "/api/dataset-export"}:
            with ws.mutex, ws.scratch() as temp:
                if target.path == "/api/export":
                    archive = temp / (ws.kind + "-project.zip")
                    ws.export_packet(q["build"], archive)
                else:
                    folder = temp / "dataset"
                    ws.export_dataset(q["build"], folder)
                    archive = temp / "sf30-dataset.zip"
                    with zipfile.ZipFile(archive, "x", compression=zipfile.ZIP_DEFLATED) as out:
                        for name in ["data.csv", "dataset.json", ws.lineage_name]:
                            out.write(folder / name, name)
                    archive.chmod(0o600)
                self._download(archive, archive.name, "application/zip")
        else:
            self._json({"error": "Unknown local route"}, 404)

    def do_POST(self):
        self._run(self._post)

    def _post(self):
        target = self._gate()
        ws = self.server.workspace
        if target.path == "/api/source":
            name = unquote(self.headers.get("X-" + ws.kind.upper() + "-Name", ws.source_name))
            label = unquote(self.headers.get("X-" + ws.kind.upper() + "-Label", name))
            self._json(ws.add_source(self._body(MAX_SOURCE), label, name), 201)
            return
        if target.path == "/api/import":
            with ws.mutex, ws.scratch() as temp:
                path = temp / "input.zip"
                with path.open("xb") as out:
                    path.chmod(0o600)
                    shutil.copyfileobj(self._body(2 * MAX_SOURCE), out, 65536)
                self._json(ws.import_packet(path), 201)
            return
        body = load_json(self._body().read())
        if not isinstance(body, dict):
            raise InputError("Expected a JSON object")
        if target.path == "/api/plan":
            self._json(ws.save_plan(body), 201)
        elif target.path == "/api/build":
            self._json(ws.build(body["source"], body["plan"]), 201)
        elif target.path == "/api/query":
            self._json(ws.query(body["build"], body.get("query", {})))
        elif target.path == "/api/compare":
            self._json(ws.compare(body["before"], body["after"]), 201)
        else:
            self._json({"error": "Unknown local route"}, 404)

"""MIT. Retained XML editions, mappings, native builds and portable customer handoff."""
from __future__ import annotations

from contextlib import contextmanager
from dataclasses import dataclass
import csv
import hashlib
import io
import json
import os
from pathlib import Path
import queue
import re
import shutil
import sqlite3
import stat
import subprocess
import tempfile
import threading
import time
import zipfile

from xml_source import InputError, MAX_SOURCE, inventory, validate_plan, extract, dataset_spec

HERE = Path(__file__).resolve().parent
HEX = re.compile(r"[0-9a-f]{64}\Z")
VERSION = "stellar-forge.xml-workspace.v1"
BUILD = "stellar-forge.xml-build.v1"
PACKET = "stellar-forge.xml-packet.v1"


@dataclass(frozen=True)
class SourceFormat:
    """Trusted local parsing functions sharing the retained dataset workflow."""
    kind: str
    label: str
    inventory: object
    validate_plan: object
    extract: object
    dataset_spec: object

    def __post_init__(self):
        if not re.fullmatch(r"[a-z][a-z0-9-]{0,31}", self.kind):
            raise InputError("Source format kind must be a short identifier")
        if not isinstance(self.label, str) or not self.label or len(self.label) > 64:
            raise InputError("Source format label must be short text")
        if any(not callable(getattr(self, name)) for name in
               ["inventory", "validate_plan", "extract", "dataset_spec"]):
            raise InputError("Source format requires its complete local parser")


XML_FORMAT = SourceFormat("xml", "XML", inventory, validate_plan, extract, dataset_spec)


def json_bytes(value) -> bytes:
    return (json.dumps(value, ensure_ascii=False, sort_keys=True, separators=(",", ":"), allow_nan=False) + "\n").encode()


def load_json(data: bytes | str):
    def pairs(items):
        result = {}
        for key, value in items:
            if key in result:
                raise InputError(f"Duplicate JSON field: {key}")
            result[key] = value
        return result
    def constant(_):
        raise InputError("Non-finite JSON numbers are not accepted")
    try:
        return json.loads(data, object_pairs_hook=pairs, parse_constant=constant)
    except (UnicodeError, json.JSONDecodeError) as e:
        raise InputError("Invalid UTF-8 JSON") from e


def digest(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def checked_id(value: str) -> str:
    if not isinstance(value, str) or not HEX.fullmatch(value):
        raise InputError("Expected a complete retained source, mapping or build ID")
    return value


def private_write(path: Path, data: bytes):
    with os.fdopen(os.open(path, os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o600), "wb") as out:
        out.write(data)
        out.flush()
        os.fsync(out.fileno())


def regular(path: Path, max_bytes: int = MAX_SOURCE):
    info = path.lstat()
    if not stat.S_ISREG(info.st_mode) or info.st_nlink != 1 or info.st_size > max_bytes:
        raise InputError("Expected a private single-link regular file within the size limit")
    if os.name == "posix" and (info.st_mode & 0o077 or info.st_uid != os.getuid()):
        raise InputError("Workspace files must be owned by the operator and private")
    return info


def file_digest(path: Path, limit: int = MAX_SOURCE) -> str:
    regular(path, limit)
    h = hashlib.sha256()
    total = 0
    with path.open("rb") as stream:
        while block := stream.read(1048576):
            total += len(block)
            if total > limit:
                raise InputError("File exceeds its declared size limit")
            h.update(block)
    return h.hexdigest()


def sync_dir(path: Path):
    if os.name == "posix":
        fd = os.open(path, os.O_RDONLY | os.O_DIRECTORY)
        try:
            os.fsync(fd)
        finally:
            os.close(fd)


class NativeEngine:
    """One serialized original Node engine per workspace; discard it on timeout."""
    def __init__(self):
        self.process = None
        self.lock = threading.RLock()
        self.sequence = 0
        self.replies = queue.Queue(maxsize=2)
        self.errors = None

    def _start(self):
        self.replies = queue.Queue(maxsize=2)
        self.errors = tempfile.TemporaryFile()
        try:
            self.process = subprocess.Popen(
                [os.environ.get("SF30_XML_NODE", "node"), "--max-old-space-size=1024", str(HERE / "native.mjs")],
                stdin=subprocess.PIPE, stdout=subprocess.PIPE, stderr=self.errors, bufsize=-1)
        except OSError as e:
            self.errors.close()
            self.errors = None
            raise InputError("Node 22 is required for the original SF30 dataset engine; set SF30_XML_NODE if needed") from e
        process, replies = self.process, self.replies
        def read():
            try:
                while line := process.stdout.readline(2 * 1024 * 1024):
                    if not line.endswith(b"\n"):
                        raise InputError("Native response exceeded the protocol limit")
                    replies.put(line)
            except Exception:
                pass
            finally:
                try:
                    replies.put_nowait(None)
                except queue.Full:
                    pass
        threading.Thread(target=read, daemon=True).start()

    def query(self, config: Path, query: dict | None = None) -> dict:
        with self.lock:
            if self.process is None:
                self._start()
            self.sequence += 1
            request = json_bytes({"id": self.sequence, "config": str(config), "query": query or {}})
            if len(request) > 65536:
                raise InputError("Native query exceeds 64 KiB")
            try:
                self.process.stdin.write(request)
                self.process.stdin.flush()
                raw = self.replies.get(timeout=120)
                if raw is None:
                    raise InputError("Original dataset engine exited while loading; reduce declared data size or available-memory pressure")
                result = load_json(raw)
                if result.get("id") != self.sequence:
                    raise InputError("Native response identity mismatch")
                if not result.get("ok"):
                    raise InputError(result.get("error", "Original dataset engine rejected the input"))
                return result
            except queue.Empty as e:
                self.close()
                raise InputError("Original dataset operation exceeded 120 seconds; retained inputs remain available") from e
            except (OSError, InputError):
                self.close()
                raise

    def close(self):
        with self.lock:
            if self.process is not None:
                p, self.process = self.process, None
                try:
                    p.stdin.close()
                    p.wait(timeout=3)
                except (OSError, subprocess.TimeoutExpired):
                    p.kill()
                    p.wait()
                finally:
                    p.stdout.close()
            if self.errors is not None:
                self.errors.close()
                self.errors = None


class Workspace:
    def __init__(self, root: str | Path, create: bool = False, *, source_format: SourceFormat | None = None):
        self.format = source_format or XML_FORMAT
        if not isinstance(self.format, SourceFormat):
            raise InputError("Use a trusted local SourceFormat adapter")
        self.kind, self.label = self.format.kind, self.format.label
        self.source_name = "source." + self.kind
        self.lineage_name = self.kind + "-lineage.json"
        self.version = f"stellar-forge.{self.kind}-workspace.v1"
        self.build_schema = f"stellar-forge.{self.kind}-build.v1"
        self.packet_schema = f"stellar-forge.{self.kind}-packet.v1"
        self.comparison_schema = f"stellar-forge.{self.kind}-comparison.v1"
        root = Path(root).expanduser().absolute()
        if create:
            root.mkdir(mode=0o700, parents=True, exist_ok=False)
            for name in ["sources", "plans", "builds", "comparisons", "tmp"]:
                (root / name).mkdir(mode=0o700)
            private_write(root / "workspace.json", json_bytes({"schema": self.version}))
        self.root = root.resolve(strict=True)
        info = self.root.stat()
        if os.name == "posix" and (info.st_uid != os.getuid() or info.st_mode & 0o077):
            raise InputError("Use a private, operator-owned workspace directory (mode 0700)")
        regular(self.root / "workspace.json", 4096)
        if load_json((self.root / "workspace.json").read_bytes()) != {"schema": self.version}:
            raise InputError(f"Unsupported {self.label} workspace version")
        for name in ["sources", "plans", "builds", "comparisons", "tmp"]:
            p = self.root / name
            if p.is_symlink() or not p.is_dir():
                raise InputError("Workspace directories must be real directories")
        flags = os.O_RDWR | os.O_CREAT | getattr(os, "O_NOFOLLOW", 0)
        self.lease = os.fdopen(os.open(self.root / ".lock", flags, 0o600), "r+b", buffering=0)
        try:
            if os.name == "posix":
                import fcntl
                fcntl.flock(self.lease, fcntl.LOCK_EX | fcntl.LOCK_NB)
            else:
                import msvcrt
                if not self.lease.read(1):
                    self.lease.write(b"0")
                self.lease.seek(0)
                msvcrt.locking(self.lease.fileno(), msvcrt.LK_NBLCK, 1)
        except OSError as e:
            self.lease.close()
            raise InputError(f"This {self.label} workspace is already open; use its existing console or close that process") from e
        db_path = self.root / "workspace.sqlite"
        if not db_path.exists():
            private_write(db_path, b"")
        regular(db_path)
        self.db = sqlite3.connect(db_path, check_same_thread=False)
        self.db.row_factory = sqlite3.Row
        self.db.executescript("""
            PRAGMA journal_mode=DELETE;
            PRAGMA foreign_keys=ON;
            CREATE TABLE IF NOT EXISTS sources(id TEXT PRIMARY KEY,label TEXT NOT NULL,name TEXT NOT NULL,
                bytes INTEGER NOT NULL,inventory TEXT NOT NULL,created REAL NOT NULL);
            CREATE TABLE IF NOT EXISTS plans(id TEXT PRIMARY KEY,body TEXT NOT NULL,created REAL NOT NULL);
            CREATE TABLE IF NOT EXISTS builds(id TEXT PRIMARY KEY,source TEXT REFERENCES sources(id),
                plan TEXT REFERENCES plans(id),review TEXT NOT NULL,created REAL NOT NULL);
            CREATE TABLE IF NOT EXISTS comparisons(id TEXT PRIMARY KEY,before_id TEXT REFERENCES builds(id),
                after_id TEXT REFERENCES builds(id),summary TEXT NOT NULL,created REAL NOT NULL);
        """)
        self.mutex = threading.RLock()
        self.native = NativeEngine()

    def close(self):
        self.native.close()
        self.db.close()
        self.lease.close()

    def __enter__(self):
        return self

    def __exit__(self, *_):
        self.close()

    @contextmanager
    def scratch(self):
        path = Path(tempfile.mkdtemp(prefix="operation-", dir=self.root / "tmp"))
        try:
            yield path
        finally:
            shutil.rmtree(path, ignore_errors=True)

    def state(self) -> dict:
        with self.mutex:
            return {"schema": self.version,
                "sources": [dict(r) for r in self.db.execute("SELECT id,label,name,bytes,created FROM sources ORDER BY created DESC")],
                "plans": [{"id": r["id"], "name": load_json(r["body"])["name"], "created": r["created"]}
                          for r in self.db.execute("SELECT * FROM plans ORDER BY created DESC")],
                "builds": [load_json(r["review"]) for r in self.db.execute("SELECT review FROM builds ORDER BY created DESC")],
                "comparisons": [load_json(r["summary"]) for r in self.db.execute("SELECT summary FROM comparisons ORDER BY created DESC")]}

    def source(self, ident: str) -> dict:
        with self.mutex:
            row = self.db.execute("SELECT * FROM sources WHERE id=?", (checked_id(ident),)).fetchone()
            if row is None:
                raise InputError("Unknown retained source")
            result = dict(row)
            result["inventory"] = load_json(result["inventory"])
            return result

    def add_source(self, stream, label: str | None = None, name: str | None = None) -> dict:
        label = label if label is not None else self.label + " source"
        name = name if name is not None else self.source_name
        if not isinstance(label, str) or not label.strip() or len(label) > 160:
            raise InputError("Source label must be 1–160 characters")
        name = Path(name.replace("\\", "/")).name[:160]
        with self.mutex, self.scratch() as temp:
            target = temp / self.source_name
            h, total = hashlib.sha256(), 0
            with os.fdopen(os.open(target, os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o600), "wb") as output:
                while block := stream.read(65536):
                    total += len(block)
                    if total > MAX_SOURCE:
                        raise InputError(f"{self.label} source exceeds 256 MiB")
                    h.update(block)
                    output.write(block)
                output.flush()
                os.fsync(output.fileno())
            ident = h.hexdigest()
            if self.db.execute("SELECT 1 FROM sources WHERE id=?", (ident,)).fetchone():
                if file_digest(self.root / "sources" / (ident + "." + self.kind)) != ident:
                    raise InputError("Retained source bytes were changed")
                return self.source(ident)
            with target.open("rb") as input_file:
                shape = self.format.inventory(input_file)
            destination = self.root / "sources" / (ident + "." + self.kind)
            if destination.exists():
                if file_digest(destination) != ident:
                    raise InputError("Retained source path contains different bytes")
            else:
                os.replace(target, destination)
                sync_dir(destination.parent)
            with self.db:
                self.db.execute("INSERT INTO sources VALUES(?,?,?,?,?,?)", (ident, label, name, total,
                                json_bytes(shape).decode(), time.time()))
            return self.source(ident)

    def save_plan(self, raw: dict) -> dict:
        plan = self.format.validate_plan(raw)
        data = json_bytes(plan)
        if len(data) > 65536:
            raise InputError("Mapping exceeds 64 KiB")
        ident = digest(data)
        with self.mutex:
            path = self.root / "plans" / (ident + ".json")
            if path.exists():
                if file_digest(path, 65536) != ident:
                    raise InputError("Retained mapping bytes were changed")
            else:
                private_write(path, data)
                sync_dir(path.parent)
            with self.db:
                self.db.execute("INSERT OR IGNORE INTO plans VALUES(?,?,?)", (ident, data.decode(), time.time()))
            return {"id": ident, "plan": plan}

    def plan(self, ident: str) -> dict:
        checked_id(ident)
        with self.mutex:
            if not self.db.execute("SELECT 1 FROM plans WHERE id=?", (ident,)).fetchone():
                raise InputError("Unknown retained mapping")
            path = self.root / "plans" / (ident + ".json")
            if file_digest(path, 65536) != ident:
                raise InputError("Retained mapping bytes were changed")
            return load_json(path.read_bytes())

    def build_view(self, ident: str) -> dict:
        checked_id(ident)
        with self.mutex:
            row = self.db.execute("SELECT review FROM builds WHERE id=?", (ident,)).fetchone()
            if row is None:
                raise InputError("Unknown completed build")
            return load_json(row["review"])

    def _build_path(self, ident: str, name: str) -> Path:
        view = self.build_view(ident)
        limits = {"data.csv": MAX_SOURCE, "dataset.json": 65536, "review.json": 131072,
                  "rows.sqlite": 4 * MAX_SOURCE}
        if name not in limits:
            raise InputError("Unknown native build artifact")
        path = self.root / "builds" / ident / name
        regular(path, limits[name])
        if name == "review.json" and path.read_bytes() != json_bytes(view):
            raise InputError("Completed review bytes were changed")
        if name in view["files"] and file_digest(path, limits[name]) != view["files"][name]["sha256"]:
            raise InputError("Completed build artifact was changed")
        return path

    def build(self, source_id: str, plan_id: str, expected: dict | None = None) -> dict:
        with self.mutex:
            self.source(source_id)
            plan = self.plan(plan_id)
            ident = digest(json_bytes({"schema": self.build_schema, "source": source_id, "plan": plan_id}))
            if self.db.execute("SELECT 1 FROM builds WHERE id=?", (ident,)).fetchone():
                result = self.build_view(ident)
                for name in ["data.csv", "dataset.json", "rows.sqlite"]:
                    self._build_path(ident, name)
                self._expected(result, expected)
                return result
            source_path = self.root / "sources" / (source_id + "." + self.kind)
            if file_digest(source_path) != source_id:
                raise InputError("Retained source bytes were changed")
            with self.scratch() as temp:
                data_path = temp / "data.csv"
                private_write(temp / "rows.sqlite", b"")
                index = sqlite3.connect(temp / "rows.sqlite")
                index.executescript("PRAGMA journal_mode=OFF; CREATE TABLE rows(ordinal INTEGER PRIMARY KEY,k TEXT UNIQUE NOT NULL,cells TEXT NOT NULL,values_json TEXT NOT NULL);")
                names = [c["name"] for c in plan["columns"]]
                key_indexes = [names.index(k) for k in plan["keys"]]
                stats = [{"column": name, "emptyCells": 0, "nullValues": 0} for name in names]
                try:
                    with os.fdopen(os.open(data_path, os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o600), "w", encoding="utf-8", newline="") as output:
                        writer = csv.writer(output, lineterminator="\n")
                        writer.writerow(names)
                        def record(ordinal, cells, values):
                            writer.writerow(cells)
                            if output.tell() > plan["maxBytes"]:
                                raise InputError("Projected CSV exceeds maxBytes")
                            key = [values[i] for i in key_indexes] if key_indexes else [ordinal]
                            if key_indexes and any(value is None or value == "" for value in key):
                                raise InputError(f"Record {ordinal}: edition key is empty")
                            try:
                                index.execute("INSERT INTO rows VALUES(?,?,?,?)", (ordinal,
                                    json_bytes(key).decode(), json_bytes(cells).decode(), json_bytes(values).decode()))
                            except sqlite3.IntegrityError as e:
                                raise InputError(f"Record {ordinal}: duplicate edition key; select a unique key or remove edition comparison") from e
                            for i, value in enumerate(values):
                                stats[i]["emptyCells"] += cells[i] == ""
                                stats[i]["nullValues"] += value is None
                        with source_path.open("rb") as stream:
                            count = self.format.extract(stream, plan, record)
                        output.flush()
                        os.fsync(output.fileno())
                    if count == 0 and not plan["allowEmpty"]:
                        raise InputError("Record selector matched zero records; review the source mapping or explicitly allow an empty edition")
                    index.commit()
                finally:
                    index.close()
                private_write(temp / "dataset.json", (json.dumps(self.format.dataset_spec(plan), ensure_ascii=False, separators=(",", ":"), allow_nan=False) + "\n").encode())
                native = self.native.query(temp / "dataset.json", {"limit": "1"})
                if native["response"]["status"] != 200 or native["dataset"]["rowCount"] != count:
                    raise InputError("Original SF30 engine did not accept the complete projection")
                files = {name: {"bytes": (temp / name).stat().st_size,
                                "sha256": file_digest(temp / name, 4 * MAX_SOURCE)}
                         for name in ["data.csv", "dataset.json", "rows.sqlite"]}
                result = {"schema": self.build_schema, "id": ident, "source": source_id, "plan": plan_id,
                          "rowCount": count, "keys": plan["keys"], "columns": stats,
                          "native": native["dataset"], "engineBlob": native["engineBlob"], "files": files}
                self._expected(result, expected)
                private_write(temp / "review.json", json_bytes(result))
                # A directory left by a crash is recovered only when every byte matches.
                destination = self.root / "builds" / ident
                if destination.exists():
                    if destination.is_symlink() or any(not (destination / n).is_file() or
                            file_digest(destination / n, 4 * MAX_SOURCE) != file_digest(temp / n, 4 * MAX_SOURCE)
                            for n in ["data.csv", "dataset.json", "rows.sqlite", "review.json"]):
                        raise InputError("An unfinished build conflicts with this deterministic build; preserve it for inspection")
                else:
                    os.replace(temp, destination)
                    sync_dir(destination.parent)
                with self.db:
                    self.db.execute("INSERT INTO builds VALUES(?,?,?,?,?)", (ident, source_id, plan_id, json_bytes(result).decode(), time.time()))
                return result

    @staticmethod
    def _expected(result, expected):
        if expected is not None and (result["files"]["data.csv"]["sha256"] != expected["files"]["data.csv"]["sha256"] or
                                    result["files"]["dataset.json"]["sha256"] != expected["files"]["dataset.json"]["sha256"] or
                                    result["native"]["snapshot"] != expected["native"]["snapshot"]):
            raise InputError("Packet reconstruction differs from the exported native dataset")

    def query(self, build_id: str, params: dict) -> dict:
        if not isinstance(params, dict) or any(not isinstance(k, str) or not isinstance(v, str) for k, v in params.items()):
            raise InputError("Native query parameters must be scalar strings")
        with self.mutex:
            # Byte checks happen before loading a new immutable native selection.
            config = self._build_path(build_id, "dataset.json")
            self._build_path(build_id, "data.csv")
            return self.native.query(config, params)

    @contextmanager
    def _comparison_connection(self, before_id: str, after_id: str):
        before, after = self.build_view(before_id), self.build_view(after_id)
        if before["plan"] != after["plan"] or not after["keys"]:
            raise InputError("Edition comparison requires the same mapping with explicit unique keys; build both editions with that mapping")
        before_path = self._build_path(before_id, "rows.sqlite")
        after_path = self._build_path(after_id, "rows.sqlite")
        db = sqlite3.connect(after_path.as_uri() + "?mode=ro", uri=True)
        db.row_factory = sqlite3.Row
        try:
            db.execute("ATTACH DATABASE ? AS old", (before_path.as_uri() + "?mode=ro",))
            db.execute("BEGIN")
            yield db, before, after
        finally:
            db.close()

    def compare(self, before_id: str, after_id: str) -> dict:
        with self.mutex:
            ident = digest(json_bytes({"schema": self.comparison_schema, "before": before_id, "after": after_id}))
            existing = self.db.execute("SELECT summary FROM comparisons WHERE id=?", (ident,)).fetchone()
            if existing:
                return load_json(existing["summary"])
            with self._comparison_connection(before_id, after_id) as (db, before, after), self.scratch() as temp:
                counts = {"added": 0, "removed": 0, "changed": 0, "unchanged": 0}
                plan = self.plan(after["plan"])
                names = [c["name"] for c in plan["columns"]]
                sql = """SELECT a.k,a.cells AS after_cells,b.cells AS before_cells,a.ordinal AS after_row,b.ordinal AS before_row
                    FROM main.rows a LEFT JOIN old.rows b ON b.k=a.k
                    UNION ALL SELECT b.k,NULL,b.cells,NULL,b.ordinal FROM old.rows b
                    LEFT JOIN main.rows a ON a.k=b.k WHERE a.k IS NULL ORDER BY 1"""
                with os.fdopen(os.open(temp / "changes.jsonl", os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o600), "wb") as out:
                    for row in db.execute(sql):
                        if row["before_cells"] == row["after_cells"]:
                            counts["unchanged"] += 1
                            continue
                        kind = "added" if row["before_cells"] is None else "removed" if row["after_cells"] is None else "changed"
                        counts[kind] += 1
                        left = load_json(row["before_cells"]) if row["before_cells"] is not None else None
                        right = load_json(row["after_cells"]) if row["after_cells"] is not None else None
                        out.write(json_bytes({"kind": kind, "key": load_json(row["k"]),
                            "beforeRow": row["before_row"], "afterRow": row["after_row"],
                            "before": dict(zip(names, left)) if left is not None else None,
                            "after": dict(zip(names, right)) if right is not None else None,
                            "fields": [name for i, name in enumerate(names) if left is None or right is None or left[i] != right[i]]}))
                    out.flush()
                    os.fsync(out.fileno())
                summary = {"schema": self.comparison_schema, "id": ident,
                    "before": before_id, "after": after_id, "plan": after["plan"], "keys": after["keys"],
                    "semantics": "exact projected CSV cells; record order changes are not field changes",
                    "counts": counts, "changesSha256": file_digest(temp / "changes.jsonl", 4 * MAX_SOURCE)}
                private_write(temp / "summary.json", json_bytes(summary))
                destination = self.root / "comparisons" / ident
                if destination.exists():
                    if destination.is_symlink() or (destination / "summary.json").read_bytes() != json_bytes(summary) or file_digest(destination / "changes.jsonl", 4 * MAX_SOURCE) != summary["changesSha256"]:
                        raise InputError("Retained comparison conflicts with this source pair")
                else:
                    os.replace(temp, destination)
                    sync_dir(destination.parent)
                with self.db:
                    self.db.execute("INSERT INTO comparisons VALUES(?,?,?,?,?)", (ident, before_id, after_id, json_bytes(summary).decode(), time.time()))
                return summary

    def comparison_file(self, ident: str) -> Path:
        checked_id(ident)
        with self.mutex:
            row = self.db.execute("SELECT summary FROM comparisons WHERE id=?", (ident,)).fetchone()
            if row is None:
                raise InputError("Unknown completed comparison")
            summary = load_json(row[0])
            path = self.root / "comparisons" / ident / "changes.jsonl"
            if file_digest(path, 4 * MAX_SOURCE) != summary["changesSha256"]:
                raise InputError("Retained comparison bytes changed")
            return path

    def comparison_page(self, ident: str, offset: int = 0, limit: int = 50) -> dict:
        if type(offset) is not int or offset < 0 or type(limit) is not int or not 1 <= limit <= 250:
            raise InputError("Invalid comparison page")
        rows, size, more = [], 0, False
        with self.comparison_file(ident).open("rb") as stream:
            for i, line in enumerate(stream):
                if i < offset:
                    continue
                if len(line) > 2 * 1024 * 1024 and not rows:
                    raise InputError("This change exceeds the interactive page size; download the complete changes file")
                if len(rows) == limit or size + len(line) > 2 * 1024 * 1024:
                    more = True
                    break
                rows.append(load_json(line))
                size += len(line)
        return {"rows": rows, "offset": offset, "nextOffset": offset + len(rows) if more else None}

    def export_dataset(self, build_id: str, destination: str | Path) -> dict:
        with self.mutex:
            view = self.build_view(build_id)
            destination = Path(destination).expanduser().absolute()
            destination.mkdir(mode=0o700, parents=False, exist_ok=False)
            try:
                for name in ["data.csv", "dataset.json"]:
                    source = self._build_path(build_id, name)
                    with source.open("rb") as inp, os.fdopen(os.open(destination / name, os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o600), "wb") as out:
                        shutil.copyfileobj(inp, out, 1048576)
                        out.flush(); os.fsync(out.fileno())
                private_write(destination / self.lineage_name, json_bytes(view))
                sync_dir(destination)
            except Exception:
                shutil.rmtree(destination)
                raise
            return {"directory": str(destination), "dataset": str(destination / "dataset.json"), "build": view}

    def export_packet(self, build_id: str, output: Path):
        with self.mutex:
            view = self.build_view(build_id)
            sources = {self.source_name: self.root / "sources" / (view["source"] + "." + self.kind),
                       "plan.json": self.root / "plans" / (view["plan"] + ".json"),
                       "data.csv": self._build_path(build_id, "data.csv"),
                       "dataset.json": self._build_path(build_id, "dataset.json"),
                       "review.json": self._build_path(build_id, "review.json")}
            entries = {name: {"bytes": regular(path).st_size, "sha256": file_digest(path)} for name, path in sources.items()}
            if entries[self.source_name]["sha256"] != view["source"] or entries["plan.json"]["sha256"] != view["plan"]:
                raise InputError("Retained source or mapping changed")
            manifest = {"schema": self.packet_schema, "build": build_id, "files": entries}
            with os.fdopen(os.open(output, os.O_RDWR | os.O_CREAT | os.O_EXCL, 0o600), "w+b") as out:
                try:
                    with zipfile.ZipFile(out, "w", compression=zipfile.ZIP_DEFLATED, compresslevel=6) as archive:
                        archive.writestr("manifest.json", json_bytes(manifest))
                        for name, path in sources.items():
                            archive.write(path, name)
                    out.flush(); os.fsync(out.fileno())
                except Exception:
                    output.unlink(missing_ok=True)
                    raise
            return {"file": str(output), "bytes": output.stat().st_size, "sha256": file_digest(output, 2 * MAX_SOURCE), "build": build_id}

    def import_packet(self, path: Path) -> dict:
        limits = {"manifest.json": 16384, self.source_name: MAX_SOURCE, "plan.json": 65536,
                  "data.csv": MAX_SOURCE, "dataset.json": 65536, "review.json": 131072}
        with self.mutex, self.scratch() as temp:
            with zipfile.ZipFile(path) as archive:
                infos = archive.infolist()
                if len(infos) != len(limits) or {i.filename for i in infos} != set(limits):
                    raise InputError("Packet must contain exactly the six documented root files")
                for info in infos:
                    mode = info.external_attr >> 16
                    if info.flag_bits & 1 or info.compress_type not in {zipfile.ZIP_STORED, zipfile.ZIP_DEFLATED} or stat.S_ISLNK(mode) or info.is_dir() or info.file_size > limits[info.filename]:
                        raise InputError("Invalid packet member, compression, or size")
                    with archive.open(info) as inp, os.fdopen(os.open(temp / info.filename, os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o600), "wb") as out:
                        size = 0
                        while block := inp.read(65536):
                            size += len(block)
                            if size > limits[info.filename]:
                                raise InputError("Packet member exceeds its size limit")
                            out.write(block)
                manifest = load_json((temp / "manifest.json").read_bytes())
                if not isinstance(manifest, dict) or manifest.get("schema") != self.packet_schema or not isinstance(manifest.get("files"), dict) or set(manifest["files"]) != set(limits) - {"manifest.json"}:
                    raise InputError("Invalid packet manifest")
                for name, entry in manifest["files"].items():
                    if not isinstance(entry, dict) or entry != {"bytes": (temp / name).stat().st_size, "sha256": file_digest(temp / name)}:
                        raise InputError(f"Packet member failed its declared identity: {name}")
                expected = load_json((temp / "review.json").read_bytes())
                mapped_body = self.format.validate_plan(load_json((temp / "plan.json").read_bytes()))
                source_id = manifest["files"][self.source_name]["sha256"]
                plan_id = digest(json_bytes(mapped_body))
                expected_id = digest(json_bytes({"schema": self.build_schema, "source": source_id, "plan": plan_id}))
                if (not isinstance(expected, dict) or expected.get("schema") != self.build_schema or
                    expected.get("source") != source_id or expected.get("plan") != plan_id or
                    expected.get("id") != expected_id or manifest.get("build") != expected_id or
                    not isinstance(expected.get("native"), dict) or not HEX.fullmatch(str(expected["native"].get("snapshot", ""))) or
                    not isinstance(expected.get("files"), dict) or
                    any(expected["files"].get(n) != manifest["files"][n] for n in ["data.csv", "dataset.json"])):
                    raise InputError("Packet source, mapping, dataset and review are not one consistent build")
                with (temp / self.source_name).open("rb") as source:
                    retained = self.add_source(source, f"Imported {self.label} edition", self.source_name)
                mapped = self.save_plan(load_json((temp / "plan.json").read_bytes()))
                if not isinstance(expected, dict) or expected.get("schema") != self.build_schema or expected.get("source") != retained["id"] or expected.get("plan") != mapped["id"] or expected.get("id") != manifest.get("build"):
                    raise InputError("Packet source, mapping and native review are not the same build")
                result = self.build(retained["id"], mapped["id"], expected=expected)
                if result["id"] != manifest["build"]:
                    raise InputError("Packet generator identity differs from this implementation")
                return {"source": retained["id"], "plan": mapped["id"], "build": result, "reconstructed": True}

"""MIT. Streaming XML inventory and explicit projection into the original SF30 CSV ABI.

Selectors are arrays of exact expanded names, not XPath expressions. Input bytes
are fed to Expat unchanged; no DTD, external entity, XInclude or network loader is
installed. Only one selected record tree is retained while projecting a source.
"""
from __future__ import annotations

from dataclasses import dataclass, field
import json
import math
from pathlib import Path
import re
from typing import BinaryIO, Callable, Any
from xml.parsers import expat

MAX_SOURCE = 256 * 1024 * 1024
MAX_RECORD = 16 * 1024 * 1024
MAX_DEPTH = 128
MAX_PATHS = 4096
NAME = re.compile(r"[A-Za-z][A-Za-z0-9_]{0,47}\Z")
INT = re.compile(r"-?(0|[1-9][0-9]*)\Z")
NUMBER = re.compile(r"-?(0|[1-9][0-9]*)(\.[0-9]+)?([eE][+-]?[0-9]+)?\Z")
NIL = "{http://www.w3.org/2001/XMLSchema-instance}nil"
SCHEMA = "stellar-forge.xml-mapping.v1"


class InputError(ValueError):
    """An actionable source or mapping error, suitable for the private operator."""


def utf16_length(value: str) -> int:
    return len(value.encode("utf-16-le")) // 2


def expanded(name: str) -> str:
    if "\x1f" not in name:
        return name
    uri, local = name.split("\x1f", 1)
    return "{" + uri + "}" + local


def parser():
    if expat.version_info < (2, 6, 0):
        raise InputError("Expat 2.6+ is required for XML large-token protections; use an updated Python runtime")
    p = expat.ParserCreate(namespace_separator="\x1f")
    p.buffer_text = True
    p.SetParamEntityParsing(expat.XML_PARAM_ENTITY_PARSING_NEVER)

    def reject(*_):
        raise InputError("DTD and entity declarations are not accepted; export a self-contained XML document")

    p.StartDoctypeDeclHandler = reject
    p.EntityDeclHandler = reject
    p.ExternalEntityRefHandler = reject
    p.SkippedEntityHandler = reject
    return p


def parse_stream(p, stream: BinaryIO, cancel: Callable[[], bool] | None = None) -> int:
    size = 0
    try:
        while chunk := stream.read(65536):
            if cancel and cancel():
                raise InputError("Operation cancelled")
            size += len(chunk)
            if size > MAX_SOURCE:
                raise InputError("XML source exceeds 256 MiB")
            p.Parse(chunk, False)
        p.Parse(b"", True)
    except expat.ExpatError as e:
        raise InputError(f"XML at line {e.lineno}, column {e.offset}: {expat.ErrorString(e.code)}") from e
    return size


def inventory(stream: BinaryIO, cancel: Callable[[], bool] | None = None) -> dict:
    """Full-document shape inventory; samples are short, private parsed-text hints."""
    p = parser()
    stack: list[dict] = []
    paths: dict[tuple, dict] = {}
    namespaces: set[tuple[str, str]] = set()
    declaration = {}
    metadata_bytes = 0

    def charge(value):
        nonlocal metadata_bytes
        metadata_bytes += len(json.dumps(value, ensure_ascii=False).encode()) + 96
        if metadata_bytes > 8 * 1024 * 1024:
            raise InputError("XML shape inventory exceeds 8 MiB; select a smaller source document")

    def start(raw, attrs):
        name = expanded(raw)
        if len(stack) >= MAX_DEPTH or len(name) > 2048 or len(attrs) > 256:
            raise InputError("XML exceeds the supported depth, name or attribute limits")
        if stack:
            stack[-1]["child"] = True
        path = tuple([s["name"] for s in stack] + [name])
        if path not in paths:
            if len(paths) >= MAX_PATHS:
                raise InputError("XML has more than 4096 distinct element paths")
            charge(list(path))
            paths[path] = {"path": list(path), "count": 0, "leafCount": 0,
                           "mixedCount": 0, "attributes": {}, "samples": []}
        row = paths[path]
        row["count"] += 1
        for key, value in attrs.items():
            key = expanded(key)
            if len(key) > 2048 or utf16_length(value) > 1048576:
                raise InputError("XML attribute exceeds supported length")
            if key not in row["attributes"]:
                charge(key)
            a = row["attributes"].setdefault(key, {"count": 0, "samples": []})
            a["count"] += 1
            sample = value[:160]
            if len(a["samples"]) < 3 and sample not in a["samples"]:
                charge(sample)
                a["samples"].append(sample)
        stack.append({"name": name, "row": row, "child": False, "nonspace": False, "sample": ""})

    def text(value):
        if stack:
            frame = stack[-1]
            frame["nonspace"] = frame["nonspace"] or bool(value.strip())
            frame["sample"] += value[:max(0, 160 - len(frame["sample"]))]

    def end(_):
        frame = stack.pop()
        row = frame["row"]
        if not frame["child"]:
            row["leafCount"] += 1
            if len(row["samples"]) < 3 and frame["sample"] not in row["samples"]:
                charge(frame["sample"])
                row["samples"].append(frame["sample"])
        elif frame["nonspace"]:
            row["mixedCount"] += 1

    def ns(prefix, uri):
        if len(namespaces) >= MAX_PATHS:
            raise InputError("XML has too many distinct namespace bindings")
        binding = (prefix or "", uri or "")
        if binding not in namespaces:
            charge(binding)
        namespaces.add(binding)

    p.StartElementHandler, p.EndElementHandler, p.CharacterDataHandler = start, end, text
    p.StartNamespaceDeclHandler = ns
    p.XmlDeclHandler = lambda version, encoding, standalone: declaration.update(
        version=version, encoding=encoding, standalone=standalone)
    size = parse_stream(p, stream, cancel)
    return {"schema": "stellar-forge.xml-inventory.v1", "bytes": size,
            "declaration": declaration,
            "namespaces": [{"prefix": a, "uri": b} for a, b in sorted(namespaces)],
            "paths": list(paths.values())}


def exact_keys(value: Any, allowed: set[str], label: str) -> dict:
    if not isinstance(value, dict) or set(value) - allowed:
        raise InputError(f"Invalid {label} fields")
    return value


def path_array(value: Any, label: str, empty: bool = True) -> list[str]:
    if not isinstance(value, list) or (not value and not empty) or len(value) > MAX_DEPTH:
        raise InputError(f"{label} must be an array of exact expanded XML names")
    if any(not isinstance(v, str) or not v or len(v) > 2048 or "\x00" in v for v in value):
        raise InputError(f"{label} contains an invalid XML name")
    return list(value)


def integer(value: Any, low: int, high: int, label: str) -> int:
    if type(value) is not int or not low <= value <= high:
        raise InputError(f"{label} must be an integer from {low} to {high}")
    return value


def validate_plan(raw: dict) -> dict:
    exact_keys(raw, {"schema", "name", "recordPath", "columns", "filters", "ranges", "sorts", "keys",
                     "defaultLimit", "maxLimit", "maxBytes", "maxRows", "maxCellChars", "allowEmpty"}, "mapping")
    if raw.get("schema") != SCHEMA:
        raise InputError(f"Mapping schema must be {SCHEMA}")
    name = raw.get("name")
    if not isinstance(name, str) or not name.strip() or utf16_length(name) > 128 or re.search(r"[\x00-\x1f\x7f]", name):
        raise InputError("Dataset name must be printable text, 1–128 UTF-16 code units")
    columns = raw.get("columns")
    if not isinstance(columns, list) or not 1 <= len(columns) <= 64:
        raise InputError("Choose 1–64 columns")
    result = {"schema": SCHEMA, "name": name,
              "recordPath": path_array(raw.get("recordPath"), "recordPath", False), "columns": []}
    result["allowEmpty"] = raw.get("allowEmpty", False)
    if type(result["allowEmpty"]) is not bool:
        raise InputError("allowEmpty must be an explicit boolean")
    names: set[str] = set()
    for original in columns:
        exact_keys(original, {"name", "path", "attribute", "type", "nullable", "mode", "separator",
                              "missing", "default", "trim", "text", "nil"}, "column")
        key = original.get("name")
        if not isinstance(key, str) or not NAME.fullmatch(key) or key in names or key in {"constructor", "prototype", "__proto__"}:
            raise InputError("Column names must be unique SF30 identifiers")
        names.add(key)
        c = {"name": key, "path": path_array(original.get("path", []), f"{key}.path"),
             "type": original.get("type", "string"), "nullable": original.get("nullable", False),
             "mode": original.get("mode", "single"), "missing": original.get("missing", "error"),
             "trim": original.get("trim", False), "text": original.get("text", "leaf"),
             "nil": original.get("nil", "literal")}
        if c["type"] not in ("string", "integer", "number", "boolean") or type(c["nullable"]) is not bool or type(c["trim"]) is not bool:
            raise InputError(f"{key}: choose an explicit SF30 type, nullable and trim policy")
        if c["mode"] not in ("single", "first", "last", "join", "json") or c["missing"] not in ("error", "empty", "default"):
            raise InputError(f"{key}: invalid multiplicity or missing-value policy")
        if c["text"] not in ("leaf", "direct", "descendant") or c["nil"] not in ("literal", "xsi"):
            raise InputError(f"{key}: invalid text or xsi:nil policy")
        if c["mode"] in {"join", "json"} and c["type"] != "string":
            raise InputError(f"{key}: join and JSON-array columns must have string type")
        if "attribute" in original and original["attribute"] is not None:
            a = original["attribute"]
            path_array([a], f"{key}.attribute")
            c["attribute"] = a
        if c["mode"] == "join":
            separator = original.get("separator")
            if not isinstance(separator, str) or len(separator) > 128:
                raise InputError(f"{key}: join requires an explicit separator of at most 128 characters")
            c["separator"] = separator
        if c["missing"] == "default":
            default = original.get("default")
            if not isinstance(default, str) or utf16_length(default) > 1048576:
                raise InputError(f"{key}: default must be an explicit cell string")
            c["default"] = default
        result["columns"].append(c)
    for label in ["filters", "ranges", "sorts", "keys"]:
        values = raw.get(label, [])
        if not isinstance(values, list) or any(not isinstance(x, str) for x in values) or len(values) > 8 or len(set(values)) != len(values) or any(x not in names for x in values):
            raise InputError(f"{label}: choose up to eight unique exposed columns")
        result[label] = sorted(values)  # Capabilities and the named key set are order-independent.
    by_name = {c["name"]: c for c in result["columns"]}
    if any(by_name[n]["type"] == "boolean" for n in result["ranges"]):
        raise InputError("Boolean columns cannot use range filters")
    if any(by_name[n]["type"] == "number" or by_name[n]["nullable"] for n in result["keys"]):
        raise InputError("Edition keys must be nonnullable string, integer or boolean columns; keep exact IDs as strings")
    if 3 + len(result["filters"]) + 4 * len(result["ranges"]) + bool(result["sorts"]) > 32:
        raise InputError("Selected capabilities exceed SF30's 32-query-parameter budget")
    result["maxLimit"] = integer(raw.get("maxLimit", 250), 1, 1000, "maxLimit")
    result["defaultLimit"] = integer(raw.get("defaultLimit", 50), 1, result["maxLimit"], "defaultLimit")
    result["maxBytes"] = integer(raw.get("maxBytes", 64 * 1024 * 1024), 1, MAX_SOURCE, "maxBytes")
    result["maxRows"] = integer(raw.get("maxRows", 250000), 1, 1000000, "maxRows")
    result["maxCellChars"] = integer(raw.get("maxCellChars", 65536), 1, 1048576, "maxCellChars")
    return result


def typed(value: str, column: dict, label: str):
    if value == "" and column["nullable"]:
        return None
    t = column["type"]
    if t == "string":
        return value
    if t == "boolean" and value in {"true", "false"}:
        return value == "true"
    if t == "integer" and INT.fullmatch(value) and len(value) <= 17:
        number = int(value)
        if abs(number) <= 9007199254740991:
            return number
    if t == "number" and NUMBER.fullmatch(value):
        number = float(value)
        if math.isfinite(number):
            return number
    raise InputError(f"{label}: requires {t}" + (" or an empty nullable cell" if column["nullable"] else ""))


@dataclass(slots=True)
class Node:
    name: str
    attrs: dict
    content: list = field(default_factory=list)
    children: list = field(default_factory=list)

    def text(self, policy: str) -> str:
        if policy == "leaf" and self.children:
            raise InputError("Selected element has child elements; choose direct or descendant text explicitly")
        return "".join(item if isinstance(item, str) else item.text("descendant")
                       for item in self.content if isinstance(item, str) or policy == "descendant")


def project(root: Node, column: dict, row: int, cell_limit: int) -> tuple[str, Any]:
    selected = [root]
    for name in column["path"]:
        selected = [child for node in selected for child in node.children if child.name == name]
    values = []
    for node in selected:
        if "attribute" in column:
            if column["attribute"] in node.attrs:
                values.append(node.attrs[column["attribute"]])
        elif column["nil"] == "xsi" and node.attrs.get(NIL) in {"true", "1"}:
            if node.children or node.text("direct").strip():
                raise InputError(f"Record {row}, {column['name']}: xsi:nil element contains content")
            values.append(None)
        else:
            values.append(node.text(column["text"]))
    if column["trim"]:
        values = [v.strip() if v is not None else None for v in values]
    label = f"Record {row}, {column['name']}"
    if not values:
        if column["missing"] == "error":
            raise InputError(f"{label}: selector is missing; choose an explicit missing-value policy")
        cell = column.get("default", "") if column["missing"] == "default" else ""
    elif column["mode"] == "json":
        cell = json.dumps(values, ensure_ascii=False, separators=(",", ":"))
    elif column["mode"] == "join":
        if any(v is None for v in values):
            raise InputError(f"{label}: join cannot preserve xsi:nil; choose JSON array")
        cell = column["separator"].join(values)
    else:
        if column["mode"] == "single" and len(values) != 1:
            raise InputError(f"{label}: selector matched {len(values)} values; choose a repeated-field policy")
        value = values[-1] if column["mode"] == "last" else values[0]
        if value is None and not column["nullable"]:
            raise InputError(f"{label}: xsi:nil requires nullable output")
        cell = "" if value is None else value
    if utf16_length(cell) > cell_limit:
        raise InputError(f"{label}: projected cell exceeds maxCellChars")
    return cell, typed(cell, column, label)


def extract(stream: BinaryIO, plan: dict, on_record: Callable[[int, list, list], None],
            cancel: Callable[[], bool] | None = None) -> int:
    """Project the complete document. Callback receives ordinal, CSV cells, typed values."""
    p = parser()
    stack: list[str] = []
    active: list[Node] = []
    count = size = nodes = 0

    def start(raw, attrs):
        nonlocal size, nodes
        name = expanded(raw)
        if len(stack) >= MAX_DEPTH or len(name) > 2048 or len(attrs) > 256:
            raise InputError("XML exceeds supported depth, name or attribute limits")
        stack.append(name)
        if active or stack == plan["recordPath"]:
            node = Node(name, {expanded(k): v for k, v in attrs.items()})
            size += len(name.encode()) + sum(len(k.encode()) + len(v.encode()) for k, v in node.attrs.items()) + 128
            nodes += 1
            if size > MAX_RECORD or nodes > 100000:
                raise InputError("Selected XML record exceeds 16 MiB working text or 100,000 nodes")
            if active:
                active[-1].children.append(node)
                active[-1].content.append(node)
            active.append(node)

    def text(value):
        nonlocal size
        if active:
            size += len(value.encode())
            if size > MAX_RECORD:
                raise InputError("Selected XML record exceeds 16 MiB working text")
            active[-1].content.append(value)

    def end(_):
        nonlocal count, size, nodes
        if active:
            node = active.pop()
            if not active:
                count += 1
                if count > plan["maxRows"]:
                    raise InputError("Selected records exceed maxRows")
                pairs = [project(node, c, count, plan["maxCellChars"]) for c in plan["columns"]]
                on_record(count, [v[0] for v in pairs], [v[1] for v in pairs])
                size = nodes = 0
        stack.pop()

    p.StartElementHandler, p.EndElementHandler, p.CharacterDataHandler = start, end, text
    parse_stream(p, stream, cancel)
    return count


def dataset_spec(plan: dict) -> dict:
    return {"schema": "stellar-forge.csv-dataset.v1", "file": "data.csv", "name": plan["name"],
            "columns": {c["name"]: {"type": c["type"], "nullable": c["nullable"]} for c in plan["columns"]},
            **{k: plan[k] for k in ["filters", "ranges", "sorts", "defaultLimit", "maxLimit", "maxBytes", "maxRows", "maxCellChars"]}}

