  const [type, ...parameters] = value.toLowerCase().split(';').map(part => part.trim());
  const charsets = parameters.filter(part => /^charset\s*=/.test(part));
  if (charsets.length > 1 || charsets.some(part =>
    !/^charset\s*=\s*(?:utf-8|utf8|"utf-8"|"utf8")$/.test(part))) return false;
  return format === 'sse' ? type === 'text/event-stream' : format === 'ndjson' &&
    ['application/x-ndjson', 'application/ndjson'].includes(type);
}

/**
 * Byte-preserving framing. Every returned record belongs to bytes already
 * supplied to push(). SSE follows the standard CR/LF, comment, data, event, id
 * and retry rules; EOF never dispatches an unfinished event. NDJSON requires
 * a newline after each JSON value and ignores empty/whitespace-only lines.
 * UTF-8 is fatal; limits apply to the complete wire record, including framing.
 */
export function createResponseStreamParser(options) {
  const config = normalizeResponseStream(options);
  const { format, maxRecordBytes, maxRecords } = config;
  const decoder = new TextDecoder('utf-8', { fatal: true, ignoreBOM: true });
  let lineBuffer = Buffer.allocUnsafe(Math.min(4096, maxRecordBytes));
  let lineBytes = 0, recordBytes = 0, lastRecordBytes = 0, totalBytes = 0;
  let records = 0, emptyLines = 0, complete = false, ended = false, failed = null;
  let firstLine = true, skipLF = false, lastCompleteByte = 0;
  let data = [], dataPresent = false, event = '', lastEventId = '', retryMilliseconds = null;
  const pending = () => lineBytes > 0 || (format === 'sse' && dataPresent);
  const summary = () => Object.freeze({ format, records, bytes: totalBytes,
    complete, pendingRecord: pending(), lastCompleteByte,
    ...(format === 'sse' ? { lastEventId, retryMilliseconds } : { emptyLines }),
    ...(failed ? { error: failed } : {}) });
  function error(code) {
    failed = code;
    const result = new BuyerResponseStreamError(code);
    result.stream = summary();
    throw result;
  }
  function append(piece) {
    if (piece.length === 0) return;
    if (piece.length > maxRecordBytes - recordBytes) error('RESPONSE_STREAM_RECORD_TOO_LARGE');
    const size = lineBytes + piece.length;
    if (size > lineBuffer.length) {
      const next = Buffer.allocUnsafe(Math.min(maxRecordBytes, Math.max(size, lineBuffer.length * 2)));
      lineBuffer.copy(next, 0, 0, lineBytes); lineBuffer = next;
    }
    lineBuffer.set(piece, lineBytes); lineBytes = size; recordBytes += piece.length;
  }
  function record(value, output) {
    if (records >= maxRecords) error('RESPONSE_STREAM_TOO_MANY_RECORDS');
    records++;
    output.push(Object.freeze({ index: records - 1, ...value }));
  }
  function line(output) {
    let text;
    try { text = decoder.decode(lineBuffer.subarray(0, lineBytes)); }
    catch { error('RESPONSE_STREAM_UTF8_INVALID'); }
    lineBytes = 0;
    if (firstLine) { firstLine = false; if (text.startsWith('\ufeff')) text = text.slice(1); }
    if (format === 'ndjson') {
      if (text.endsWith('\r')) text = text.slice(0, -1);
      if (text.includes('\r')) error('RESPONSE_STREAM_JSON_INVALID');
      if (text.trim().length === 0) emptyLines++;
      else {
        let value;
        try { value = JSON.parse(text); } catch { error('RESPONSE_STREAM_JSON_INVALID'); }
        record({ format, value }, output);
      }
      recordBytes = 0; lastCompleteByte = totalBytes;
      return;
    }
    if (text === '') {
      if (dataPresent) record({ format, event: event || 'message', data: data.join('\n'),
        id: lastEventId, ...(retryMilliseconds === null ? {} : { retry: retryMilliseconds }) }, output);
      else emptyLines++;
      data = []; dataPresent = false; event = ''; lastRecordBytes = recordBytes;
      recordBytes = 0; lastCompleteByte = totalBytes;
      return;
    }
    if (text.startsWith(':')) return;
    const colon = text.indexOf(':');
    const field = colon === -1 ? text : text.slice(0, colon);
    let value = colon === -1 ? '' : text.slice(colon + 1);
    if (value.startsWith(' ')) value = value.slice(1);
    if (field === 'data') { data.push(value); dataPresent = true; }
    else if (field === 'event') event = value;
    else if (field === 'id' && !value.includes('\0')) lastEventId = value;
    else if (field === 'retry' && /^[0-9]+$/.test(value) && Number.isSafeInteger(Number(value)))
      retryMilliseconds = Number(value);
  }
  function push(value) {
    need(!ended && failed === null, 'RESPONSE_STREAM_PARSER_CLOSED');
    need(value instanceof Uint8Array, 'RESPONSE_STREAM_BAD_CHUNK');
    const bytes = Buffer.from(value.buffer, value.byteOffset, value.byteLength), output = [];
    let start = 0;
    for (let i = 0; i < bytes.length; i++) {
      const byte = bytes[i];
      if (skipLF) {
        skipLF = false;
        if (byte === 10) { totalBytes++; start = i + 1;
          if (recordBytes === 0) {
            if (++lastRecordBytes > maxRecordBytes) error('RESPONSE_STREAM_RECORD_TOO_LARGE');
            lastCompleteByte = totalBytes;
          }
          else { if (++recordBytes > maxRecordBytes) error('RESPONSE_STREAM_RECORD_TOO_LARGE'); }
          continue;
        }
      }
      if (byte !== 10 && (format !== 'sse' || byte !== 13)) continue;
      append(bytes.subarray(start, i));
      totalBytes += i - start + 1;
      if (++recordBytes > maxRecordBytes) error('RESPONSE_STREAM_RECORD_TOO_LARGE');
      line(output);
      skipLF = format === 'sse' && byte === 13;
      start = i + 1;
    }
    append(bytes.subarray(start)); totalBytes += bytes.length - start;
    return output;
  }
  function finish() {
    need(!ended && failed === null, 'RESPONSE_STREAM_PARSER_CLOSED');
    ended = true;
    // Validate even the undispatched tail. Do not emit it as a completed record.
    if (lineBytes) {
      try { decoder.decode(lineBuffer.subarray(0, lineBytes)); }
      catch { error('RESPONSE_STREAM_UTF8_INVALID'); }
    }
    complete = !pending();
    return [];
  }
  return Object.freeze({ push, finish, summary, options: config });
}

/** Decode retained bytes or one live body with normal async-iterator backpressure. */
export async function* parseResponseStream(chunks, { signal, ...options }) {
  need(signal === undefined || signal instanceof AbortSignal, 'BAD_RESPONSE_STREAM_SIGNAL');
  const parser = createResponseStreamParser(options);
  for await (const chunk of chunks) {
    need(!signal?.aborted, 'RESPONSE_STREAM_ABORTED');
    yield* parser.push(chunk);
  }
  need(!signal?.aborted, 'RESPONSE_STREAM_ABORTED');
  yield* parser.finish();
  if (!parser.summary().complete) {
    const error = new BuyerResponseStreamError('RESPONSE_STREAM_INCOMPLETE_RECORD');
    error.stream = parser.summary();
    throw error;
  }
}

/** Safe, side-effect-free error interpretation for Stellar Forge's x402 v2 adapters.
 * Does not sign, broadcast, retry a paid request, or query a ledger.
 */
export const VERSION = 'stellar-forge.failure.v1';
export const STAGES = Object.freeze(['verify', 'settle', 'discovery', 'mcp', 'wallet']);
export const ACTIONS = Object.freeze({
  STOP: 'stop', REQUOTE_AND_REAUTHORIZE: 'requote_and_reauthorize',
  REAUTHORIZE: 'reauthorize', CHECK_ACCOUNT: 'check_account',
  CHANGE_ROUTE: 'change_route', RETRY_READ: 'retry_read',
  RECONCILE_SETTLEMENT: 'reconcile_settlement', REQUEST_APPROVAL: 'request_approval',
});

// Canonical x402 v2 codes plus local orchestration errors. Map prevents inherited
// property names (e.g. constructor, __proto__) being mistaken for known errors.
const ENTRIES = new Map([
  ['insufficient_funds', ['check_account', 'Wallet balance insufficient']],
  ['invalid_exact_evm_payload_authorization_valid_after', ['reauthorize', 'Authorization is not yet valid']],
  ['invalid_exact_evm_payload_authorization_valid_before', ['reauthorize', 'Authorization expired']],
  ['invalid_exact_evm_payload_authorization_value_mismatch', ['requote_and_reauthorize', 'Payment amount differs from terms']],
  ['invalid_exact_evm_payload_signature', ['reauthorize', 'Authorization signature invalid']],
  ['invalid_exact_evm_payload_recipient_mismatch', ['requote_and_reauthorize', 'Payment recipient differs from terms']],
  ['invalid_network', ['change_route', 'Unsupported network']],
  ['invalid_payload', ['stop', 'Invalid payment payload']],
  ['invalid_payment_requirements', ['stop', 'Invalid payment requirements']],
  ['invalid_scheme', ['change_route', 'Invalid payment scheme']],
  ['unsupported_scheme', ['change_route', 'Unsupported payment scheme']],
  ['invalid_x402_version', ['stop', 'Unsupported protocol version']],
  ['invalid_transaction_state', ['stop', 'Ledger transaction failed']],
  ['unexpected_verify_error', ['stop', 'Unexpected verification error']],
  ['unexpected_settle_error', ['reconcile_settlement', 'Settlement result uncertain']],
  ['settlement_pending', ['reconcile_settlement', 'Settlement confirmation pending']],
  ['discovery_not_found', ['stop', 'Resource is not indexed']],
  ['discovery_stale_terms', ['requote_and_reauthorize', 'Resource terms changed']],
  ['seller_identity_unverified', ['request_approval', 'Seller identity not verified']],
  ['wallet_trustline_missing', ['check_account', 'Wallet trustline missing']],
  ['budget_exceeded', ['request_approval', 'Buyer policy budget exceeded']],
  ['rpc_unavailable', ['retry_read', 'Read-only RPC unavailable']],
  ['rate_limited', ['retry_read', 'Read-only request rate limited']],
  ['timeout', ['retry_read', 'Read-only request timed out']],
  ['mcp_tool_missing', ['stop', 'MCP tool not found']],
]);
const TOKEN = /^[a-zA-Z0-9_.:-]{1,128}$/;
const clean = v => typeof v === 'string' && TOKEN.test(v) ? v : null;
const uncertainCodes = new Set(['settlement_pending', 'unexpected_settle_error', 'timeout', 'rpc_unavailable']);

/** Takes canonical verify/settle response shapes without modifying them. */
export function explainFailure({stage, reason, response = null, traceId, retryAfterMs} = {}) {
  if (!STAGES.includes(stage)) throw new TypeError('Invalid failure stage');
  if (response !== null && (typeof response !== 'object' || Array.isArray(response))) {
    throw new TypeError('response must be an object');
  }
  if (stage === 'verify' && response?.isValid === true) throw new TypeError('verify result is successful');
  if (stage === 'settle' && response?.success === true) throw new TypeError('settlement result is successful');
  const raw = stage === 'verify' ? response?.invalidReason ?? reason :
    stage === 'settle' ? response?.errorReason ?? reason : reason;
  const code = clean(raw) ?? 'unknown_upstream_error';
  const [action, text] = ENTRIES.get(code) ?? ['stop', 'Unrecognized upstream error'];
  const transaction = clean(response?.transaction);
  const network = clean(response?.network);
  const malformedPending = code === 'settlement_pending' && (!transaction || !network);
  const mayHaveSubmitted = stage === 'settle';
  const reconcile = mayHaveSubmitted && uncertainCodes.has(code);
  const recoveryAction = reconcile ? ACTIONS.RECONCILE_SETTLEMENT : action;
  const safeToAutoRetry = (stage === 'verify' || stage === 'discovery') && recoveryAction === ACTIONS.RETRY_READ;
  const result = {
    version: VERSION,
    code: malformedPending ? 'invalid_settlement_pending_response' : code,
    reason: malformedPending ? 'Pending settlement lacks transaction or network' : text,
    stage, traceId: clean(traceId) ?? 'unspecified', recoveryAction, safeToAutoRetry,
    requiresNewPaymentAuthorization: recoveryAction === ACTIONS.REAUTHORIZE ||
      recoveryAction === ACTIONS.REQUOTE_AND_REAUTHORIZE,
    settlementMayBePending: reconcile,
    settlement: mayHaveSubmitted ? Object.freeze({transaction, network, confirmed: false}) : null,
  };
  if (safeToAutoRetry && Number.isSafeInteger(retryAfterMs) && retryAfterMs >= 0 && retryAfterMs <= 3600000) {
    result.retryAfterMs = retryAfterMs;
  }
  return Object.freeze(result);
}

/** Trust only an independently obtained canonical ledger receipt, never model text.
 * All results have maySubmitPayment=false: a separate operator must authorize any payment.
 */
// Do not infer a payment transfer from transaction inclusion alone.
const PAYMENT_ATOMIC = /^[1-9][0-9]{0,77}$/;
function matchingVerifiedTransfer(receipt, expectedPayment) {
  if (receipt?.transferVerified !== true || !Array.isArray(receipt.transfers) ||
      receipt.transfers.length !== 1 || !expectedPayment) return false;
  const transfer = receipt.transfers[0];
  if (!transfer || typeof transfer !== 'object' || Array.isArray(transfer)) return false;
  if (!['from','payTo','asset'].every(k => clean(expectedPayment[k]) !== null) ||
      typeof expectedPayment.amount !== 'string' ||
      !PAYMENT_ATOMIC.test(expectedPayment.amount)) return false;
  return transfer.from === expectedPayment.from &&
    transfer.to === expectedPayment.payTo && transfer.asset === expectedPayment.asset &&
    transfer.amount === expectedPayment.amount;
}

export function gateNextAction(failure, {ledgerReceipt, expectedPayment, explicitNewAuthorization = false} = {}) {
  if (!failure || failure.version !== VERSION) throw new TypeError('unrecognized failure envelope');
  if (failure.settlementMayBePending) {
    const transaction = failure.settlement?.transaction;
    const network = failure.settlement?.network;
    const settled = Boolean(transaction && network && ledgerReceipt?.confirmed === true &&
      ledgerReceipt?.success === true && ledgerReceipt.transaction === transaction && ledgerReceipt.network === network &&
      matchingVerifiedTransfer(ledgerReceipt, expectedPayment));
    return Object.freeze({decision: settled ? 'already_settled' : 'reconcile_before_any_new_payment',
      maySubmitPayment: false, requiresManualReview: !settled});
  }
  if (failure.requiresNewPaymentAuthorization) {
    return Object.freeze({decision: explicitNewAuthorization ? 'prepare_new_authorization' : 'await_user_authorization',
      maySubmitPayment: false, requiresManualReview: !explicitNewAuthorization});
  }
  if (failure.safeToAutoRetry) {
    return Object.freeze({decision: 'retry_read_only_operation', maySubmitPayment: false, requiresManualReview: false});
  }
  return Object.freeze({decision: 'stop_or_request_user_action', maySubmitPayment: false, requiresManualReview: true});
}

"""Accountant references on immutable issued buyer allocations, in the same Store."""
from __future__ import annotations
import base64
import hashlib
import json
from domain import Problem, canonical, digest, identifier, now, text
from native_accountant import return_bytes, inspect_return

ACCOUNTANT_TABLES = {"accountant_returns", "accountant_heads"}
ACCOUNTANT_DDL = """
CREATE TABLE IF NOT EXISTS accountant_returns(id TEXT PRIMARY KEY,close_id TEXT NOT NULL,handoff_id TEXT NOT NULL,created_at TEXT NOT NULL,body TEXT NOT NULL,packet_base64 TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS accountant_heads(handoff_id TEXT PRIMARY KEY,return_id TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS accountant_returns_close ON accountant_returns(close_id,created_at,id);
"""


class AccountantStore:
    def accountant_source(self, close_id):
        with self.lock:
            workspace_id = self.connection.execute("SELECT value FROM meta WHERE key='id'").fetchone()[0]
            value = {"schema": "stellar-forge.buyer-accountant-source.v1", "workspaceId": workspace_id,
                     "issued": self._get("closes", close_id)}
            return (canonical(value) + "\n").encode("utf-8")

    def _accountant_return(self, ident):
        row = self.connection.execute("SELECT body FROM accountant_returns WHERE id=?", (ident,)).fetchone()
        if row is None:
            raise Problem("ACCOUNTANT_RETURN_NOT_FOUND", "Choose a retained accountant return", 404)
        return json.loads(row[0])

    def accountant_returns(self, close_id, offset=0, limit=50):
        from store import page
        with self.lock:
            source = self.accountant_source(close_id)
            values = [json.loads(row[0]) for row in self.connection.execute(
                "SELECT body FROM accountant_returns WHERE close_id=? ORDER BY created_at DESC,id DESC", (close_id,))]
            heads = dict(self.connection.execute("SELECT handoff_id,return_id FROM accountant_heads"))
            summaries = [{k: value[k] for k in ("id", "close_id", "handoff_id", "created_at", "name", "operator",
                                               "packet_sha256", "selected_revision_id", "summary", "previous", "supersedes")}
                         | {"current": heads.get(value["handoff_id"]) == value["id"]} for value in values]
            return page(summaries, offset, limit) | {"close_id": close_id,
                "source_sha256": hashlib.sha256(source).hexdigest(), "revision": self.revision()}

    def accountant_delivery(self, close_id, expected_revision=None):
        from exports import accountant_packet
        with self.lock:
            if expected_revision is not None and (type(expected_revision) is not int or expected_revision != self.revision()):
                raise Problem("REVISION_CHANGED", "Review the current workspace revision before preparing its bookkeeping packet", 409)
            doc = self._get("closes", close_id)
            heads = set(row[0] for row in self.connection.execute("SELECT return_id FROM accountant_heads"))
            records = [json.loads(row[0]) for row in self.connection.execute(
                "SELECT body FROM accountant_returns WHERE close_id=? ORDER BY created_at,id", (close_id,))]
            values = [value | {"current": value["id"] in heads} for value in records]
            return accountant_packet(doc, {"source":self.accountant_source(close_id), "revision":self.revision(),
                "returns":values, "originals":{row["id"]:self.accountant_original(row["id"]) for row in records}})

    def accountant_return(self, ident):
        with self.lock:
            value = self._accountant_return(ident)
            head = self.connection.execute("SELECT return_id FROM accountant_heads WHERE handoff_id=?", (value["handoff_id"],)).fetchone()
            return value | {"current": bool(head and head[0] == ident)}

    def accountant_original(self, ident):
        with self.lock:
            row = self.connection.execute("SELECT packet_base64 FROM accountant_returns WHERE id=?", (ident,)).fetchone()
            if row is None:
                raise Problem("ACCOUNTANT_RETURN_NOT_FOUND", "Choose a retained accountant return", 404)
            return base64.b64decode(row[0], validate=True)

    def preview_accountant_return(self, close_id, payload):
        with self.lock:
            packet = return_bytes(payload)
            native = inspect_return(self.accountant_source(close_id), packet, self.node_executable)
            row = self.connection.execute("SELECT return_id FROM accountant_heads WHERE handoff_id=?", (native["handoffId"],)).fetchone()
            previous = self._accountant_return(row[0]) if row else None
            chain = {value["id"]: value for value in native["revisions"]}
            if previous:
                old = previous["native"]
                retained = chain.get(old["selectedRevisionId"])
                if retained is None or retained["sha256"] != old["selectedRevisionSha256"]:
                    raise Problem("ACCOUNTANT_RETURN_DIVERGED", "This file does not extend the accountant history already accepted for its original handoff", 409)
            heads = [json.loads(row[0]) for row in self.connection.execute(
                "SELECT r.body FROM accountant_returns r JOIN accountant_heads h ON h.return_id=r.id WHERE r.close_id=?", (close_id,))]
            same_rows = {row["sourceLineId"] for row in native["rows"]}
            overlap = [{"return_id": saved["id"], "handoff_id": saved["handoff_id"],
                        "source_line_ids": sorted(same_rows.intersection(row["sourceLineId"] for row in saved["native"]["rows"]))}
                       for saved in heads if saved["handoff_id"] != native["handoffId"]]
            overlap = [value for value in overlap if value["source_line_ids"]]
            basis = {"packet_sha256": native["packetSha256"], "source_sha256": native["source"]["sha256"],
                     "previous": previous["id"] if previous else None, "other_handoffs": overlap}
            return {"native": native, "previous": basis["previous"], "other_handoffs": overlap,
                    "duplicate": bool(previous and previous["packet_sha256"] == native["packetSha256"]),
                    "preview_sha256": digest(basis), "revision": self.revision()}

    def save_accountant_return(self, close_id, payload, expected):
        def operation():
            preview = self.preview_accountant_return(close_id, payload)
            if payload.get("preview_sha256") != preview["preview_sha256"]:
                raise Problem("ACCOUNTANT_PREVIEW_CHANGED", "Preview the exact returned file against the current accepted bookkeeping history", 409)
            if preview["duplicate"]:
                return self._accountant_return(preview["previous"]) | {"duplicate": True}
            operator = text(payload.get("operator"), "Bookkeeping operator", maximum=160)
            name = text(payload.get("name"), "Bookkeeping return name", maximum=160)
            supersedes = payload.get("supersedes", [])
            required = sorted(value["return_id"] for value in preview["other_handoffs"])
            if not isinstance(supersedes, list) or sorted(supersedes) != required:
                raise Problem("ACCOUNTANT_HANDOFF_CONFLICT", "Review and explicitly supersede every other accepted handoff for these same issued allocation lines", 409)
            reason = text(payload.get("reason", ""), "Bookkeeping review note", maximum=2000, optional=not bool(required))
            native = preview["native"]
            value = {"id": identifier("accountant-return"), "close_id": close_id, "handoff_id": native["handoffId"],
                     "created_at": now(), "name": name, "operator": operator, "reason": reason,
                     "packet_sha256": native["packetSha256"], "source_sha256": native["source"]["sha256"],
                     "selected_revision_id": native["selectedRevisionId"], "summary": native["summary"],
                     "previous": preview["previous"], "supersedes": supersedes, "native": native}
            self.connection.execute("INSERT INTO accountant_returns VALUES(?,?,?,?,?,?)",
                (value["id"], close_id, value["handoff_id"], value["created_at"], canonical(value), payload["content_base64"]))
            for prior in preview["other_handoffs"]:
                self.connection.execute("DELETE FROM accountant_heads WHERE handoff_id=? AND return_id=?",
                                        (prior["handoff_id"], prior["return_id"]))
            self.connection.execute("INSERT INTO accountant_heads VALUES(?,?) ON CONFLICT(handoff_id) DO UPDATE SET return_id=excluded.return_id",
                                    (native["handoffId"], value["id"]))
            return value
        return self._change(expected, "accountant.return", operation)

"""Original receipt intake and buyer credit decisions in the existing expense Store."""
import base64
import io
import json
import zipfile
from domain import Problem, canonical, digest, identifier, now, text, row_key
from native_woo import capture_refund
from native_adjustments import capture_adjustments as read_adjustments
from credits import data_context, coding_basis, purchase_matches, validate_credit_coding, credit_period

CREDIT_TABLES = {"refund_packets", "credits", "credit_codings", "credit_coding_heads"}
CREDIT_DDL = """
CREATE TABLE IF NOT EXISTS refund_packets(id TEXT PRIMARY KEY,manifest_sha256 TEXT NOT NULL UNIQUE,status TEXT NOT NULL,created_at TEXT NOT NULL,body TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS credits(id TEXT PRIMARY KEY,source_id TEXT NOT NULL,item_id TEXT NOT NULL,packet_id TEXT NOT NULL,body TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS credit_codings(id TEXT PRIMARY KEY,credit_id TEXT NOT NULL,created_at TEXT NOT NULL,body TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS credit_coding_heads(credit_id TEXT PRIMARY KEY,coding_id TEXT NOT NULL);
"""


def native_kind(native):
    return native.get("source_kind", "woo_refund")


def native_credits(native):
    return native.get("credits", [native["credit"]] if native.get("credit") else [])


def origin_key(native):
    if native_kind(native) == "merchant_adjustments":
        return digest(["merchant_adjustments", native["source_identity"]])
    p = native["purchase"]
    return digest([p["site_url"], p["order_reference"], p["transfer_identity"]])


def credit_identity(native, purchase, credit):
    if native_kind(native) == "merchant_adjustments":
        return "credit-" + digest(["merchant_adjustments", credit["network"], credit["adjustment_id"]])
    return "credit-" + digest([purchase["site_url"], credit["adjustment_id"]])


def credit_native_basis(native, credit):
    fields = ("adjustment_id", "order_reference", "event_id", "original_transaction", "amount", "network",
              "asset", "payer", "recipient", "transaction", "transfer_identity", "observation_sha256",
              "currency", "store_amount", "input_sha256")
    if native_kind(native) == "woo_refund":
        return digest({k: credit[k] for k in fields})
    return digest({k: credit.get(k) for k in fields} | {"source_kind": "merchant_adjustments",
                  "request_sha256": credit["request_sha256"]})


def packet_summary(value):
    native = value["native"]
    credits = native_credits(native)
    return {k: value.get(k) for k in ("id", "status", "manifest_sha256", "created_at", "reviewed_at",
             "operator", "reason", "name", "data_context", "provenance", "source_id", "credit_id", "credit_ids", "item_id")} | {
             "source_kind": native_kind(native), "source_directory": native["source_directory"],
             "source_file": native.get("source_file"), "source_sha256": native.get("source_sha256"),
             "source_reference": native.get("source_reference"), "site_url": native.get("site_url"),
             "manifest_kind": native.get("manifest_kind", "ORIGINAL_MERCHANT_MANIFEST"),
             "purchase": native.get("purchase"), "credit": credits[0] if credits else None, "credits": credits,
             "adjustments": native.get("adjustments", []), "original_event": native.get("original_event"),
             "payment_status": native.get("payment_status"), "receipt": native["receipt"],
             "files": [{k: f[k] for k in ("name", "bytes", "sha256")} for f in native["files"]]}


class CreditStore:
    def _data_context(self):
        row = self.connection.execute("SELECT value FROM meta WHERE key='data_context'").fetchone()
        return row[0] if row else ("operational" if self.connection.execute("SELECT COUNT(*) FROM sources").fetchone()[0] else "")

    def _context(self, selected, commit=False):
        selected = data_context(selected)
        current = self._data_context()
        if current and current != selected:
            raise Problem("SEPARATE_DATA_CONTEXT", "This workspace contains " + current + " records. Use a separate workspace for " + selected + " inputs", 409)
        if commit and not current:
            self.connection.execute("INSERT INTO meta VALUES('data_context',?) ON CONFLICT(key) DO UPDATE SET value=excluded.value", (selected,))
        return selected

    def _packet(self, ident):
        row = self.connection.execute("SELECT body FROM refund_packets WHERE id=?", (ident,)).fetchone()
        if row is None:
            raise Problem("REFUND_PACKET_NOT_FOUND", "Select an original retained return receipt", 404)
        return json.loads(row[0])

    def refund_packets(self, offset=0, limit=50):
        from store import page
        with self.lock:
            values = [packet_summary(json.loads(row[0])) for row in self.connection.execute(
                "SELECT body FROM refund_packets ORDER BY created_at DESC,id DESC")]
            return page(values, offset, limit)

    def refund_packet(self, ident):
        with self.lock:
            value = packet_summary(self._packet(ident))
            value["matching_purchases"] = [{"id": item["id"], "source_name": item["source_name"],
                "request_id": item["row"]["request_id"], "coding_status": item["status"]}
                for item in self._items() if value["purchase"] and purchase_matches(item, value["purchase"])]
            return value

    def refund_original(self, ident):
        with self.lock:
            native = self._packet(ident)["native"]
            output = io.BytesIO()
            with zipfile.ZipFile(output, "w", zipfile.ZIP_DEFLATED) as archive:
                def member(name, raw):
                    item = zipfile.ZipInfo(name); item.create_system = 3
                    item.external_attr = 0o100600 << 16; item.compress_type = zipfile.ZIP_DEFLATED
                    archive.writestr(item, raw)
                manifest_name = "buyer-selection.json" if native.get("manifest_kind") == "BUYER_INTAKE_SELECTION" else "original/manifest.json"
                member(manifest_name, base64.b64decode(native["manifest_base64"], validate=True))
                for entry in native["files"]:
                    member("original/" + entry["name"], base64.b64decode(entry["base64"], validate=True))
                member("buyer-intake.json", (canonical(packet_summary(self._packet(ident))) + "\n").encode())
            return output.getvalue()

    def _capture_receipt(self, payload, expected, reader, source_kind):
        name = text(payload.get("name"), "Original receipt source name", maximum=160)
        provenance = text(payload.get("provenance"), "Original operation provenance", maximum=6000)
        context = data_context(payload.get("data_context"))
        with self.lock:
            self._context(context)
            if self.revision() != expected:
                raise Problem("WORKSPACE_CHANGED", "Refresh the original workspace before capturing this receipt", 409)
            native = reader()
            manifest = native["manifest_sha256"]
            existing = self.connection.execute("SELECT id FROM refund_packets WHERE manifest_sha256=?", (manifest,)).fetchone()
            if existing:
                saved = self._packet(existing[0])
                if saved["data_context"] != context or native_kind(saved["native"]) != source_kind:
                    raise Problem("REFUND_SOURCE_CHANGED", "The same original receipt has a different retained context", 409)
                if source_kind == "woo_refund" and saved["native"]["site_url"] != native["site_url"]:
                    raise Problem("REFUND_SOURCE_CHANGED", "The same original packet has another store binding", 409)
                return self._change(expected, "refund.capture.reopen", lambda: packet_summary(saved))
            def operation():
                self._context(context)
                value = {"id": identifier("refund-packet"), "status": "PENDING", "created_at": now(),
                         "manifest_sha256": manifest, "name": name, "data_context": context,
                         "provenance": provenance, "native": native}
                self.connection.execute("INSERT INTO refund_packets VALUES(?,?,?,?,?)",
                    (value["id"], manifest, value["status"], value["created_at"], canonical(value)))
                return packet_summary(value)
            return self._change(expected, "refund.capture", operation)

    def capture_refund(self, payload, expected):
        directory = text(payload.get("directory"), "Original refund handoff directory", maximum=4096)
        site = text(payload.get("site_url"), "Original store URL", maximum=2048)
        manifest = text(payload.get("manifest_sha256"), "Original manifest SHA-256", maximum=64)
        return self._capture_receipt(payload, expected, lambda: capture_refund(
            directory, manifest, site, self.root / "refund-intake" / manifest, self.node_executable), "woo_refund")

    def capture_adjustments(self, payload, expected):
        source_file = text(payload.get("source_file"), "Original accounting-export file", maximum=4096)
        source_sha = text(payload.get("source_sha256"), "Original export SHA-256", maximum=64)
        event_id = text(payload.get("event_id"), "Original accounting event ID", maximum=64)
        return self._capture_receipt(payload, expected, lambda: read_adjustments(
            source_file, source_sha, event_id, payload.get("expected_job"), self.node_executable), "merchant_adjustments")

    def decide_refund(self, ident, payload, expected):
        decision = payload.get("decision")
        if decision not in ("ACCEPT", "REJECT"):
            raise Problem("REFUND_DECISION", "Accept or reject the retained original receipt")
        owner = text(payload.get("operator"), "Buyer source reviewer", maximum=240)
        reason = text(payload.get("reason"), "Buyer source decision", maximum=4000)
        def operation():
            packet = self._packet(ident)
            if packet["status"] != "PENDING":
                raise Problem("REFUND_REVIEWED", "This receipt already has a retained decision", 409)
            native = packet["native"]
            packet.update(status="ACCEPTED" if decision == "ACCEPT" else "REJECTED",
                          operator=owner, reason=reason, reviewed_at=now())
            if decision == "ACCEPT":
                self._context(packet["data_context"], commit=True)
                kind, p, returns = native_kind(native), native.get("purchase"), native_credits(native)
                if kind == "merchant_adjustments":
                    from native_adjustments import purchase_row, purchase_capture
                else:
                    from native_woo import purchase_row, purchase_capture
                origin = origin_key(native)
                source = next((s for s in self._bodies("sources") if s.get("credit_origin_key") == origin), None)
                requested = payload.get("purchase_item_id") or None
                linked = source.get("linked_purchase_item") if source and source.get("purchase_item_id") else requested
                item_id = source.get("purchase_item_id") if source else None
                if p is None:
                    if requested or payload.get("register_original_purchase") is True or returns:
                        raise Problem("ORIGINAL_PAYMENT_PROOF_REQUIRED", "This source records the merchant decision without a complete original payment proof. Accept its reference without registering an expense.", 409)
                else:
                    if item_id:
                        if requested and requested != item_id:
                            raise Problem("CREDIT_PURCHASE_LINK", "This original payment already binds to its retained buyer row", 409)
                        if not purchase_matches(self.item(item_id), p):
                            raise Problem("CREDIT_PURCHASE_LINK", "This receipt differs from the previously accepted original buyer payment", 409)
                    elif requested and not purchase_matches(self.item(requested), p):
                        raise Problem("CREDIT_PURCHASE_LINK", "Select the exact original payment event, parties, asset and amount", 409)
                    other_bindings = [c for c in self._credit_views() if c["purchase"]["transfer_identity"] == p["transfer_identity"]]
                    if other_bindings:
                        original_item = other_bindings[0]["item_id"]
                        if (requested and requested != original_item) or (item_id and item_id != original_item):
                            raise Problem("CREDIT_PURCHASE_LINK", "This original payment already has returns bound to another expense row", 409)
                        if not item_id:
                            linked = original_item
                    if not item_id and not linked and payload.get("register_original_purchase") is not True:
                        raise Problem("CREDIT_PURCHASE_SELECTION", "Choose the matching buyer payment or explicitly register the reviewed original purchase")
                if source is None:
                    source = {"id": identifier("source"), "name": packet["name"], "kind": kind,
                              "path": native.get("source_file", native["source_directory"]),
                              "identity": {"purchase_identity": origin}, "credit_origin_key": origin,
                              "immutable_intake": True, "data_context": packet["data_context"], "provenance": packet["provenance"],
                              "created_at": now(), "current_capture": None, "linked_purchase_item": linked,
                              "purchase_item_id": None}
                if p and not item_id:
                    item_id = linked or row_key(source["id"], purchase_row(native, packet["data_context"])["request_id"])
                    source.update(purchase_item_id=item_id, linked_purchase_item=linked)
                source["latest_refund_packet"] = ident
                self._put("sources", source)
                credit_ids = []
                for n in returns:
                    credit_id = credit_identity(native, p, n)
                    previous = self.connection.execute("SELECT body FROM credits WHERE id=?", (credit_id,)).fetchone()
                    previous = json.loads(previous[0]) if previous else None
                    native_basis = credit_native_basis(native, n)
                    if previous and (previous["native_basis"] != native_basis or previous["item_id"] != item_id or
                                     previous["data_context"] != packet["data_context"]):
                        raise Problem("ORIGINAL_REFUND_CHANGED", "The same original adjustment changed its immutable payment, amount or buyer binding", 409)
                    value = {"id": credit_id, "source_id": source["id"], "item_id": item_id, "packet_id": ident,
                             "manifest_sha256": packet["manifest_sha256"], "native": n, "purchase": p,
                             "native_basis": native_basis, "data_context": packet["data_context"],
                             "created_at": previous["created_at"] if previous else packet["created_at"],
                             "packet_history": (previous.get("packet_history", []) if previous else []) + [ident]}
                    self.connection.execute("INSERT INTO credits VALUES(?,?,?,?,?) ON CONFLICT(id) DO UPDATE SET packet_id=excluded.packet_id,body=excluded.body",
                        (credit_id, source["id"], item_id, ident, canonical(value)))
                    credit_ids.append(credit_id)
                packet.update(source_id=source["id"], credit_id=credit_ids[0] if credit_ids else None,
                              credit_ids=credit_ids, item_id=item_id)
                packets = [{"id": row["id"], "manifest_sha256": row["manifest_sha256"]}
                           for row in (json.loads(r[0]) for r in self.connection.execute("SELECT body FROM refund_packets WHERE status='ACCEPTED' ORDER BY created_at,id"))
                           if row.get("source_id") == source["id"]]
                packets.append({"id": ident, "manifest_sha256": packet["manifest_sha256"]})
                # A reference-only successor does not remove an already retained
                # independently proved purchase or relabel it as newly observed.
                if p or not source.get("purchase_item_id"):
                    captured = self._new_capture(source, purchase_capture(native, source, packets, source["linked_purchase_item"]))
                    captured = self._get("captures", captured["id"])
                    self._accept_capture(captured, source)
                    captured.update(status="ACCEPTED", operator=owner, reason=reason, reviewed_at=packet["reviewed_at"])
                    self.connection.execute("UPDATE captures SET status='ACCEPTED',body=? WHERE id=?", (canonical(captured), captured["id"]))
            self.connection.execute("UPDATE refund_packets SET status=?,body=? WHERE id=?", (packet["status"], canonical(packet), ident))
            return packet_summary(packet)
        return self._change(expected, "refund." + decision.lower(), operation)

    def _credit_views(self):
        purchases = {item["id"]: item for item in self._items()}
        sources = {s["id"]: s for s in self._bodies("sources")}
        heads = {row["credit_id"]: json.loads(row["body"]) for row in self.connection.execute(
            "SELECT h.credit_id,c.body FROM credit_coding_heads h JOIN credit_codings c ON c.id=h.coding_id")}
        latest = {s["id"]: {n["adjustment_id"]: n for n in self._packet(s["latest_refund_packet"])["native"]["adjustments"]}
                  for s in sources.values() if s.get("kind") == "merchant_adjustments" and s.get("latest_refund_packet")}
        values = []
        for row in self.connection.execute("SELECT body FROM credits ORDER BY id"):
            value = json.loads(row[0]); source = sources[value["source_id"]]
            value.update(source_name=source["name"], capture_id=source["current_capture"],
                         coding=heads.get(value["id"]),
                         present_in_latest_receipt=value["native"]["adjustment_id"] in latest[source["id"]] if source["id"] in latest else True)
            current_decision = latest.get(source["id"], {}).get(value["native"]["adjustment_id"])
            value["latest_source_status"] = current_decision["status"] if current_decision else None
            value["latest_source_eligibility"] = current_decision.get("eligibility") if current_decision else None
            value["basis"] = coding_basis(value, purchases.get(value["item_id"]))
            value["status"] = "UNCODED" if not value["coding"] else "CODED" if value["coding"]["basis"] == value["basis"] else "STALE"
            values.append(value)
        return values

    def credits(self, offset=0, limit=50):
        from store import page
        with self.lock:
            return page(self._credit_views(), offset, limit)

    def credit(self, ident):
        with self.lock:
            value = next((c for c in self._credit_views() if c["id"] == ident), None)
            if value is None:
                raise Problem("CREDIT_NOT_FOUND", "Select a retained original buyer credit", 404)
            value["purchase_item"] = self.item(value["item_id"])
            value["coding_history"] = [json.loads(row[0]) for row in self.connection.execute(
                "SELECT body FROM credit_codings WHERE credit_id=? ORDER BY created_at DESC,id DESC", (ident,))]
            value["related_credits"] = [{"id": c["id"], "adjustment_id": c["native"]["adjustment_id"],
                "amount": c["native"]["amount"], "coding": c.get("coding")} for c in self._credit_views()
                if c["item_id"] == value["item_id"] and c["id"] != ident]
            return value

    def save_credit_coding(self, ident, payload, expected):
        def operation():
            credit = self.credit(ident)
            value = validate_credit_coding(credit, payload, credit["purchase_item"],
                {c["id"]: c for c in self._bodies("centers")}, self._credit_views())
            dates = [value["recognition_date"]]
            if credit.get("coding"):
                dates.append(credit["coding"]["recognition_date"])
            if any(p["state"] == "CLOSED" and any(p["from_day"] <= d <= p["through_day"] for d in dates) for p in self._bodies("periods")):
                raise Problem("PERIOD_CLOSED", "Reopen the affected original period before changing a return allocation", 409)
            value.update(id=identifier("credit-coding"), created_at=now(),
                         previous=credit["coding"]["id"] if credit.get("coding") else None)
            self.connection.execute("INSERT INTO credit_codings VALUES(?,?,?,?)", (value["id"], ident, value["created_at"], canonical(value)))
            self.connection.execute("INSERT INTO credit_coding_heads VALUES(?,?) ON CONFLICT(credit_id) DO UPDATE SET coding_id=excluded.coding_id",
                                    (ident, value["id"]))
            return value
        return self._change(expected, "credit.code", operation)

    def _credit_period(self, view):
        closed = []
        for period in self._bodies("periods"):
            if period["id"] == view["period"]["id"] or period["state"] != "CLOSED" or not period.get("latest_close"):
                continue
            doc = self._get("closes", period["latest_close"])
            for line in doc.get("credit_allocations", []):
                closed.append({k: line[k] for k in ("credit_id", "item_id", "transfer_identity", "recognition_date", "amount")} |
                              {"period_id": period["id"], "close_id": doc["id"]})
        pending = [json.loads(r[0]) for r in self.connection.execute("SELECT body FROM refund_packets WHERE status='PENDING' ORDER BY id")]
        return credit_period(view, self._credit_views(), pending, self._items(),
            {c["id"]: c for c in self._bodies("centers")}, self._dispositions(view["period"]["id"]), closed, self._data_context(), self._adjustment_outcomes())

    def _adjustment_outcomes(self):
        result = []
        for source in self._bodies("sources"):
            ident = source.get("latest_refund_packet")
            if source.get("kind") != "merchant_adjustments" or not ident:
                continue
            packet = self._packet(ident)
            native = packet["native"]
            common = {"packet_id": ident, "source_id": source["id"], "source_name": source["name"],
                      "source_capture": source["current_capture"], "manifest_sha256": packet["manifest_sha256"],
                      "source_sha256": native["source_sha256"], "event_id": native["source_identity"]["event_id"],
                      "data_context": packet["data_context"], "payment_status": native["payment_status"],
                      "source_reference": native["source_reference"],
                      "network": native["original_event"]["network"], "asset_digest": native["original_event"]["assetDigest"],
                      "merchant_totals": native["receipt"]["totals"]}
            if native["adjustments"]:
                result.extend(common | row for row in native["adjustments"])
            else:
                result.append(common | {"kind": "ORIGINAL_EVENT", "status": "NO_ADJUSTMENT", "adjustment_id": None,
                                         "amount": None, "native_verified": False, "eligible_return": False})
        return result

    def _issued_refund_packets(self, report):
        rows = report.get("merchant_credit_outcomes", []) + report.get("merchant_adjustment_outcomes", [])
        ids = sorted({row["packet_id"] for row in rows})
        return [self._packet(ident) for ident in ids]

"""Expense coding and period views over original native statement rows."""
from __future__ import annotations

import hashlib
import json
import re
from datetime import datetime, timezone
from uuid import uuid4
from native import COLUMNS, utc_day

SCHEMA = "stellar-forge.buyer-expense-workspace.v1"
INTEGER = re.compile(r"(?:0|[1-9][0-9]{0,99})")


class Problem(ValueError):
    def __init__(self, code, message, status=400):
        super().__init__(message)
        self.code, self.status = code, status


def now():
    return datetime.now(timezone.utc).isoformat()


def canonical(value):
    return json.dumps(value, ensure_ascii=True, sort_keys=True, separators=(",", ":"))


def digest(value):
    return hashlib.sha256(canonical(value).encode()).hexdigest()


def identifier(prefix):
    return prefix + "-" + str(uuid4())


def text(value, label, *, maximum=1000, optional=False):
    if not isinstance(value, str):
        raise Problem("INVALID_TEXT", label + " must be text")
    value = value.strip()
    if (not value and not optional) or len(value) > maximum or any(ord(c) < 32 and c not in "\n\t" for c in value):
        raise Problem("INVALID_TEXT", label + " is empty, too long, or contains control characters")
    return value


def day(value):
    try:
        return utc_day(value)
    except (ValueError, TypeError) as exc:
        raise Problem("INVALID_DATE", "Use a complete calendar date in YYYY-MM-DD form") from exc


def amount(value):
    if not isinstance(value, str) or INTEGER.fullmatch(value) is None:
        raise Problem("INVALID_AMOUNT", "Enter an exact nonnegative base-unit integer as text")
    return int(value)


def row_key(source_id, request_id):
    return digest([source_id, request_id])


def basis(row, missing=False):
    value = {"row": {key: row[key] for key in COLUMNS}, "missing": bool(missing)}
    if row.get("native_context_sha256"):
        value["native_context_sha256"] = row["native_context_sha256"]
    return digest(value)


def native_changes(previous, current):
    before = {r["request_id"]: r for r in (previous or {}).get("rows", [])}
    after = {r["request_id"]: r for r in current["rows"]}
    changes = []
    for request_id in sorted(before.keys() | after.keys()):
        a, b = before.get(request_id), after.get(request_id)
        if a is None:
            changes.append({"request_id": request_id, "kind": "ADDED", "before": None, "after": b})
        elif b is None:
            changes.append({"request_id": request_id, "kind": "ABSENT", "before": a, "after": None})
        elif any(a.get(k) != b.get(k) for k in (*COLUMNS, "native_context_sha256")):
            changes.append({"request_id": request_id, "kind": "CHANGED", "before": a, "after": b,
                            "fields": [k for k in (*COLUMNS, "native_context_sha256") if a.get(k) != b.get(k)]})
    return changes


def validate_coding(item, payload, centers):
    row = item["row"]
    if item["missing"] or row["state"] != "settled":
        raise Problem("NATIVE_SETTLEMENT_REQUIRED", "Code a present, settled native row; review other rows as period exceptions")
    if payload.get("basis") != item["basis"]:
        raise Problem("ROW_CHANGED", "The native row changed. Review its current values before saving", 409)
    recognition = day(payload.get("recognition_date"))
    allocations = payload.get("allocations")
    if not isinstance(allocations, list) or not 1 <= len(allocations) <= 100:
        raise Problem("INVALID_ALLOCATIONS", "Add one to 100 allocation lines")
    normalized = []
    total = 0
    for line in allocations:
        if not isinstance(line, dict):
            raise Problem("INVALID_ALLOCATIONS", "Each allocation must be an object")
        center = centers.get(line.get("center_id"))
        if center is None or not center["active"]:
            raise Problem("COST_CENTER_REQUIRED", "Choose an active cost center for each line")
        value = amount(line.get("amount"))
        total += value
        normalized.append({"center_id": center["id"], "amount": str(value),
                           "project": text(line.get("project", ""), "Project", maximum=160, optional=True),
                           "account_code": text(line.get("account_code", ""), "Account code", maximum=120, optional=True),
                           "memo": text(line.get("memo", ""), "Line memo", maximum=1000, optional=True)})
    if total != int(row["settled_base_units"]):
        raise Problem("ALLOCATION_TOTAL", "Allocation lines must equal the native settled actual of " + row["settled_base_units"] + " base units")
    return {"item_id": item["id"], "basis": item["basis"], "recognition_date": recognition,
            "memo": text(payload.get("memo", ""), "Expense memo", maximum=4000, optional=True),
            "operator": text(payload.get("operator"), "Coding owner", maximum=240), "allocations": normalized}


def group_amounts(lines, dimensions=()):
    groups = {}
    for line in lines:
        key = tuple(line[k] for k in ("network", "asset", *dimensions))
        entry = groups.setdefault(key, {k: line[k] for k in ("network", "asset", *dimensions)} | {"amount": 0, "lines": 0})
        entry["amount"] += int(line["amount"])
        entry["lines"] += 1
    return [value | {"amount": str(value["amount"])} for _, value in sorted(groups.items())]


def spending_reservation_identity(ledger, request_id, request_digest):
    """One original physical ledger row, retained across its financial source views."""
    if not isinstance(ledger, dict) or set(ledger) != {"device", "inode"} or not all(
            isinstance(value, (str, int)) and str(value).isdigit() for value in ledger.values()):
        return None
    if not isinstance(request_id, str) or not request_id or not isinstance(request_digest, str) or not re.fullmatch(r"[0-9a-f]{64}", request_digest):
        return None
    return {"ledger": {key: str(ledger[key]) for key in ("device", "inode")},
            "request_id": request_id, "request_digest": request_digest}


def period_view(period, items, sources, centers, dispositions, closed_transfers=None):
    """Dates are operator recognition dates; native days never become settlement dates."""
    start, through = period["from_day"], period["through_day"]
    source_views = [{**{k: s.get(k) for k in ("id", "name", "kind", "path", "current_capture", "capture_time", "projection_sha256", "journal_events", "last_sequence", "record_kind", "source_basis", "date_basis", "data_context", "immutable_intake")},
                     **({k:s.get(k) for k in ("spending_owner","ledger_state","reservation_ledger_identity","unlinked_spending_exposures","source_issues","source_notes")} if s.get("kind") == "governed_mcp" else {})}
                    for s in sources]
    issues, candidates, exposures, native_outcomes = [], [], [], []
    disposition_by_key = {(d["item_id"], d["code"]): d for d in dispositions}
    closed_transfers = sorted(closed_transfers or [], key=lambda v:(v["period_id"], v["close_id"], v["item_id"]))
    previously_issued, previously_reserved = {}, {}
    for entry in closed_transfers:
        if entry.get("transfer_identity"):
            previously_issued.setdefault(entry["transfer_identity"], []).append(entry)
        if entry.get("spending_reservation"):
            previously_reserved.setdefault(digest(entry["spending_reservation"]), []).append(entry)
        for historical in entry.get("spending_reservation_history", []):
            previously_reserved.setdefault(digest(historical["identity"]), []).append(entry)

    def issue(code, item, description, *, group=None, kinds=None):
        item_id = item["id"] if item else ""
        selected = disposition_by_key.get((item_id, code))
        issue_basis = digest({"code": code, "basis": item["basis"] if item else None, "group": group})
        allowed = ["carry_forward", "exclude_from_period"] if kinds is None else kinds
        valid = bool(selected and selected["basis"] == issue_basis and selected["kind"] in allowed)
        result = {"code": code, "item_id": item_id, "request_id": item["row"]["request_id"] if item else None,
                  "source_name": item.get("source_name") if item else None, "description": description,
                  "source_capture": item.get("capture_id") if item else None,
                  "basis": issue_basis, "allowed_kinds": allowed, "resolved": valid,
                  "disposition": selected if valid else None, "group": group}
        issues.append(result)
        return result

    for source in sources:
        if source.get("source_issues"):
            issue("GOVERNED_SOURCE_" + source["id"], None,
                  source["name"] + " retains original native bindings that need source recovery before financial attribution",
                  group={"source_id":source["id"],"issues":source["source_issues"]}, kinds=[])
        if source.get("pending"):
            issue("SOURCE_REVIEW_" + source["id"], None, source["name"] + " has captured source awaiting acceptance or rejection",
                  group={"source_id": source["id"], "captures": source["pending"]}, kinds=[])
        elif not source.get("current_capture"):
            issue("SOURCE_CAPTURE_" + source["id"], None, source["name"] + " has no accepted native capture",
                  group={"source_id": source["id"]}, kinds=[])

    governed_present = any(s.get("kind") == "governed_mcp" for s in sources)
    source_by_id = {s["id"]:s for s in sources}
    ledger_observations = {}
    seen_reservation_issues = set()

    def reservation_key(source, request_id, request_digest, missing=False):
        if not governed_present or missing or not source:
            return None
        identity = source.get("reservation_ledger_identity")
        if not isinstance(identity, dict) or set(identity) != {"device","inode"}:
            return None
        return (str(identity["device"]),str(identity["inode"]),request_id,request_digest)

    def item_reservation_key(item):
        source=source_by_id.get(item["source_id"])
        if not source or source.get("current_capture") != item["capture_id"]:
            return None
        row=item["row"]
        if row.get("source_kind") == "governed_mcp" and not row.get("native_detail", {}).get("spending_state"):
            return None
        if row.get("source_kind", "sf36_ledger") not in ("sf36_ledger","governed_mcp"):
            return None
        return reservation_key(source,row["request_id"],row["request_digest"],item["missing"])

    def observe_ledger(key, entry):
        if key is not None:
            ledger_observations.setdefault(key, []).append(entry)

    def original_contributions(key):
        return sorted(ledger_observations.get(key, []), key=lambda entry:(entry["source_id"],entry["item_id"]))

    for item in items:
        row=item["row"];key=item_reservation_key(item)
        if key is not None and row["day"] <= through:
            detail=row.get("native_detail", {})
            observe_ledger(key,{"item_id":item["id"],"source_id":item["source_id"],"source_name":item["source_name"],
                "source_capture":item["capture_id"],"basis":item["basis"],"native_state":detail.get("spending_state",row["state"]),
                "network":row["network"],"asset":row["asset"],"native_reservation_day":row["day"],
                "maximum":row["amount"],"actual":row["actual"],"reserved_base_units":row["reserved_base_units"],
                "request_id":row["request_id"],"request_digest":row["request_digest"]})

    for source in sources:
        for selected in source.get("unlinked_spending_exposures", []):
            if selected["native_reservation_day"] > through:
                continue
            key=reservation_key(source,selected["request_id"],selected["request_digest"])
            observe_ledger(key,{"item_id":"","source_id":source["id"],"source_name":source["name"],
                "source_capture":source["current_capture"],"basis":digest(selected),"native_state":selected["state"],
                "network":selected["network"],"asset":selected["asset"],
                "native_reservation_day":selected["native_reservation_day"],"maximum":selected["maximum"],
                "actual":selected["settled_actual"],"reserved_base_units":selected["amount"],
                "request_id":selected["request_id"],"request_digest":selected["request_digest"]})
            if int(selected["amount"]) > 0:
                exposures.append({"item_id":"","request_id":selected["request_id"],"source_name":source["name"],
                    "network":selected["network"],"asset":selected["asset"],"amount":selected["amount"],
                    "native_reservation_day":selected["native_reservation_day"],"missing":False,
                    "source_capture":source["current_capture"],"request_digest":selected["request_digest"],
                    "attribution":"UNVERIFIED_NATIVE_LINK","_reservation_key":key})
    for key, entries in ledger_observations.items():
        projections={(e["network"],e["asset"],e["native_state"],e["maximum"],e["actual"],e["native_reservation_day"])
                     for e in entries}
        if len(projections) > 1:
            issue("SPENDING_CAPTURE_DIVERGENCE_"+digest(key)[:16],None,
                "Accepted views of the same original spending reservation disagree. Refresh and review the original source editions together.",
                group={"ledger_identity":{"device":key[0],"inode":key[1]},"request_id":key[2],
                       "request_digest":key[3],"sources":original_contributions(key)},kinds=[])

    def receipt_key(row):
        ref = row.get("receipt_ref", "")
        matched = re.fullmatch(re.escape(row["network"]) + r"/([0-9a-fA-F]{64})", ref)
        if matched:
            ref = row["network"] + "/" + matched.group(1).lower()
        elif re.fullmatch(r"[0-9a-fA-F]{64}", ref):
            ref = row["network"] + "/" + ref.lower()
        return (row["network"], row["asset"], ref)

    receipt_groups, exact_transfers, exact_spending = {}, {}, {}
    for item in items:
        row = item["row"]
        if row["state"] == "settled" and row.get("receipt_ref") and not item["missing"]:
            key = receipt_key(row)
            receipt_groups.setdefault(key, []).append(item)
            transfer = row.get("native_detail", {}).get("transfer_identity")
            if transfer:
                exact_transfers.setdefault(transfer, []).append(item)
            spending_key = item_reservation_key(item)
            if spending_key is not None:
                exact_spending.setdefault(spending_key, []).append(item)

    for item in items:
        row, coding = item["row"], item.get("coding")
        relevant = row["day"] <= through or bool(coding and start <= coding["recognition_date"] <= through)
        if not relevant:
            continue
        detail = row.get("native_detail")
        source = source_by_id.get(item["source_id"], {})
        original_reservation = (spending_reservation_identity(source.get("reservation_ledger_identity"), row["request_id"], row["request_digest"])
            if row.get("source_kind", "sf36_ledger") in ("sf36_ledger", "governed_mcp") and
            source.get("current_capture") == item["capture_id"] and not item["missing"] else None)
        if isinstance(detail, dict):
            native_outcomes.append({"item_id":item["id"], "request_id":row["request_id"], "source_name":item["source_name"],
                "source_capture":item["capture_id"], "quote_day":detail.get("quote_created_day",row["day"]), "native_status":detail["native_status"],
                "payment_classification":detail["classification"], "network":row["network"], "asset":row["asset"],
                "quoted_amount":detail.get("quoted_amount"), "settled_actual":row["settled_base_units"],
                "receipt_ref":row["receipt_ref"], "observation_sha256":detail.get("observation_sha256"),
                "transfer_identity":detail.get("transfer_identity"), "payer":detail.get("payer"),
                "recipient":detail.get("recipient"), "result_file":detail.get("result_file"),
                "result_preview":detail.get("result_preview"),
                "result_file_status":(detail.get("result_file") or {}).get("status"),
                "result_file_sha256":(detail.get("result_file") or {}).get("sha256"),
                "result_file_bytes":(detail.get("result_file") or {}).get("bytes"),
                "result_preview_sha256":(detail.get("result_preview") or {}).get("bodySha256"),
                "result_preview_bytes":(detail.get("result_preview") or {}).get("bodyBytes"),
                "missing":item["missing"], "source_kind":row.get("source_kind", "sf36_ledger"),
                "data_context":detail.get("data_context", "operational"),
                "store_currency":detail.get("store_currency"), "store_amount":detail.get("store_amount"),
                **({key:detail.get(key) for key in ("spending_link","spending_state","spending_maximum","spending_actual",
                    "spending_reserved_base_units","spending_reservation_day","spending_request_sha256",
                    "spending_binding_sha256","spending_receipt_ref","spending_proof_sha256","finality_record_sha256",
                    "observed_settled_actual","spending_problems","spending_notes","unverified_spending_exposure")} if row.get("source_kind") == "governed_mcp" else {})})
        if row["state"] == "reserved" or (row.get("source_kind") == "governed_mcp" and int(row.get("reserved_base_units") or "0") > 0):
            exposures.append({"item_id": item["id"], "request_id": row["request_id"], "source_name": item["source_name"],
                              "network": row["network"], "asset": row["asset"], "amount": row["reserved_base_units"],
                              "native_reservation_day": row["day"], "missing": item["missing"],
                              "source_capture": item["capture_id"], "request_digest": row["request_digest"],
                              **({"_reservation_key":item_reservation_key(item)} if governed_present else {})})
        if item["missing"]:
            issue("ABSENT_FROM_CURRENT_SOURCE", item, "This original row is absent from the accepted source capture; its previous bytes remain retained")
            continue
        if row["state"] == "spending_review":
            issue("GOVERNED_SPENDING_BINDING", item,
                  "The retained quote, native approval or original ledger/finality disagree. Inspect the original buyer and refresh this source.",
                  group={"problems":row.get("native_detail", {}).get("spending_problems", [])}, kinds=[])
            continue
        if row["state"] == "reserved":
            key=item_reservation_key(item)
            if key is None or key not in seen_reservation_issues:
                contributing=original_contributions(key) if key is not None else []
                issue("UNRESOLVED_RESERVATION", item, "The original maximum remains reserved. Carry it for native finalization; it is not settled expense",
                    group={"sources":contributing} if len(contributing)>1 else None)
                if key is not None:
                    seen_reservation_issues.add(key)
            continue
        if row["state"] == "not_dispatched":
            continue
        if row["state"] == "failed":
            issue("FAILED_NATIVE_PAYMENT", item, "The original saved RPC observation reports this transaction failed. Record its period disposition; the quote amount is not an expense.")
            continue
        if row["state"] == "unresolved":
            issue("NATIVE_PAYMENT_UNRESOLVED", item, "The original buyer retains a signed dispatch without a matched transfer observation. Carry or exclude this quote while its original payment recovery continues; its quoted amount is not a spending reservation.")
            continue
        if row["state"] == "observation_review":
            issue("NATIVE_OBSERVATION_BINDING", item, "The saved original payment observation does not match this quote's retained native binding. Inspect the original buyer observation and refresh its source.", group={"source_id":item["source_id"]}, kinds=[])
            continue
        if coding and coding["recognition_date"] < start:
            if coding["basis"] != item["basis"]:
                issue("EARLIER_PERIOD_SOURCE_CHANGED", item, "The native row changed after earlier-date coding; review that original period")
            continue
        if coding and coding["recognition_date"] > through:
            if coding["basis"] != item["basis"]:
                issue("FUTURE_CODING_SOURCE_CHANGED", item, "The native row changed after future-date coding; update the allocation")
            continue
        if coding is None:
            issue("UNCODED_SETTLED_ROW", item, "Assign an accounting date and exact cost-center allocation, or record its disposition")
            continue
        if coding["basis"] != item["basis"]:
            issue("CODING_SOURCE_CHANGED", item, "The native row differs from the allocation's reviewed source; update coding or record its disposition")
            continue
        transfer_identity = row.get("native_detail", {}).get("transfer_identity")
        prior = previously_issued.get(transfer_identity, [])
        if original_reservation:
            prior = list({(value["period_id"], value["close_id"], value["item_id"]): value for value in
                [*prior, *previously_reserved.get(digest(original_reservation), [])]}.values())
        if prior:
            issue("TRANSFER_ALREADY_ISSUED", item,
                  "The same original transfer or spending reservation is included in another currently closed period. Exclude this representation, or reopen and correct the earlier period before recognising it here.",
                  group={"issued_charges":prior}, kinds=["exclude_from_period"])
            continue
        selected_lines = []
        for index, line in enumerate(coding["allocations"]):
            center = centers.get(line["center_id"])
            if center is None:
                raise Problem("COST_CENTER_MISSING", "A retained allocation references a missing cost center", 409)
            selected_lines.append({"item_id": item["id"], "source_id": item["source_id"], "source_name": item["source_name"],
                                   "request_id": row["request_id"], "request_digest": row["request_digest"],
                                   "native_reservation_day": row["day"] if row.get("source_kind", "sf36_ledger") == "sf36_ledger" else row.get("native_detail", {}).get("spending_reservation_day"),
                                   "native_source_day":row["day"], "native_date_basis":row.get("native_date_basis", "SF36 reservation day"),
                                   "source_kind":row.get("source_kind", "sf36_ledger"), "recognition_date": coding["recognition_date"],
                                   "network": row["network"], "asset": row["asset"], "scheme": row["scheme"],
                                   "settled_actual": row["settled_base_units"],
                                   "reserved_maximum":row["amount"] if row.get("source_kind", "sf36_ledger") == "sf36_ledger" else row.get("native_detail", {}).get("spending_maximum"),
                                   "quoted_amount":row.get("native_detail", {}).get("quoted_amount") if row.get("source_kind") in ("mcp_quote","governed_mcp") else None,
                                   "receipt_ref": row["receipt_ref"], "proof_sha256": row["proof_sha256"],
                                   "center_id": center["id"], "center_code": center["code"], "center_name": center["name"],
                                   "project": line["project"], "account_code": line["account_code"], "amount": line["amount"],
                                   "memo": line["memo"] or coding["memo"], "coding_id": coding["id"], "line": index + 1,
                                   "source_capture": item["capture_id"], "basis": item["basis"],
                                   "native_payment": row.get("native_detail"),
                                   "original_spending_reservation": original_reservation})
        group = receipt_groups.get(receipt_key(row), [])
        exact = exact_transfers.get(row.get("native_detail", {}).get("transfer_identity"), [])
        # The same original ledger row can be exposed directly and through its
        # governed quote. Its physical ledger and complete request identity make
        # this an exact duplicate even when the direct statement has no RPC object.
        spending_key = item_reservation_key(item)
        if spending_key is not None:
            exact = list({entry["id"]: entry for entry in
                [*exact, *exact_spending.get(spending_key, [])]}.values())
        exclude = False
        if len(group) > 1:
            same_transfer = len(exact) > 1
            shared = issue("SHARED_RECEIPT_REFERENCE", item,
                           "These original rows record the same native transfer event. Include one original charge and exclude duplicates." if same_transfer else
                           "More than one registered native row uses this transaction reference; review whether these are distinct charges or a duplicate source.",
                           group={"items": sorted([{"id": x["id"], "basis": x["basis"]} for x in group], key=lambda x: x["id"]),
                                  "same_transfer_items":sorted(x["id"] for x in exact) if same_transfer else []},
                           kinds=["include_original_charge", "exclude_from_period"] if same_transfer else ["separate_native_rows", "exclude_from_period"])
            exclude = bool(shared["resolved"] and shared["disposition"]["kind"] == "exclude_from_period")
        if not exclude:
            candidates.extend(selected_lines)

    # Two source rows with the same original native event cannot both become expense.
    included = {line["item_id"] for line in candidates}
    for values in [*exact_transfers.values(), *exact_spending.values()]:
        selected = included.intersection(item["id"] for item in values)
        if len(selected) > 1:
            for shared in issues:
                if shared["code"] == "SHARED_RECEIPT_REFERENCE" and shared["item_id"] in selected:
                    shared["resolved"] = False
                    shared["description"] = "The same original native transfer is still allocated more than once. Keep one included charge and exclude the duplicate source rows."
    # A native ledger and a governed MCP capture can expose one physical
    # reservation. Retain every source/capture reference and count its capacity
    # once. Conflicting original observations remain an unresolved source issue.
    merged_exposures={}
    unique_exposures=[]
    for exposure in exposures:
        key=exposure.pop("_reservation_key",None)
        if key is None:
            unique_exposures.append(exposure)
            continue
        financial_key=(*key,exposure["network"],exposure["asset"])
        if financial_key not in merged_exposures:
            merged_exposures[financial_key]=exposure
            unique_exposures.append(exposure)
            contributions=original_contributions(key)
            if len(contributions)>1:
                exposure["contributing_sources"]=contributions
                exposure["reservation_ledger_identity"]={"device":key[0],"inode":key[1]}
        else:
            saved=merged_exposures[financial_key]
            saved["amount"]=str(max(int(saved["amount"]),int(exposure["amount"])))
            if exposure.get("attribution")=="UNVERIFIED_NATIVE_LINK":
                saved["attribution"]="UNVERIFIED_NATIVE_LINK"
    exposures=unique_exposures
    unresolved = [x for x in issues if not x["resolved"]]
    context = {"period": {k: period[k] for k in ("id", "name", "from_day", "through_day", "generation")},
               "sources": source_views, "items": [{"id": i["id"], "basis": i["basis"], "coding": i.get("coding")} for i in items],
               "centers": sorted(centers.values(), key=lambda x: x["id"]), "dispositions": dispositions,
               "pending_sources": [{"id": s["id"], "pending": s.get("pending", [])} for s in sources],
               "closed_native_transfers":closed_transfers}
    return {"schema": "stellar-forge.buyer-expense-period.v1", "period": period, "source_captures": source_views,
            "context_sha256": digest(context), "ready": not unresolved, "issues": issues,
            "unresolved": len(unresolved), "allocations": candidates, "totals": group_amounts(candidates),
            "by_cost_center": group_amounts(candidates, ("center_code", "center_name")),
            "by_project": group_amounts(candidates, ("project",)), "outstanding_reservations": exposures,
            "outstanding_totals": group_amounts(exposures), "native_payment_outcomes":native_outcomes,
            "basis": "Original SF36 ledger projections, retained MCP quote/payment observations and original customer refund packets; each native operation retains its original provenance",
            "date_basis": "Operator-assigned recognition dates; original reservation or quote-creation days retain their own source meaning",
            "unit_basis": "Exact native base-unit strings, grouped by network and asset; no fiat conversion"}

